window.__Q=window.__Q||{};window.__Q["prev/6/A1"]=[{"q":"超抗原引起自身免疫病的机制是","o":["隐蔽抗原的释放","自身抗原的改变","交叉抗原的存在","免疫忽视的打破","分子模拟"],"a":3,"e":"超抗原多克隆激活大量T细胞并增强共刺激信号，使处于免疫忽视状态的自身反应性克隆被活化，从而打破免疫忽视诱发自身免疫病。"},{"q":"治疗性单克隆抗体一般不用于","o":["肿瘤","自身免疫性疾病","移植排斥反应","感染性疾病","免疫缺陷病"],"a":4,"e":"治疗性单抗用于肿瘤、自身免疫病、移植排斥和感染性疾病等，通过阻断靶分子或介导CDC、ADCC发挥作用；免疫缺陷病以补充缺失成分、干细胞移植和预防感染为主。"},{"q":"婴幼儿易感染含TI-2抗原的病原体的原因是","o":["婴幼儿体内的B1细胞不成熟","婴幼儿体内的B2细胞不成熟","婴幼儿体内的Th1细胞不成熟","婴幼儿体内的Th2细胞不成熟","婴幼儿体内的DC细胞不成熟"],"a":0,"e":"TI-2抗原仅能激活成熟B细胞，应答主要由B1细胞承担，而人B1细胞约5岁才发育成熟，故婴幼儿易感染含TI-2抗原的病原体。"},{"q":"抗IgE（Xolair）用于下列哪种疾病治疗","o":["持续性哮喘","斑块性银屑病","多发性硬化症","年龄相关性黄斑病变","类风湿关节炎"],"a":0,"e":"奥马珠单抗与IgE的Fc段结合，阻止IgE与肥大细胞、嗜碱性粒细胞表面FcεRⅠ结合，抑制其被变应原活化释放介质，用于持续性哮喘和慢性自发性荨麻疹。"},{"q":"B细胞表达的CD分子是","o":["CD2","CD8","CD16","CD19","CD28"],"a":3,"e":"CD19是B细胞特征性表面标志，与CD21、CD81组成BCR共受体；CD2、CD8、CD28为T细胞标志，CD16主要表达于NK细胞。"},{"q":"下列分子可以代替不适于体内免疫的抗原，如HIV和肿瘤，进行免疫，有利于发展特异和安全的免疫干预手段的是","o":["Ab1α","Ab1β","Ab2α","Ab2β","Ab3"],"a":3,"e":"Ab2β为抗独特型抗体中的内影像组，其可变区模拟原始抗原的空间构象，可代替HIV、肿瘤抗原等不宜体内免疫的抗原诱导特异性免疫应答。"},{"q":"关于浆细胞的描述错误的是","o":["来自B细胞","是B细胞分化的中间阶段","细胞质中富含粗面内质网","不再表达BCR","不再表达MHCⅡ类分子"],"a":1,"e":"浆细胞是B细胞分化的终末效应细胞，不再表达BCR和MHCⅡ类分子，胞质富含粗面内质网以大量合成和分泌抗体。"},{"q":"引起1型糖尿病的抗原属于","o":["异嗜性抗原","自身抗原","同种异型抗原","变应原","耐受原"],"a":1,"e":"1型糖尿病由胰岛β细胞自身抗原诱导自身反应性T细胞及抗体破坏β细胞所致，属器官特异性自身免疫病，其靶抗原本质为自身抗原。"},{"q":"临床上用于慢性乙型病毒性肝炎治疗的细胞因子首选","o":["IFN-α","IFN-β","IFN-γ","TGF-β","TNF-α"],"a":0,"e":"IFN-α为Ⅰ型干扰素，可诱导抗病毒蛋白合成、增强NK与CTL活性并调节免疫，是慢性乙型病毒性肝炎抗病毒治疗的首选细胞因子。"},{"q":"能直接杀伤肿瘤细胞的细胞因子是","o":["IL-1","IFN-α","TNF-α","IL-6","IL-4"],"a":2,"e":"TNF-α可直接与肿瘤细胞表面TNFR结合诱导其凋亡，并损伤肿瘤血管引起出血坏死；IFN-γ主要经激活巨噬细胞和NK细胞间接发挥抗肿瘤作用。"},{"q":"关于TI-2抗原说法错误的是","o":["细菌胞壁是TI-2抗原","荚膜多糖是TI-2抗原","对TI-2抗原应答的主要是B2细胞","仅能激活成熟B细胞","不能诱导抗体亲和力成熟"],"a":2,"e":"对TI-2抗原应答的主要是B1细胞而非B2，故该项错误；TI-2抗原多为细菌胞壁与荚膜多糖，仅激活成熟B细胞，不诱导亲和力成熟。"},{"q":"胸腺细胞经历阴性选择后获得了","o":["表达协同刺激分子的能力","杀伤靶细胞的能力","分泌细胞因子的能力","MHC限制性","自身耐受"],"a":4,"e":"胸腺内阴性选择清除自身反应性T细胞克隆，使成熟T细胞对自身抗原不应答，获得自身免疫耐受；阳性选择赋予MHC限制性。"},{"q":"人体免疫细胞产生、发育、分化成熟的场所是","o":["胸腺和淋巴结","胸腺和骨髓","淋巴结和脾","骨髓和黏膜免疫系统","脾和胸腺"],"a":1,"e":"骨髓和胸腺为中枢免疫器官，是免疫细胞发生、分化和发育成熟的场所；淋巴结、脾和黏膜淋巴组织为成熟T、B细胞定居和应答的外周场所。"},{"q":"刺激机体产生类风湿因子（RF）的抗原是","o":["变性IgA","变性IgD","变性IgE","变性IgG","变性IgM"],"a":3,"e":"自身IgG的Fc段变性后刺激机体产生抗变性IgG的自身抗体，即类风湿因子，多为IgM类，两者形成的免疫复合物沉积于关节滑膜致病。"},{"q":"CD8/CD4分别与MHCⅠ/Ⅱ类分子结合，可为T细胞活化","o":["提供第一信号","加强第一信号","提供第二信号","加强第二信号","提供抑制信号"],"a":1,"e":"CD4与MHCⅡ类分子、CD8与MHCⅠ类分子结合，作为共受体增强TCR与pMHC的亲和力，并借胞质区结合的激酶促进CD3的ITAM磷酸化，加强第一信号。"},{"q":"B1细胞具有鉴别意义的表面标志是","o":["CD5＋，mIgM＋","CD5－，mIgM＋","CD5＋，mIgM－","CD25＋，mIgM＋","CD25＋，mIgM－"],"a":0,"e":"B1细胞表达CD5和mIgM，CD5为其与B2细胞鉴别的标志；B2细胞为CD5阴性、mIgM阳性。"},{"q":"容易引起免疫耐受的抗原注射途径为","o":["静脉＞皮下、肌肉＞腹腔","腹腔＞皮下、肌肉＞静脉","腹腔＞静脉＞皮下、肌肉","静脉＞腹腔＞皮下、肌肉","皮下、肌肉＞腹腔＞静脉"],"a":3,"e":"诱导耐受由易到难依次为口服、静脉、腹腔、肌内、皮下或皮内，故静脉注射最易致耐受，皮下注射最难。"},{"q":"黏膜相关淋巴组织中的B细胞主要分泌","o":["IgG类抗体","IgA类抗体","IgE类抗体","IgM类抗体","IgD类抗体"],"a":1,"e":"黏膜相关淋巴组织的B细胞主要向IgA发生类别转换，在TGF-β等作用下分化为分泌IgA二聚体的浆细胞，经上皮转运为SIgA。"},{"q":"关于免疫复合物免疫调节作用的叙述，下列哪项是错误的","o":["免疫复合物与FDC表面的FcR和CR结合，供B细胞识别，诱发免疫应答","免疫复合物激活补体，经CR1介导的免疫黏附作用清除抗原","免疫应答后期，IgG类抗体形成的免疫复合物有增强免疫应答的作用","免疫应答初期，IgM类抗体形成的免疫复合物有增强免疫应答的作用","免疫复合物促进吞噬细胞对抗原的清除，抑制抗体的进一步产生"],"a":2,"e":"应答后期IgG类免疫复合物经FcγRⅡB与BCR交联，抑制B细胞活化及抗体产生；应答初期IgM类复合物经FDC捕获抗原则促进应答。"},{"q":"属于同种异型抗原的是","o":["甲胎蛋白","HLA血型物质","甲状腺球蛋白","肠毒素","外毒素"],"a":1,"e":"HLA抗原是同一种属不同个体间的同种异型抗原，人群中多态性最高，是移植排斥反应的主要抗原；甲胎蛋白和甲状腺球蛋白属自身抗原。"},{"q":"后天接触Ag致免疫耐受表述有误的是","o":["终生不被打破","Ag单体较其聚体容易","口服Ag可致免疫分离","耐受原表位有作用","Ag剂量不适宜"],"a":0,"e":"后天接触抗原诱导的免疫耐受并非终生不变，可随抗原消失而消退，再次接触抗原可恢复应答；抗原单体较其聚体更易诱导耐受。"},{"q":"浆细胞的主要储存场所是","o":["胸腺","骨髓","肝脏","脾","淋巴结"],"a":1,"e":"骨髓是各类血细胞生成和B细胞发育成熟的场所，再次免疫应答产生的长寿命浆细胞归巢并长期留存于骨髓，持续分泌抗体。"},{"q":"含有免疫效应分子的是","o":["白喉类毒素","破伤风抗毒素","卡介苗","百日咳疫苗","脊髓灰质炎疫苗"],"a":1,"e":"破伤风抗毒素含抗毒素抗体，是免疫效应分子，用于人工被动免疫；类毒素、卡介苗和疫苗均为诱导主动免疫的抗原制剂。"},{"q":"HIV侵入靶细胞时，与CD4分子结合的蛋白是","o":["gp21","gp41","gp120","p17","P24"],"a":2,"e":"HIV外膜糖蛋白gp120与靶细胞CD4结合，构象改变后暴露位点与CXCR4或CCR5结合，进而暴露gp41介导膜融合。"},{"q":"肿瘤细胞表面","o":["HLA-Ⅱ类抗原显著增加","HLA-Ⅰ类抗原显著增加","HLA-Ⅰ类抗原显著减少","HLA-Ⅲ类抗原显著增加","HLA-Ⅰ和Ⅱ类抗原表达均降低"],"a":2,"e":"官方题库缺失图片"},{"q":"下列关于IgG的叙述错误的是","o":["可分为四个亚类","可通过胎盘","抗原结合价为二价","CH2有补体C1q结合点","经木瓜蛋白酶水解后可获得F（ab'）2片段"],"a":4,"e":"木瓜蛋白酶水解IgG铰链区近N端，得到2个Fab和1个Fc；胃蛋白酶作用于近C端才产生F(ab′)2和pFc′。"},{"q":"抗CD20靶向治疗用于","o":["再生障碍性贫血","移植排斥反应","急性髓样白血病","B细胞淋巴瘤","类风湿关节炎"],"a":3,"e":"CD20表达于B细胞，利妥昔单抗与之结合后经补体依赖细胞毒和ADCC清除B细胞，用于治疗B细胞非霍奇金淋巴瘤，也用于清除B细胞治疗自身免疫病。"},{"q":"下列不属于诱导免疫耐受的方法的是","o":["应用IFN-γ诱导抗原提呈细胞上调MHCⅡ类分子表达","静脉注射抗原","应用自身抗原肽拮抗肽","阻断共刺激信号","过继输入抑制性免疫细胞"],"a":0,"e":"IFN-γ上调APC的MHCⅡ类分子和共刺激分子，增强抗原提呈并促进Th1和CTL应答，属增强免疫应答的措施；诱导耐受需阻断共刺激或输入抑制性细胞。"},{"q":"MHCⅠ类分子表达缺陷病患者常出现慢性呼吸道感染，实验室检查常显示CD8＋T分化发育障碍、数量减少和功能缺失，这是因为","o":["CD8＋T淋巴细胞不表达MHCⅠ类分子","CD4＋T淋巴细胞相对增多","CD4＋T淋巴细胞不表达MHCⅠ类分子","T细胞在胸腺发育过程中CD4＋CD8＋T细胞不能通过阴性选择分化为CD8＋T细胞","T细胞在胸腺发育过程中CD4＋CD8＋T细胞不能通过阳性选择分化为CD8＋T细胞"],"a":4,"e":"胸腺内CD4+CD8+双阳性细胞须与胸腺上皮细胞表面MHCⅠ类分子结合，才能经阳性选择分化为CD8+单阳性细胞；MHCⅠ类分子缺陷使该选择受阻。"},{"q":"CD4＋Th1细胞不产生下列哪项细胞因子","o":["IL-2","IL-4","IFN-γ","TNF","GM-CSF"],"a":1,"e":"Th1细胞主要分泌IFN-γ、TNF-α、IL-2和GM-CSF；IL-4是Th2细胞的特征性细胞因子，可诱导Th0向Th2分化并促进IgE类别转换。"},{"q":"与鼻咽癌发生有关的是","o":["CMV","HBV","HPV","EBV","SV40"],"a":3,"e":"EB病毒与B细胞淋巴瘤及鼻咽癌发生相关，其表达产物属致瘤病毒相关抗原；HBV、HCV与肝癌相关，HPV与宫颈癌相关，HTLV-1与成人T细胞白血病相关。"},{"q":"可促进Th1细胞进一步分化，同时抑制Th2细胞增生的细胞因子是","o":["IL-2","IL-4","IL-13","TNF-β","IFN-γ"],"a":4,"e":"IFN-γ促进Th0细胞向Th1分化，同时抑制Th2细胞增殖；IL-4作用相反，促进Th2分化并抑制Th1，二者相互拮抗。"},{"q":"关于免疫调节的正确叙述是","o":["协同刺激分子受体分为高亲和性的CD28和低亲和性的CTLA-4","协同刺激分子与CD28结合抑制免疫应答","协同刺激分子与CTLA-4结合促进免疫应答","CTLA-4的表达密度大于CD28的表达密度","活化的T细胞才能表达CTLA-4"],"a":4,"e":"CTLA-4为共抑制分子，仅在T细胞活化后表达，与CD80/CD86的亲和力显著高于CD28，竞争性结合后招募磷酸酶、下调或终止T细胞活化。"},{"q":"CD4分子存在于","o":["Th1、Tc细胞","Treg、CTL细胞","Th0、Th1、Th2细胞","所有成熟T细胞","肥大细胞"],"a":2,"e":"CD4是TCR共受体，表达于Th0、Th1、Th2、Th17、Tfh和Treg等CD4+T细胞；CTL表达CD8，B细胞、NK细胞和巨噬细胞不表达CD4。"},{"q":"可分泌穿孔素和颗粒酶的细胞有","o":["CTL细胞和B细胞","CTL细胞和NK细胞","B细胞和NK细胞","CTL细胞和巨噬细胞","B淋巴细胞和巨噬细胞"],"a":1,"e":"CTL与NK细胞活化机制不同，但均通过脱颗粒释放穿孔素、颗粒酶，并表达FasL、分泌LT-α杀伤靶细胞；B细胞和巨噬细胞不分泌穿孔素。"},{"q":"下列分子中，不参与蛋白质抗原加工提呈过程的是","o":["CD1","CD4","CD8","MHC","TCR"],"a":0,"e":"CD1提呈脂类抗原，不参与蛋白质抗原的加工提呈；蛋白质抗原由MHC分子提呈给TCR识别，CD4、CD8作为共受体参与。"},{"q":"对人体来说，乙型肝炎病毒表面抗原（HBsAg）不属于","o":["胸腺依赖性抗原","异种抗原","内源性抗原","天然抗原","异嗜性抗原"],"a":4,"e":"HBsAg是HBV的结构蛋白，对人体属异种抗原、天然抗原，也是胸腺依赖性抗原；异嗜性抗原指不同种属间的共同抗原，HBsAg不属此类。"},{"q":"由Ⅱ型超敏反应引起的自身免疫病是","o":["类风湿关节炎","系统性红斑狼疮","自身免疫性溶血性贫血","接触性皮炎","多发性硬化症"],"a":2,"e":"自身免疫性溶血性贫血由药物或病毒感染使红细胞膜抗原改变，刺激产生的抗体与红细胞结合并激活补体，导致红细胞溶解，属抗体介导的Ⅱ型超敏反应。"},{"q":"引起新生儿溶血症患儿红细胞溶解的抗体是","o":["天然的血型抗体IgA","免疫的血型抗体IgA","天然的血型抗体IgM","免疫的血型抗体IgM","免疫的血型抗体IgG"],"a":4,"e":"Rh阴性母亲受Rh阳性红细胞刺激产生IgG类抗Rh抗体，可经胎盘进入胎儿体内激活补体溶解红细胞；ABO输血反应由天然IgM介导。"},{"q":"下列细胞因子中，不属于促炎细胞因子的是","o":["IL-1","IL-6","IL-8","IL-12","MCP-1"],"a":2,"e":"IL-8属趋化因子，主要功能是趋化并活化中性粒细胞，与IL-1、IL-6、TNF-α等促炎细胞因子分属不同的功能类别。"},{"q":"单克隆抗体是指","o":["是指所有具有相同H链的抗体","是由突变的浆细胞产生","具有高度均一性","具有识别多种抗原决定簇之特点","对人体无免疫原性"],"a":2,"e":"单克隆抗体由单一B细胞克隆与骨髓瘤细胞融合形成的杂交瘤产生，只针对单一抗原表位，结构和特异性高度均一，可无限量制备。"},{"q":"临床上最常见的移植类型是","o":["自体移植","同种同基因移植","同种异基因移植","异种移植","人造器官移植"],"a":2,"e":"临床移植的供受者多为无血缘关系的同一种属不同个体，即同种异基因移植；自体移植仅限自身组织，同基因移植仅见于同卵双生，异种移植尚少用。"},{"q":"特异性免疫治疗不包括","o":["免疫毒素疗法","细胞因子治疗","抗毒素血清治疗","抗体导向化学疗法","细胞因子拮抗治疗"],"a":1,"e":"特异性免疫治疗针对特定抗原，包括抗毒素血清、免疫毒素、抗体导向化学疗法和细胞因子拮抗治疗；输入细胞因子属非特异性免疫调节。"},{"q":"关于再次应答叙述错误的是","o":["生发中心有大量浆细胞","潜伏期比初次应答短","下降期比初次应答短","维持高抗体浓度的时间比初次应答长","IgG浓度超过IgM"],"a":2,"e":"再次应答的下降期缓慢而长，抗体可维持高水平数月乃至数年，源于记忆B细胞的持续应答；潜伏期短、以高亲和力IgG为主均正确。"},{"q":"接种牛痘获得对天花的免疫力表明","o":["增强巨噬细胞对病毒的吞噬能力","抗原交叉反应性","被动免疫的效果","增强了天然免疫力","抗原特异性"],"a":1,"e":"牛痘病毒与天花病毒存在共同抗原表位，接种牛痘诱导的抗体和效应T细胞可交叉识别天花病毒，由此建立对天花的免疫力。"},{"q":"以下属于Ⅲ型超敏反应性疾病的是","o":["新生儿溶血症","输血反应","血清病","接触性皮炎","青霉素过敏性休克"],"a":2,"e":"血清病发生于大量注射异种血清或药物后1～2周，体内产生的抗体与残留抗原形成循环免疫复合物，沉积于血管壁引起发热、皮疹、关节痛，属Ⅲ型超敏反应。"},{"q":"口服脊髓灰质炎疫苗后，肠内含量明显升高的免疫球蛋白是","o":["sIgA","IgD","IgG","IgM","IgE"],"a":0,"e":"口服脊灰减毒活疫苗经肠道黏膜诱导局部免疫，黏膜固有层浆细胞产生二聚体IgA，经pIgR转运并携带分泌片成为SIgA排入肠腔，故肠内SIgA明显升高。"},{"q":"隐性感染后获得的免疫属于","o":["过继免疫","人工主动免疫","人工被动免疫","自然主动免疫","自然被动免疫"],"a":3,"e":"隐性感染时机体自然暴露于病原体，主动产生特异性抗体和致敏淋巴细胞并形成记忆，属自然主动免疫。"},{"q":"单核细胞进入肝脏后发育而成的免疫细胞是","o":["破骨细胞","库普弗细胞","小胶质细胞","朗格汉斯细胞","肥大细胞"],"a":1,"e":"肝内库普弗细胞属组织定居型巨噬细胞，由单核细胞迁入肝脏后发育而成，具吞噬清除和抗原提呈功能；破骨细胞在骨，小胶质细胞在中枢神经系统。"},{"q":"TNF-α主要由哪种细胞产生","o":["单核-巨噬细胞","初始T细胞","B细胞","树突状细胞","红细胞"],"a":0,"e":"TNF-α主要由活化的单核/巨噬细胞产生，TNF-β（淋巴毒素）主要由活化T细胞产生，两者均能杀伤肿瘤并介导炎症。"},{"q":"自身免疫病的组织损伤机制包括","o":["Ⅰ、Ⅱ、Ⅲ型超敏反应","Ⅱ、Ⅲ、Ⅳ型超敏反应","Ⅲ、Ⅳ型超敏反应","Ⅰ、Ⅱ、Ⅳ型超敏反应","Ⅱ、Ⅲ型超敏反应"],"a":1,"e":"自身抗体和自身反应性T细胞所致组织损伤，通过Ⅱ型（抗体介导）、Ⅲ型（免疫复合物）和Ⅳ型（T细胞介导）超敏反应机制实现。"},{"q":"诱导T细胞向Treg细胞分化的细胞因子是","o":["SCF","TNF","IFN","TGF-β","IL-2"],"a":3,"e":"TGF-β与IL-2共同诱导Th0细胞向Treg分化，Treg的关键转录因子为Foxp3，可抑制过度免疫应答；IL-2主要维持活化T细胞的增殖。"},{"q":"介导T细胞活化的共刺激分子","o":["CD4","CD8","CD16","CD28","CTLA-4"],"a":3,"e":"CD28是T细胞表面最重要的共刺激分子，与APC表面B7结合提供T细胞活化第二信号；CTLA-4结合B7后传递抑制信号。"},{"q":"下列哪一项属于器官特异性自身免疫病","o":["强直性脊柱炎","冷球蛋白血症","1型糖尿病","类风湿关节炎","多发性硬化症"],"a":2,"e":"1型糖尿病针对胰岛β细胞，属器官特异性自身免疫病；系统性红斑狼疮、类风湿关节炎和多发性硬化症均为器官非特异性。"},{"q":"Th2型细胞因子包括","o":["IFN-γ、TNF和IL-12","IFN-γ、TGF-β和IL-12","TNF、IL-4和IL-12","IL-4、IL-5和IL-10","IL-12、IL-10、IL-13"],"a":3,"e":"Th2细胞主要分泌IL-4、IL-5、IL-10和IL-13，辅助体液免疫和抗寄生虫免疫；IFN-γ和IL-12是Th1型特征性细胞因子。"},{"q":"可诱导B细胞分化为分泌IgE的浆细胞的细胞因子是","o":["IL-4","IL-2","IL-6","IFN-γ","TGF-β"],"a":0,"e":"IL-4和IL-13驱动B细胞向IgE进行类别转换，IL-4是诱导B细胞分化为分泌IgE浆细胞的主要因子；TGF-β促IgA，IL-21促IgG。"},{"q":"对肿瘤免疫的认识，错误的是","o":["巨噬细胞在抗肿瘤免疫应答中具有双重性","肿瘤细胞可通过表达Fas诱导肿瘤特异性T细胞凋亡","运用肿瘤特异性CTL可更多的发现TSA","检测肿瘤抗原是目前最常用的肿瘤免疫诊断方法","细胞因子能增强机体抗肿瘤免疫功能"],"a":1,"e":"肿瘤细胞通过表达FasL与肿瘤特异性T细胞表面Fas结合，诱导T细胞凋亡而逃逸；单纯表达Fas则有利于CTL经Fas/FasL途径杀伤肿瘤细胞。"},{"q":"不能引起肥大细胞和嗜碱性粒细胞脱颗粒的因素是","o":["细胞表面IgE与多价Ag结合","C3a、C5a","植物血凝素与细胞表面IgE结合","细胞表面IgE与单价Ag结合","抗FcεR1抗体"],"a":3,"e":"变应原须与致敏肥大细胞表面两个以上相邻IgE结合，使FcεRⅠ交联聚集才能启动活化信号；单价抗原只能占据IgE而不能交联受体，故不引起脱颗粒。"},{"q":"免疫佐剂是","o":["增强半抗原免疫原性的物质","增强对抗原免疫应答的物质","减少免疫原毒性的物质","增强免疫交叉反应性的物质","增强造血作用的物质"],"a":1,"e":"佐剂是与抗原同时或预先注入、可非特异增强机体对该抗原免疫应答或改变应答类型的物质，如铝盐、弗氏佐剂和CpG，其本身无抗原特异性。"},{"q":"B细胞主要定居在淋巴结的","o":["浅皮质区","深皮质区","副皮质区","髓索","髓窦"],"a":0,"e":"淋巴结浅皮质区为非胸腺依赖区，是B细胞定居并聚集成初级淋巴滤泡的场所；深皮质区为T细胞区，髓质区由髓索和髓窦组成。"},{"q":"不参与移植排斥反应的抗原是","o":["Rh血型抗原","mH抗原","组织特异性抗原","HLA抗原","超抗原"],"a":4,"e":"参与移植排斥的抗原包括HLA抗原、mH抗原、ABO等血型抗原和组织特异性抗原；超抗原并非移植抗原，其多克隆激活T细胞与排斥无直接对应。"},{"q":"进行器官移植时优先考虑的候选供者是","o":["患者的父母","患者的妻子","患者的子女","患者的表兄弟姐妹","患者的同胞兄弟姐妹"],"a":4,"e":"HLA单倍型由父母各传一条，同胞间两条单倍型完全相同的概率为25%，远高于其他亲属，故移植时优先选择HLA全相合的同胞兄弟姐妹作为供者。"},{"q":"与抗原抗体相互作用无关的是","o":["范德华力","离子键","非共价键","疏水键","共价化学键"],"a":4,"e":"抗原与抗体通过氢键、离子键、范德华力和疏水键等非共价键结合，结合可逆、易受温度、pH及离子强度影响；共价键只出现于半抗原与载体的人工偶联。"},{"q":"血清中检出高效价抗核抗体多见于","o":["多发性骨髓瘤","系统性红斑狼疮","自身免疫性溶血性贫血","甲状腺肿大","重症肌无力"],"a":1,"e":"SLE患者产生抗dsDNA、抗组蛋白等抗核抗体，高效价抗核抗体是其标志性改变，效价与病情活动相关；多发性骨髓瘤、重症肌无力不以此为主。"},{"q":"下列哪两个结构域之间构成Ⅰ类MHC分子抗原肽结合部位","o":["α1与α2","α2与α3","α2与β2m","β2m与α1","β2与β1"],"a":0,"e":"HLAⅠ类分子重链胞外段折叠为α1、α2、α3三个结构域，其中远膜端的α1和α2共同构成抗原结合槽，两端封闭，容纳8～10个氨基酸的抗原肽。"},{"q":"NK细胞杀伤肿瘤细胞时","o":["不需预先致敏","抗瘤谱较窄","通过表面的IgE Fc段发挥作用","有MHC限制性","在肿瘤晚期时杀瘤作用较强"],"a":0,"e":"NK细胞无需抗原预先致敏、无MHC限制性即可直接杀伤肿瘤细胞，是抗肿瘤的第一道防线，早期作用强且抗瘤谱广。"},{"q":"BALB/c鼠是胞内感染硕大利什曼原虫的易感性鼠，原因是","o":["细胞免疫应答低下","诱导了Th1为主的细胞免疫应答","诱导了Th2为主的细胞免疫应答","诱导了Th17为主的细胞免疫应答","体液免疫应答低下"],"a":0,"e":"BALB/c小鼠感染硕大利什曼原虫后以Th2应答为主，IL-12产生减少、Th1应答受抑，巨噬细胞活化不足，虫体在吞噬体内存活，故细胞免疫应答低下而易感。"},{"q":"浆细胞","o":["可发育为B细胞","具有细胞毒作用","分泌大量IFN-γ","来源于Th细胞","能分泌抗体"],"a":4,"e":"浆细胞是B细胞受抗原刺激后分化的终末细胞，胞质富含粗面内质网，持续分泌特异性抗体，不再具有增殖和分化能力。"},{"q":"CTLA-4的配体是","o":["CD21","CD23","CD32","CD51/CD29","CD80/86"],"a":4,"e":"CTLA-4（CD152）的配体是CD80和CD86，其结合亲和力显著高于CD28，可竞争性抑制CD28的共刺激信号。"},{"q":"B细胞不具有的功能是","o":["抗原提呈功能","分化为浆细胞产生抗体","细胞因子分泌功能","免疫记忆功能","直接杀伤靶细胞功能"],"a":4,"e":"B细胞可提呈抗原、分泌细胞因子、分化为浆细胞产生抗体并形成记忆细胞，但无直接杀伤靶细胞的功能，杀伤由CTL和NK细胞承担。"},{"q":"树突状细胞表面提供T细胞活化第二信号的分子主要是","o":["MHCⅡ类分子","CD19","CD28","CD58","CD80/CD86"],"a":4,"e":"DC表面的B7分子（CD80/CD86）与T细胞CD28结合提供第二信号；MHCⅡ类分子提呈抗原肽产生第一信号。"},{"q":"有关未成熟DC，哪项是错误的","o":["高表达TLR","高表达调理性受体","高表达趋化因子受体","高表达MHCⅡ类分子","摄取加工抗原能力强"],"a":3,"e":"未成熟DC高表达TLR、趋化因子受体和调理性受体，摄取加工抗原能力强，但低表达MHCⅡ类分子和共刺激分子，成熟后才高水平表达。"},{"q":"下述关于NK细胞的正确叙述是","o":["IL-3能增强其杀菌活性","来源于骨髓的髓样细胞系","可通过ADCC效应杀伤靶细胞","表面具有mIg","发挥作用具有特异性"],"a":2,"e":"NK细胞表面表达FcγRⅢA，与包被靶细胞的IgG Fc段结合后经ADCC杀伤靶细胞；其作用无抗原特异性，不表达mIg，来源于共同淋巴样前体。"},{"q":"不属于人工被动免疫制剂的是","o":["抗毒素","类毒素","抗病毒血清","血清丙种球蛋白","胎盘球蛋白"],"a":1,"e":"类毒素由外毒素经甲醛处理制成，保留免疫原性而失去毒性，接种后诱导机体主动产生抗毒素，属人工主动免疫制剂。"},{"q":"关于BCR，以下说法正确的是","o":["主体是一个mIgD分子","主体是一个mIgG分子","主体是一个mIgM分子","主体是五个mIgD分子","主体是五个mIgM分子"],"a":2,"e":"BCR即膜型免疫球蛋白，成熟B细胞以单体mIgM及mIgD构成BCR识别结合抗原，其胞质区短，需Igα/Igβ转导信号。"},{"q":"有关化学致癌剂诱导实验动物发生肿瘤的叙述，错误的是","o":["同一宿主不同部位肿瘤具有相同抗原性","抗原具有个体特异性","人类肿瘤中较少见","抗原性弱","免疫学诊断困难"],"a":0,"e":"化学致癌物诱发的肿瘤抗原呈高度个体特异性，同一宿主不同部位、不同肿瘤抗原性各异，且抗原性弱、免疫学诊断困难，人类肿瘤中较少见。"},{"q":"CD16主要表达于","o":["Mφ","T细胞","NK细胞","DC","肥大细胞"],"a":2,"e":"CD16即FcγRⅢA，主要表达于NK细胞，也见于部分单核细胞和中性粒细胞，介导ADCC；CD56与CD16联合可划分NK细胞亚群。"},{"q":"下列属于X连锁无丙种球蛋白血症发生原因的是","o":["HIV感染","C1INH缺乏","在胚胎发育中，第三、四咽囊发育障碍","Bruton酪氨酸激酶基因缺乏","整合素β2基因突变"],"a":3,"e":"X连锁无丙种球蛋白血症由X染色体上Bruton酪氨酸激酶（BTK）基因突变所致，B细胞发育停滞于前B细胞阶段，血清Ig极低。"},{"q":"下列哪种疾病与HLA分子无关","o":["强直性脊柱炎","多发性硬化病","类风湿性关节炎","血友病","1型糖尿病"],"a":3,"e":"血友病为凝血因子Ⅷ、Ⅸ基因缺陷所致出血性疾病，与HLA无关；强直性脊柱炎与B27、类风湿关节炎与DR4、1型糖尿病与DR3/DR4相关联。"},{"q":"摄取、加工处理抗原能力最强的DC是","o":["前体DC","未成熟DC","骨髓内DC","迁移期DC","成熟DC"],"a":1,"e":"未成熟DC高表达模式识别受体，识别和摄取抗原能力强，但低表达MHCⅡ类分子和共刺激分子，加工提呈能力弱；成熟DC则相反。"},{"q":"有关免疫器官和组织的说法错误的是","o":["骨髓是所有免疫细胞发育和成熟的场所","脾是对血液性抗原产生免疫应答的主要场所","淋巴结是T细胞的主要定居地","黏膜免疫系统是局部免疫应答发生部位","脾是人体最大的外周免疫器官"],"a":0,"e":"骨髓是各类血细胞产生和B细胞发育成熟的场所，但T细胞在胸腺发育成熟，故骨髓并非所有免疫细胞发育成熟之处。"},{"q":"关于补体的叙述下列错误的是","o":["存在于正常人的新鲜血清中","包括30余种组分","其活性较不稳定","激活后具有酶活性","在机体受抗原刺激后产生"],"a":4,"e":"补体是固有免疫分子，由肝细胞和巨噬细胞等持续合成，存在于新鲜血清中，包括30余种组分，激活前无活性、激活后呈酶活性，其产生不依赖抗原刺激。"},{"q":"DC通过分泌何种细胞因子激活Th1细胞","o":["IL-12","IL-10","IL-2","Il-3","IL-4"],"a":0,"e":"DC分泌IL-12，与IL-18协同促进Th0向Th1分化并增强NK、CTL产生IFN-γ；IL-4则诱导Th0向Th2分化。"},{"q":"NK细胞通过ADCC机制杀伤靶细胞需要","o":["补体","抗体","MHC","TCR","细胞因子"],"a":1,"e":"ADCC依赖抗体：IgG与靶细胞表面抗原特异性结合，其Fc段再与NK细胞表面FcγRⅢA结合，交联后触发NK细胞释放穿孔素、颗粒酶杀伤靶细胞，补体和MHC不参与。"},{"q":"过客白细胞主要是","o":["NK细胞","T淋巴细胞","B淋巴细胞","树突状细胞","中性粒细胞"],"a":3,"e":"移植物中残留的过客白细胞主要是供者树突状细胞，可携带同种异型MHC分子迁移至受者淋巴组织，直接激活受者T细胞。"},{"q":"内源性抗原肽需经下列哪种分子转运进入内质网","o":["LMP","TAP","CLIP","HLA-DM","Ii"],"a":1,"e":"TAP在内质网膜形成孔道，以ATP依赖方式将胞质中8～16个氨基酸的抗原肽转运入内质网腔，与MHCⅠ类分子结合；LMP为免疫蛋白酶体组分。"},{"q":"介导B细胞活化第二信号的分子对是","o":["CD28-B7","CD40-CD40L","BCR-抗原","CD4-MHCⅡ类分子","CD8-MHCⅠ类分子"],"a":1,"e":"B细胞活化的第二信号主要由活化Tfh细胞表面CD40L与B细胞组成性表达的CD40结合提供；CD28与B7结合为T细胞活化的第二信号。"},{"q":"关于移植物抗宿主反应的叙述，正确的是","o":["可见于新生儿接受大量输血时","受者T细胞识别供者血型抗原","受者T细胞识别供者HLA抗原","供者NK细胞通常不参与反应","原因是使用了免疫抑制剂"],"a":0,"e":"移植物抗宿主反应是供者移植物中的免疫细胞识别受者同种异型抗原后增殖分化，攻击宿主组织；免疫缺陷个体接受大量输血（含新生儿）时可发生。"},{"q":"决定抗原特异性的是","o":["抗原的化学性质","抗原分子结构的复杂性","抗原分子的特殊化学基团","抗原相对分子质量的大小","抗原的物理性状"],"a":2,"e":"抗原表位是决定抗原特异性的结构基础，其化学基团的性质、数目和空间构象决定抗体或TCR识别的专一性；分子量大小和物理性状只影响免疫原性强弱。"},{"q":"抗体与抗原结合的相互作用是","o":["共价键","非共价键","二硫键","磷酸化作用","氢键"],"a":1,"e":"抗体与抗原表位依靠氢键、离子键、范德华力和疏水作用等非共价键结合，具可逆性，不形成共价键或二硫键。"},{"q":"TI-Ag引起免疫应答的特点是","o":["只引起体液免疫","可以产生各种类别的Ig","有免疫记忆","可以引起细胞免疫","需要巨噬细胞进行加工处理"],"a":0,"e":"TI抗原不经APC加工提呈，可直接刺激B细胞，无需Th细胞辅助，故只引起体液免疫应答，无抗体类别转换和免疫记忆，也不引起细胞免疫。"},{"q":"关于旁路激活途径正确的叙述是","o":["需要抗原抗体的识别和反应","膜攻击单位与经典途径相同","首先活化的补体成分是C5","形成的C3转化酶与经典途径相同","形成的C5转化酶与经典途径相同"],"a":1,"e":"三条途径共用C5b～C9组装MAC的末端通路；旁路途径的C3转化酶为C3bBb、C5转化酶为C3bBb3b，无需抗原抗体复合物启动。"},{"q":"关于细胞因子的检测，错误的是","o":["采用细胞增殖法检测需要细胞因子依赖性细胞株","几乎所有细胞因子都可以用ELISA进行检测","ELISPOT法比ELISA法更敏感","胞内细胞因子检测法需要对细胞进行固定和增加膜的通透性","胞内细胞因子检测法需要使用抑制剂来抑制细胞因子释放"],"a":2,"e":"官方答案为【ELISPOT法比ELISA法更敏感】，但依据教材，正确答案为【几乎所有细胞因子都可以用ELISA进行检测】。ELISPOT经生物素-亲和素系统放大反应，灵敏度确实高于ELISA。"},{"q":"抗御病原体的化学屏障不包括","o":["汗腺分泌的乳酸","皮脂腺分泌的不饱和脂肪酸","胃酸","多种分泌物中的溶菌酶和抗菌肽","细胞因子"],"a":4,"e":"化学屏障由汗液乳酸、皮脂腺不饱和脂肪酸、胃酸、溶菌酶和抗菌肽等杀抑菌物质构成；细胞因子属免疫分子，介导炎症和免疫调节，不是屏障成分。"},{"q":"反应性氧中间物系统中所不具备的杀菌物质是","o":["超氧阴离子","一氧化氮","单态氧","游离羟基","过氧化氢"],"a":1,"e":"反应性氧中间物包括超氧阴离子、过氧化氢、单态氧和游离羟基；一氧化氮属反应性氮中间物，由iNOS催化生成。"},{"q":"以下关于肿瘤免疫诊断的叙述，哪项是错误的","o":["检测血清AFP抗原，协助诊断原发性肝细胞癌","检测HCV和HBV抗原有助于原发性肝癌诊断","用放射免疫显像诊断肿瘤所在部位","检测CEA有助于诊断直结肠癌","检测CA199有助于B淋巴细胞瘤诊断"],"a":4,"e":"CA19-9是胰腺癌相关标志物，B细胞淋巴瘤的诊断依靠CD19、CD20等分化抗原检测；AFP对肝癌、CEA对结直肠癌有辅助诊断价值。"},{"q":"介导Ⅰ型超敏反应的生物活性物质主要是由下列哪一种细胞释放的","o":["单核细胞","巨噬细胞","嗜碱性粒细胞","B细胞","中性粒细胞"],"a":2,"e":"嗜碱性粒细胞胞质富含嗜碱性颗粒，表面高表达FcεRⅠ，变应原交联膜IgE后脱颗粒释放组胺、白三烯等，是介导Ⅰ型超敏反应速发相的主要效应细胞。"},{"q":"吞噬细胞表面CD14和TLR4识别结合的配体是","o":["G＋菌肽聚糖","G－菌脂多糖","细菌甘露糖","酵母多糖","病毒双股RNA"],"a":1,"e":"CD14与TLR4/MD-2复合物共同识别G-菌脂多糖，经MyD88途径活化NF-κB诱导炎症因子表达；G+菌肽聚糖由TLR2识别，酵母多糖亦由TLR2识别，病毒双链RNA由TLR3识别。"},{"q":"能与NK细胞、巨噬细胞表面的Fc受体结合并介导ADCC效应的主要免疫球蛋白是","o":["IgA","IgM","IgG","IgD","IgE"],"a":2,"e":"IgG与靶细胞表面抗原结合后，其Fc段与NK细胞CD16、巨噬细胞FcγR结合，介导ADCC和调理吞噬，是介导ADCC的主要抗体类别。"},{"q":"机体防止外界病原体的入侵及清除已入侵病原体的功能称为","o":["免疫调节","免疫缺陷","免疫耐受","免疫防御","免疫监视"],"a":3,"e":"免疫防御指免疫系统抵御外界病原体入侵并清除已入侵病原体及有害物质的功能，功能低下易发生感染，应答过强则引起超敏反应。"},{"q":"兼备抗原加工提呈和吞噬杀菌作用的免疫细胞是","o":["树突状细胞","B细胞","肥大细胞","巨噬细胞","中性粒细胞"],"a":3,"e":"巨噬细胞既有强大吞噬杀菌能力，又作为专职性APC以抗原肽-MHCⅡ类分子复合物将抗原提呈给CD4+Th细胞。"},{"q":"关于补体三条激活途径的叙述，下列哪项是错误的","o":["三条途径形成的膜攻击复合物相同","MBL途径一般在感染后期发挥作用","经典途径从C1被激活开始","旁路途径从C3被激活开始","MBL途径中的C3转化酶是C4b2a或者C3bBb"],"a":1,"e":"MBL途径无需抗体参与，在感染早期即发挥作用；感染后期起作用的是经典途径，其C3转化酶为C4b2a，而非C3bBb。"},{"q":"生发中心大约形成于","o":["抗原进入机体时","抗原进入机体第二天","抗原进入机体一周后","抗原进入机体两周后","抗原进入机体三周后"],"a":2,"e":"抗原刺激后B细胞在淋巴滤泡内增殖，约1周形成生发中心，其中发生体细胞高频突变、亲和力成熟和类别转换，随后产生记忆B细胞与长寿浆细胞。"},{"q":"释放介导Ⅰ型超敏反应的生物活性介质的主要细胞是","o":["巨噬细胞","单核细胞","肥大细胞","B细胞","中性粒细胞"],"a":2,"e":"肥大细胞经FcεRⅠ结合IgE而致敏，再次接触变应原后脱颗粒释放组胺、白三烯等，是Ⅰ型超敏反应速发相的主要效应细胞。"},{"q":"Th2细胞通过产生何种细胞因子抑制Th1细胞的活性","o":["IL-4","IFN-γ","TNF-α","IL-12","IL-2"],"a":0,"e":"Th2细胞分泌的IL-4可抑制Th1细胞分化及IFN-γ产生；IL-12和IFN-γ促进Th1分化，二者相互拮抗维持亚群平衡。"},{"q":"APC和T细胞间形成的免疫突触，错误的是","o":["是在细胞接触部位形成的特殊膜结构","含多种跨膜分子","中心区是TCR和抗原肽-MHC分子复合物","可促进T细胞内信号转导","在细胞相互作用前预先存在的膜结构"],"a":4,"e":"免疫突触是T细胞与APC接触后诱导形成的特殊膜结构，中央为TCR-pMHC，外围为共刺激分子和黏附分子，并非接触前预先存在。"},{"q":"外周血白细胞中数量最多、存活期最短的免疫细胞是","o":["单核细胞","中性粒细胞","嗜碱性粒细胞","嗜酸性粒细胞","T淋巴细胞"],"a":1,"e":"中性粒细胞占外周血白细胞的50%～70%，数量最多，产生速率高但存活不超过24小时；单核细胞仅占3%～8%。"},{"q":"适应性免疫应答不具备的特点是","o":["无需抗原激发","具有免疫记忆性","具有抗原特异性","具有再次应答的能力","精确区分“自身”和“非己”"],"a":0,"e":"适应性免疫必须由抗原激发，具有抗原特异性、免疫记忆和再次应答能力，并能精确区分自身与非己；无需抗原激发是固有免疫的特点。"},{"q":"具有非特异性细胞毒作用的细胞是","o":["单核细胞","Th细胞","CTL细胞","NK细胞","B细胞"],"a":3,"e":"NK细胞无需抗原预先致敏，不表达特异性抗原识别受体，经活化性受体与抑制性受体信号整合后直接杀伤病毒感染细胞和肿瘤细胞，其细胞毒作用属非特异性。"},{"q":"组成化学屏障的杀、抑菌物质不包括","o":["脂肪酸","α-防御素","乳酸","溶菌酶","抗菌肽"],"a":1,"e":"化学屏障由皮脂腺不饱和脂肪酸、汗液乳酸、胃酸、溶菌酶、抗菌肽和乳铁蛋白等分泌物构成；α-防御素储存于吞噬细胞颗粒内，属氧非依赖性杀菌系统的效应分子。"},{"q":"可刺激红细胞产生的细胞因子是","o":["TPO","G-CSF","EPO","M-CSF","GM-CSF"],"a":2,"e":"红细胞生成素主要由肾皮质间质细胞产生，刺激红系祖细胞增殖分化，用于治疗肾性贫血；TPO作用于血小板，G-CSF作用于粒细胞。"},{"q":"嵌合抗体是指","o":["将鼠CDR序列移植到人抗体可变区形成的抗体","一条肽链中含两个抗体可变区片段的抗体","小鼠转染人抗体基因后产生的抗体","双特异性抗体","将鼠源抗体可变区与人抗体恒定区融合形成的抗体"],"a":4,"e":"人-鼠嵌合抗体由鼠源抗体的V区与人抗体的C区融合而成，保留亲本抗体的特异性和亲和力，同时降低对人体的免疫原性。"},{"q":"下列关于免疫耐受的说法正确的是","o":["免疫耐受是对某一抗原物质上的所有决定簇都具有特异性","耐受最易在成年期产生","应用佐剂可增强免疫耐受效果","免疫耐受可人为终止","免疫耐受形成只与抗原的性质有关，与机体因素无关"],"a":3,"e":"免疫耐受为后天获得的特异性无应答，可应用佐剂、提供共刺激信号或清除调节性T细胞等措施人为终止。"},{"q":"NKT细胞表面TCR识别结合的配体是","o":["MHCⅠ类分子提呈的抗原肽","CD1分子提呈的磷脂/糖脂类抗原","MHCⅡ类分子提呈的抗原肽","某些肿瘤细胞表面的MICA/B分子","细菌脂多糖"],"a":1,"e":"NKT细胞的TCR识别CD1d分子提呈的糖脂和磷脂类抗原，而非MHC分子提呈的抗原肽；MICA/B是γδT细胞识别的配体。"},{"q":"成熟树突状细胞具有的生物学特征是","o":["高表达调理性受体，摄取加工抗原能力强","高表达模式识别受体，摄取加工抗原能力强","高表达共刺激分子，摄取加工抗原能力强","高表达MHCⅡ类分子，提呈抗原能力强","高表达黏附分子，迁移能力强"],"a":3,"e":"DC成熟后高表达MHCⅡ类分子及CD80、CD86等共刺激分子和黏附分子，提呈抗原、激活初始T细胞的能力强；摄取加工抗原能力强是未成熟DC的特点。"},{"q":"下列分子中，不表达于专职性APC表面的是","o":["MHCⅠ类分子","MHCⅡ类分子","TCR","BCR","共刺激分子"],"a":2,"e":"专职APC表达MHCⅠ、Ⅱ类分子和共刺激分子，B细胞还表达BCR；TCR为T细胞特有，不存在于APC表面。"},{"q":"具有最强调理功能的抗体类别是","o":["IgG","IgM","IgD","IgA","IgE"],"a":0,"e":"IgG尤其IgG1、IgG3的Fc段与吞噬细胞FcγR结合，通过桥联作用介导调理吞噬，是调理作用最强的抗体类别。"},{"q":"Th细胞辅助抗体产生","o":["可发生于经X线照射的小鼠","依靠T细胞识别结合于BCR的完整抗原","发生在对LPS的应答过程中","依靠T细胞识别经B细胞处理、提呈的抗原","涉及B细胞上的MHCⅠ类分子"],"a":3,"e":"B细胞借BCR摄取抗原，经MHCⅡ类分子提呈给CD4+Th细胞，Th识别抗原肽-MHCⅡ类分子复合物后被激活并辅助B细胞。"},{"q":"临床尝试以口服重组胰岛素的方法预防和治疗糖尿病，主要机制是","o":["模拟骨髓阴性选择诱导B细胞免疫耐受","模拟胸腺阴性选择诱导T细胞免疫耐受","口服自身抗原诱导免疫耐受","增强胰岛素的作用","消除病人体内的自身抗体"],"a":2,"e":"口服重组胰岛素可在肠相关淋巴组织诱导针对胰岛自身抗原的特异性免疫耐受，抑制自身反应性T细胞，属口服自身抗原诱导耐受的策略。"},{"q":"鼻咽癌发生发展可能的免疫学机制是","o":["鼻咽癌瘤细胞MHCⅠ类分子表达下调","鼻咽癌细胞表面Fas表达上调","鼻咽癌细胞可分泌IL-2下调免疫应答","鼻咽癌细胞表面肿瘤抗原免疫原性强","鼻咽癌细胞B7分子表达增强"],"a":0,"e":"肿瘤细胞MHCⅠ类分子缺陷或表达低下，不能有效提呈肿瘤抗原，使CTL无法识别和杀伤，是鼻咽癌等肿瘤免疫逃逸的重要机制。"},{"q":"抗体亲和力成熟的机制是","o":["骨髓内的阴性选择","骨髓内的阳性选择","生发中心内的阴性选择","生发中心内的阳性选择","骨髓内的优胜劣汰"],"a":3,"e":"生发中心B细胞经体细胞高频突变后，能高亲和力结合FDC表面抗原并获得Tfh辅助者被选择性存活增殖，即阳性选择，实现亲和力成熟。"},{"q":"HLAⅠ类基因编码的产物是","o":["MHCⅠ类分子的α链","MHCⅠ类分子的β链","MHCⅡ类分子的α链","MHCⅡ类分子的β链","C2、C4、TNF"],"a":0,"e":"HLAⅠ类基因编码MHCⅠ类分子的α链即重链，轻链β2m由第15号染色体非MHC基因编码；Ⅱ类分子α、β链由Ⅱ类基因编码。"},{"q":"三条补体激活途径的共同点是","o":["参与的补体成分相同","所需离子相同","C3转化酶的组成相同","激活物质相同","膜攻击复合物的形成及其溶解细胞的效应相同"],"a":4,"e":"三条途径的激活物、参与成分和C3转化酶组成均不同，但终末通路一致，均生成C5转化酶，进而组装C5b-9膜攻击复合物，产生相同的溶细胞效应。"},{"q":"早期非特异性免疫应答阶段发生于感染后（ ）小时之内","o":["0～4","0～24","4～48","4～96","24～96"],"a":3,"e":"早期诱导的固有免疫应答发生于感染后4～96小时，以招募和活化固有免疫细胞为主；即刻应答在4小时内，适应性应答在96小时后。"},{"q":"去除病原体中与激发保护性免疫无关的成分，保留有效免疫原成分制作的疫苗称为","o":["类毒素","结合疫苗","亚单位疫苗","重组抗原疫苗","灭活疫苗"],"a":2,"e":"亚单位疫苗去除病原体中与保护性免疫无关及引起超敏反应的成分，仅保留有效免疫原成分，经理化提纯或DNA重组技术制备。"},{"q":"下列哪个分子可与MHCⅡ类分子结合，并具有辅助增强CD4＋T细胞识别抗原的能力","o":["CD2","CD3","CD4","CD8","CD9"],"a":2,"e":"CD4是TCR的共受体，其胞膜外区远膜端的Ig样结构域与MHCⅡ类分子β2结构域结合，可增强TCR对pMHC的亲和力并辅助其识别，胞质区还结合酪氨酸激酶参与信号转导。"},{"q":"下列关于脾的功能的描述错误的是","o":["是T细胞定居的场所","是B细胞定居的场所","是对血源性抗原产生免疫应答的场所","是对引流淋巴液而来的抗原产生免疫应答的场所","可吞噬清除外周血中衰老的红细胞"],"a":3,"e":"脾主要对血源性抗原产生免疫应答，淋巴结才对随淋巴液引流而来的抗原应答；脾也是T、B细胞定居并清除衰老红细胞的场所。"},{"q":"在脱敏治疗中，诱导机体产生的封闭性抗体是","o":["IgA","IgE","IgG","IgM","sIgA"],"a":2,"e":"脱敏治疗诱导产生特异性IgG类封闭抗体，与变应原结合后阻断其与致敏肥大细胞表面IgE的结合，从而抑制Ⅰ型超敏反应。"},{"q":"胞质区含有ITIM，与B7结合后可抑制T细胞活化的CD分子是","o":["CD3","CD4","CD8","CD28","CD152"],"a":4,"e":"CD152即CTLA-4，胞质区含ITIM，与B7结合后传递抑制信号，下调或终止T细胞活化；CD28与同一配体结合则传递活化信号。"},{"q":"下列哪个部位的浆细胞一般情况下不能产生IgE","o":["胃肠道黏膜","鼻咽","支气管","扁桃体","脾脏"],"a":4,"e":"IgE主要由呼吸道、消化道黏膜固有层及扁桃体等黏膜淋巴组织的浆细胞产生，参与黏膜局部过敏反应；脾脏浆细胞一般不产生IgE。"},{"q":"人T细胞区别于B细胞及其他细胞的特征是","o":["形态","Fc受体","胞质颗粒","TCR","Ig表面标志"],"a":3,"e":"TCR为T细胞特有的抗原识别受体，与CD3组成复合物；B细胞以BCR即mIg识别抗原，Fc受体、胞质颗粒和形态均非T细胞独有。"},{"q":"以下不属于细胞因子的生物学活性的是","o":["抗细菌作用","抗病毒作用","刺激造血","促进血管的生成","激活补体"],"a":4,"e":"细胞因子具抗感染、抗肿瘤、刺激造血、促进血管生成和免疫调节等活性；激活补体是补体系统的级联活化，不属细胞因子功能。"},{"q":"具有抑制病毒增殖作用细胞因子是","o":["IFN-α","TNF-α","IL-1","IL-6","IL-2"],"a":0,"e":"IFN-α属Ⅰ型干扰素，由病毒感染细胞和pDC产生，与受体结合后诱导合成2′-5′寡腺苷酸合成酶和蛋白激酶R，抑制病毒蛋白翻译与复制。"},{"q":"下列可被动转移Ⅳ型超敏反应的成分是","o":["巨噬细胞","淋巴细胞","血清Ig","血清补体","中性粒细胞"],"a":1,"e":"Ⅳ型超敏反应由致敏T细胞介导，可通过淋巴细胞被动转移；抗体和补体不参与其发生，故血清不能转移该反应。"},{"q":"拮抗Th2细胞分化的细胞因子是","o":["IL-1","IL-2","IL-4","IL-5","IFN-γ"],"a":4,"e":"IFN-γ抑制Th2细胞分化并促进Th1应答；IL-4是诱导Th0向Th2分化、上调转录因子GATA3的关键因子。"},{"q":"T细胞在胸腺发育过程中，通过阳性选择获得","o":["自身MHC限制性","自身耐受","TCR的表达","TCRα链基因重排","TCRβ链基因重排"],"a":0,"e":"胸腺皮质中，DP细胞以适当亲和力识别胸腺上皮细胞表面自身抗原肽-MHC分子复合物而存活并分化为SP细胞，由此获得自身MHC限制性。"},{"q":"拥有4个重链恒定区的免疫球蛋白包括","o":["IgG和IgE","IgA和IgG","IgD和IgM","IgM和IgE","IgG和IgM"],"a":3,"e":"IgM和IgE的重链恒定区含CH1～CH4四个结构域且无铰链区；IgG、IgA、IgD的重链恒定区仅CH1～CH3三个结构域。"},{"q":"CD4分子","o":["属胞内糖蛋白","是异二聚体","可结合抗原","可结合APC细胞上的MHCⅡ类分子","具有高度多态性"],"a":3,"e":"CD4为单链跨膜糖蛋白，其远膜端结构域与APC表面MHCⅡ类分子β2结构域结合，增强TCR与pMHC亲和力并辅助信号转导。"},{"q":"关于TI抗原描述错误的是","o":["能刺激初始B细胞","如某些细菌多糖及脂多糖","即胸腺非依赖性抗原","能在无胸腺鼠诱导Ab应答","在正常个体可诱导Ab产生和T细胞应答"],"a":4,"e":"TI抗原即胸腺非依赖性抗原，主要是细菌多糖和脂多糖，可直接刺激初始B细胞并在无胸腺裸鼠体内诱生抗体；其应答不依赖T细胞，故不能诱导T细胞应答。"},{"q":"关于减毒活疫苗的特点，错误的是","o":["接种量少","接种次数少","易保存","免疫效果好","注射副反应较灭活疫苗少"],"a":2,"e":"减毒活疫苗需低温冷链保存，较灭活疫苗难以保存；其接种量小、接种次数少、免疫效果好且持久。"},{"q":"下列细胞间作用受MHCⅠ类分子限制的是","o":["APC与Th细胞","NK细胞与靶细胞","Th细胞与巨噬细胞","CTL细胞与靶细胞","Th细胞与B细胞"],"a":3,"e":"CTL表达CD8，其TCR识别靶细胞表面内源性抗原肽-MHCⅠ类分子复合物，受自身MHCⅠ类分子限制；APC与Th、Th与B细胞间的识别则受MHCⅡ类分子限制。"},{"q":"不能用于可溶性抗原检测的是","o":["间接凝集试验","反向间接凝集试验","间接凝集抑制试验","直接凝集试验","SPA协同凝集试验"],"a":3,"e":"直接凝集试验检测细菌、红细胞等颗粒性抗原；可溶性抗原须先吸附于载体颗粒，再用间接凝集或间接凝集抑制试验检测。"},{"q":"关于TCRγδT细胞的特性，错误的是","o":["主要分布在黏膜上皮","TCR有较少的多态性","受经典的MHC分子限制","识别抗原多为脂类或多糖类","占外周血T细胞5%～15%"],"a":2,"e":"γδT细胞识别热休克蛋白、脂类和多糖，提呈分子为MHCⅠ类样分子，无经典MHC限制性；主要分布于皮肤黏膜，占外周血T细胞5%～15%。"},{"q":"关于自身免疫病发病的正确说法是","o":["儿童发病多于老年人","男性多于女性","切除卵巢后发病率增高","睾丸酮可诱发某些品系小鼠出现系统性红斑狼疮","切除小鼠卵巢可避免某些品系小鼠发生自发性系统性红斑狼疮"],"a":4,"e":"自身免疫病女性多发，雌激素促进发病；切除某些品系小鼠卵巢可阻断雌激素作用，避免自发性系统性红斑狼疮发生。"},{"q":"B1细胞表面具有鉴别意义的标志是","o":["TCR－、mIgM＋、CD5＋","TCR－、mIgM＋/IgD＋、CD5－","TCR＋、CD56＋、CD16－","TCR－、CD56＋、CD16＋","TCR－、CD34＋、CD117＋"],"a":0,"e":"B1细胞不表达TCR，表面为mIgM而不表达mIgD，并组成性表达CD5，即TCR-、mIgM+、CD5+，主要定居于胸膜腔、腹膜腔和肠道固有层，参与早期抗感染。"},{"q":"固有免疫分子不包括","o":["防御素","补体系统","细胞因子","溶菌酶","抗毒素"],"a":4,"e":"固有免疫分子包括防御素、溶菌酶、补体系统及多种细胞因子，在感染早期非特异发挥作用；抗毒素是抗原刺激后由浆细胞产生的特异性抗体，属适应性免疫。"},{"q":"不属于体外Ag-Ab反应的是","o":["沉淀反应","凝集反应","ELISA","PCR","免疫荧光技术"],"a":3,"e":"PCR扩增核酸，不涉及抗原抗体反应；沉淀反应、凝集反应、ELISA和免疫荧光技术均以抗原与抗体特异性结合为基础，属体外Ag-Ab反应。"},{"q":"个体甄别是依据HLA分子的","o":["肽结合区","跨膜区","胞浆区","Ig样区","单体型"],"a":0,"e":"HLA分子的肽结合区由α1、α2或α1、β1结构域构成，其序列高度多态，决定抗原肽结合与提呈的特异性，因而是HLA分型和个体识别的结构基础。"},{"q":"通过激活补体参与移植排斥的抗体主要是","o":["IgA","IgG","IgM","IgE","IgD"],"a":2,"e":"IgM为五聚体，含5个Fc段，结合抗原后更易使C1q发生构象改变而激活经典途径，故介导超急性排斥的预存ABO血型抗体主要为IgM。"},{"q":"关于γδT细胞，正确的描述是","o":["大多数是CD4＋CD8＋","具有细胞毒作用","大多数是CD4＋CD8－","主要分布于脾脏和淋巴结","识别抗原时具有MHC限制性"],"a":1,"e":"γδT细胞多数为CD4-CD8-，主要分布于皮肤和黏膜组织，属固有免疫细胞，识别抗原不受MHC限制，可经穿孔素/颗粒酶和FasL直接杀伤靶细胞。"},{"q":"下列关于抗原的叙述，哪一项是错误的","o":["大分子蛋白质抗原常含有多种不同的抗原决定基","抗原诱导免疫应答必须有T细胞辅助","不同的抗原之间可以有相同的抗原决定基","抗原不一定只诱导正向免疫应答","半抗原虽无免疫原性，但可与相应抗体结合"],"a":1,"e":"胸腺非依赖性抗原可直接激活B细胞产生抗体，无需Th细胞辅助；需T细胞辅助只是胸腺依赖抗原的特点，以此概括全部抗原有误。"},{"q":"天然的特异性细胞因子抑制物是","o":["IL-1Rα","IL-2R","IL-4R","IL-6R","IL-8R"],"a":0,"e":"IL-1受体拮抗剂（IL-1Rα）天然存在，能竞争结合IL-1R而不启动信号转导，是特异性细胞因子抑制物。"},{"q":"DC摄取凋亡的肿瘤细胞后，其肿瘤抗原自吞噬体逸出至胞浆。该抗原经过DC的加工处理，最有可能激活的细胞是","o":["CD4＋T细胞","CD8＋T细胞","NKT细胞","B1细胞","B2细胞"],"a":1,"e":"抗原自吞噬体逸入胞质后经蛋白酶体降解，由TAP转运入内质网与MHCⅠ类分子结合，即交叉提呈途径，激活CD8+T细胞。"},{"q":"抗体抗肿瘤的机制不包括","o":["增强抗体的作用","ADCC","调理作用","CDC","封闭肿瘤细胞上的转铁蛋白受体"],"a":0,"e":"抗体抗肿瘤通过激活补体、调理吞噬、ADCC及封闭转铁蛋白受体抑制肿瘤生长；增强抗体可封闭肿瘤抗原、阻碍CTL攻击，反而促进肿瘤生长。"},{"q":"兄弟姐妹间引起器官移植排斥反应的物质属于","o":["自身抗原","同种异型抗原","异种抗原","异嗜性抗原","隐蔽抗原"],"a":1,"e":"同一种属不同个体间HLA等位基因产物存在差异，构成同种异型抗原，是同胞间移植排斥反应的主要靶抗原。"},{"q":"接种疫苗后，首先产生的抗体一般是","o":["IgM","IgG","IgA","IgE","IgD"],"a":0,"e":"初次体液免疫应答潜伏期长，最先产生的是IgM，随后出现低亲和力IgG；再次应答则以高亲和力IgG为主。"},{"q":"属于未成熟DC的是","o":["并指状DC","浆细胞样DC","朗格汉斯细胞","滤泡DC","外周血DC"],"a":2,"e":"朗格汉斯细胞位于表皮，属未成熟DC，摄取加工抗原能力强而低表达MHCⅡ类和共刺激分子；并指状DC和滤泡DC均属成熟DC。"},{"q":"识别外源性抗原肽，受自身MHCⅡ类分子限制的CD分子是","o":["CD3","CD4","CD8","CD28","CD152"],"a":1,"e":"CD4是MHCⅡ类分子的共受体，与其β2结构域结合，故识别外源性抗原肽、受自身MHCⅡ类分子限制的T细胞为CD4+T细胞。"},{"q":"下列不属于隐蔽抗原的是","o":["精子","组织相容性抗原","脑组织","睾丸","眼晶状体"],"a":1,"e":"隐蔽抗原指解剖上隔绝、从未与免疫系统接触的成分，如眼晶状体、精子、脑组织和睾丸；组织相容性抗原表达于所有有核细胞，是移植排斥的主要靶抗原。"},{"q":"同种异基因器官移植中，最常见的一类移植排斥反应是","o":["超急性排斥反应","急性排斥反应","慢性排斥反应","GVHR","迟发性排斥"],"a":1,"e":"急性排斥反应一般发生于移植术后数天至2周，80%～90%在术后1个月内，是同种异型器官移植中最常见的一类排斥反应。"},{"q":"能与肥大细胞表面FcεRⅠ结合的免疫球蛋白是","o":["IgG","IgM","IgE","IgD","sIgA"],"a":2,"e":"IgE为亲细胞抗体，其Fc段与肥大细胞、嗜碱性粒细胞表面高亲和力受体FcεRⅠ结合使细胞致敏，再次接触变应原即脱颗粒。"},{"q":"主要分布于黏膜和上皮组织中，表面标志为CD3＋的免疫细胞是","o":["NK细胞","巨噬细胞","B细胞","γδT细胞","αβT细胞"],"a":3,"e":"γδT细胞表达TCRγδ-CD3复合物，主要分布于肠道、呼吸道等黏膜和皮下组织，是黏膜局部早期抗感染、抗肿瘤的主要效应细胞。"},{"q":"体内执行抗肿瘤免疫监视作用的固有免疫细胞是","o":["Tc细胞（CTL）","NK细胞","LAK细胞","巨噬细胞","调节性T细胞"],"a":1,"e":"NK细胞无需抗原致敏即可识别杀伤MHCⅠ类分子表达下调的肿瘤细胞，是执行免疫监视的固有免疫细胞；Tc细胞属适应性免疫。"},{"q":"以下试验中涉及两对抗原抗体反应的是","o":["肥达试验","Coombs试验","直接免疫荧光","免疫比浊","间接凝集试验"],"a":1,"e":"Coombs试验以抗人球蛋白抗体（第二抗体）结合红细胞上已吸附的不完全抗体（第一对），形成凝集，故涉及两对抗原抗体反应。"},{"q":"发生机制与分子模拟无关的疾病是","o":["多发性硬化症","急性肾小球肾炎","风湿性心脏病","类风湿关节炎","柯萨奇病毒感染引发的糖尿病"],"a":3,"e":"类风湿关节炎由自身变性IgG刺激产生类风湿因子并形成免疫复合物沉积于滑膜致病；多发性硬化症、风湿性心脏病、链球菌感染后肾炎和柯萨奇病毒所致糖尿病均与分子模拟有关。"},{"q":"在机体抗HIV感染过程中，下列哪个细胞有可能成为HIV的“庇护所”","o":["NK细胞","CD4＋T细胞","CD8＋T细胞","B细胞","树突状细胞"],"a":4,"e":"树突状细胞可结合HIV并将完整病毒传递给CD4+T细胞而自身不被感染，成为病毒存留和播散的庇护所；滤泡树突状细胞亦滞留病毒。"},{"q":"只有偶联到蛋白质载体上才具有免疫原性的物质是","o":["调理素","佐剂","半抗原","变应原","耐受原"],"a":2,"e":"半抗原单独无免疫原性，与蛋白质载体偶联成完全抗原后才能诱导免疫应答；佐剂只增强免疫原性，并不提供抗原表位。"},{"q":"血清中含量最高的Ig是","o":["IgM","IgE","IgA","IgD","IgG"],"a":4,"e":"IgG占血清总Ig的75%～80%，是血清和胞外液中含量最高的抗体，出生后3个月开始合成；IgM仅占5%～10%，SIgA主要存在于外分泌液，均明显低于IgG。"},{"q":"一患者因注射抗毒素发生血清病，最佳的处理措施是","o":["输全血","输白蛋白","停止注射抗毒素","注射抗生素","输血小板"],"a":2,"e":"血清病由抗抗毒素抗体与未清除的抗毒素形成中等分子量免疫复合物所致，具自限性，停止注射抗毒素后症状可自行消退。"},{"q":"关于B1细胞亚群的正确叙述是","o":["个体发生较晚","不表达CD5分子","产生IgM类抗体","对T细胞有依赖性","分布在外周免疫器官"],"a":2,"e":"B1细胞针对细菌多糖等TI抗原应答，无需Th辅助，不发生类别转换，只产生低亲和力IgM，呈多反应性；其个体发生早，主要定居于胸腔、腹腔和黏膜。"},{"q":"下列关于抗原免疫原性影响因素的叙述正确的是","o":["抗原与机体之间的亲缘关系越远，免疫原性越弱","一般而言，脂类较蛋白质免疫原性强","一般而言，抗原的分子量越大，免疫原性越弱","抗原的分子结构越复杂，免疫原性越强","抗原结构越简单，免疫原性越强"],"a":3,"e":"抗原分子量越大、结构越复杂、含表位越多，免疫原性越强；与机体亲缘关系越远异物性越强，脂类免疫原性弱。"},{"q":"能分化为巨噬细胞的前体细胞是","o":["单核细胞","B细胞","T细胞","嗜酸性粒细胞","红细胞"],"a":0,"e":"骨髓单核细胞进入血液后停留12～24小时，在MCP-1等趋化因子作用下迁入组织，分化为巨噬细胞或树突状细胞。"},{"q":"可直接调节Ig类别转换的细胞是","o":["Th细胞","B细胞","Tc细胞","NK细胞","中性粒细胞"],"a":0,"e":"Th（Tfh）细胞分泌的细胞因子直接决定类别转换方向，IL-21驱动向IgG、TGF-β驱动向IgA、IL-4和IL-13驱动向IgE；B细胞是转换发生的场所。"},{"q":"下列哪种疾病不属于自身免疫病","o":["SLE","溃疡性结肠炎","重症肌无力","荨麻疹","甲状腺功能亢进"],"a":3,"e":"荨麻疹由变应原特异性IgE介导，属Ⅰ型超敏反应，肥大细胞脱颗粒释放组胺引起风团和红斑；SLE、重症肌无力、Graves病均由自身抗体或自身反应性T细胞致病。"},{"q":"细胞之间相互作用不受MHC限制的是","o":["CTL对肿瘤细胞的杀伤作用","NK细胞对肿瘤细胞的杀伤作用","APC对Th细胞的激活作用","CTL对病毒感染细胞的杀伤作用","Th细胞对B细胞的辅助作用"],"a":1,"e":"NK细胞杀伤不依赖TCR识别pMHC，其活化与抑制信号由自身受体与靶细胞配体决定，故不受MHC限制；CTL与靶细胞、Th与B细胞、APC与Th细胞间作用均受MHC限制。"},{"q":"主要由病毒感染的组织细胞合成和分泌的细胞因子是","o":["IFN-γ","TNF-α","TGF-β","IFN-α/β","TNF-β"],"a":3,"e":"病毒感染的组织细胞可合成并分泌IFN-α/β，诱导邻近细胞产生抗病毒蛋白；IFN-γ主要由活化T细胞和NK细胞产生。"},{"q":"当肺癌细胞表面由HLA-B位点编码的分子表达减少时，以下哪种细胞的抗肿瘤作用最可能下降","o":["NK细胞","CTL","巨噬细胞","γδ细胞","B细胞"],"a":1,"e":"CTL的TCR需识别肿瘤细胞表面抗原肽-MHCⅠ类分子复合物，HLA-B表达减少使CTL不能有效识别杀伤；NK细胞反因抑制信号缺失而被激活。"},{"q":"不表达MHCⅡ类分子的细胞是","o":["初始T细胞","初始B细胞","活化B细胞","活化巨噬细胞","成熟DC细胞"],"a":0,"e":"MHCⅡ类分子组成性表达于DC、巨噬细胞和B细胞等专职APC；初始T细胞只表达MHCⅠ类分子，活化后才可诱导表达MHCⅡ类分子。"},{"q":"IgE分子中，具有高亲和性、可结合到肥大细胞上的部位是","o":["Fab段","CH2功能区","H链恒定区","HVR区","Fc段"],"a":4,"e":"IgE为亲细胞抗体，通过Fc段与肥大细胞、嗜碱性粒细胞表面高亲和力FcεRⅠ结合而使之致敏，再次接触变应原即触发脱颗粒。"},{"q":"免疫增强疗法不宜用于","o":["感染","慢性皮肤过敏","肿瘤","炎症","艾滋病"],"a":3,"e":"免疫增强疗法用于感染、肿瘤和免疫缺陷（如艾滋病）等免疫功能低下状态；炎症时机体免疫应答已过度，需抗炎或免疫抑制治疗。"},{"q":"以下哪一项与肿瘤的免疫逃逸无关","o":["肿瘤细胞抗原的缺失","抗原调变","肿瘤细胞表达PD-L1分子","肿瘤细胞表达FasL分子","肿瘤细胞产生胚胎抗原"],"a":4,"e":"肿瘤胚胎抗原如AFP、CEA属基因异常表达的正常成分，是诊断标志而非逃逸机制；抗原缺失、抗原调变、表达PD-L1及FasL则分别逃避识别、抑制或杀伤效应细胞。"},{"q":"免疫缺陷病是指","o":["免疫系统先天发育不全或后天受损所致免疫功能降低或缺失的一组临床综合征","应用免疫抑制剂导致的免疫无应答状态","由于过度而持久的自身免疫反应导致组织器官损伤的一类疾病","机体对某些抗原所产生的非正常生理性免疫应答","机体经某种抗原诱导后形成的特异性免疫无应答状态"],"a":0,"e":"免疫缺陷病是先天或后天因素致免疫系统一个或多个组分发育障碍或功能受损，表现为抗感染能力低下、易患肿瘤和自身免疫病的一组临床综合征。"},{"q":"能产生IL-2、IFN-γ、TNF-α的细胞是","o":["Th2细胞","Th1细胞","巨噬细胞","NK细胞","B细胞"],"a":1,"e":"Th1细胞表达T-bet，主要分泌IFN-γ、TNF-α、IL-2、LT-α及GM-CSF，介导细胞免疫、辅助CTL并活化巨噬细胞；Th2以IL-4、IL-5、IL-10为主。"},{"q":"能够形成免疫耐受的细胞是","o":["B细胞和NK细胞","T细胞和NK细胞","T细胞和B细胞","B细胞和单核细胞","T细胞和单核细胞"],"a":2,"e":"免疫耐受按介导细胞分为T细胞耐受和B细胞耐受，中枢耐受分别在胸腺和骨髓形成，外周耐受由成熟T、B细胞在外周淋巴器官形成。"},{"q":"穿孔素分子不具有下列哪项特点","o":["与补体成分C9作用相似","可在靶细胞膜上聚合成孔道样结构","存在于CTL细胞的胞浆颗粒中","可使靶细胞发生凋亡","可使靶细胞发生溶解"],"a":3,"e":"穿孔素在靶细胞膜上聚合成孔道使细胞溶解，作用与补体C9相似；诱导靶细胞凋亡的是进入胞内的颗粒酶及Fas/FasL途径。"},{"q":"T细胞的自分泌生长因子是","o":["IL-2","IL-3与IL-5","IL-6与IL-8","IL-1与IL-7","EPO与TPO"],"a":0,"e":"活化T细胞约12小时即分泌IL-2并表达高亲和力IL-2受体，以自分泌方式作用于自身，是T细胞增殖和分化所必需的生长因子。"},{"q":"选择素家族成员胞膜外区CL结构域结合的组分是","o":["碳水化合物","脂类","核酸","多肽","LPS"],"a":0,"e":"选择素家族胞膜外区含凝集素（CL）结构域，可识别结合唾液酸化岩藻糖等碳水化合物基团，介导白细胞与活化内皮的黏附。"},{"q":"根据有效免疫原的氨基酸序列，设计和合成的免疫原性多肽属于","o":["结合疫苗","类毒素","合成肽疫苗","DNA疫苗","亚单位疫苗"],"a":2,"e":"合成肽疫苗依据有效抗原表位的氨基酸序列设计并合成免疫原性多肽，以最小的免疫原性多肽激发特异性应答，且避免病原体成分带来的安全风险。"},{"q":"集落刺激因子不包括","o":["EPO","TNF","TPO","GM-CSF","SCF"],"a":1,"e":"集落刺激因子包括GM-CSF、M-CSF、G-CSF、EPO、SCF和TPO，均刺激造血干/祖细胞增殖分化；TNF属肿瘤坏死因子家族。"},{"q":"ELISPOT的方法适用于","o":["血清抗体的检测","单细胞水平分泌细胞因子的检测","整体水平分泌细胞因子的检测","DNA检测","微量抗原的检测"],"a":1,"e":"ELISPOT将激活细胞分泌的细胞因子或抗体原位捕获于包被板，形成可计数斑点，可检测单细胞水平的分泌功能，灵敏度高于ELISA。"},{"q":"免疫毒素的作用有","o":["预防感染","治疗感染","预防肿瘤","治疗肿瘤","诊断肿瘤"],"a":3,"e":"免疫毒素由抗体或配体与毒素分子偶联而成，借抗体的特异性将毒素定向导入肿瘤细胞，属肿瘤的被动免疫治疗手段。"},{"q":"B细胞中枢耐受形成，描述错误的是","o":["不成熟B细胞遇自身Ag","可在骨髓及末梢中发生","仅在胚胎发育期发生","经克隆消除所致","需与自身Ag高亲和力结合"],"a":2,"e":"中枢耐受形成于B细胞在骨髓发育阶段，未成熟B细胞与骨髓中自身抗原高亲和力结合后经克隆清除或受体编辑形成，并非仅见于胚胎期。"},{"q":"抗肿瘤效应的第一道防线是","o":["NK细胞","中性粒细胞","Th细胞","B细胞","Tc细胞"],"a":0,"e":"NK细胞无需抗原预先致敏即可杀伤肿瘤细胞，是早期抗肿瘤的重要效应细胞，构成抗肿瘤的第一道防线；CTL属特异性免疫。"},{"q":"B细胞表面不表达的受体是","o":["BCR","HIV受体","EB病毒受体","CR1和CR2","FcγRⅡ"],"a":1,"e":"HIV以CD4为主要受体、CXCR4或CCR5为辅助受体感染细胞，B细胞不表达CD4，故无HIV受体；B细胞表面表达BCR、CR1和CR2、FcγRⅡ及EB病毒受体CD21。"},{"q":"全身性细菌感染时，补体活性片段发挥免疫效应作用主要通过","o":["细胞毒作用","ADCC作用","调理作用","清除免疫复合物","引起炎症反应"],"a":2,"e":"补体裂解产生的C3b、C4b结合于细菌表面，被吞噬细胞CR1识别，介导调理吞噬，是清除全身性细菌感染的主要效应；C3a、C5a主要介导炎症。"},{"q":"T细胞的阴性选择发生在","o":["血管","骨髓","淋巴结","脾","胸腺"],"a":4,"e":"阴性选择在胸腺皮质和髓质进行，自身反应性DP或SP细胞与胸腺上皮细胞、DC提呈的自身抗原肽-MHC高亲和力结合后凋亡，自身反应性克隆被清除。"},{"q":"具有免疫抑制功能的T细胞分泌IL-10可介导的作用是","o":["抑制iDC分化为成熟DC","促进iDC诱导免疫耐受","促进中枢耐受","抑制iDC分化为成熟DC、促进iDC诱导免疫耐受、促进中枢耐受","抑制iDC分化为成熟DC、促进iDC诱导免疫耐受"],"a":4,"e":"调节性T细胞分泌IL-10和TGF-β，抑制未成熟DC分化为成熟DC，使其维持耐受性表型，从而诱导外周免疫耐受，与中枢耐受无关。"},{"q":"FcγRⅡb基因多态性和全身性系统性红斑狼疮的发病相关。直接致病机制是","o":["B细胞过度活化，抑制信号不足","促B细胞生长因子BAFF水平异常","调节性T细胞功能缺陷","T细胞过度活化，抑制信号不足","活化诱导的细胞死亡机制异常"],"a":0,"e":"FcγRⅡb是B细胞表面含ITIM的抑制性受体，其基因多态性使抑制信号减弱，B细胞对自身抗原过度活化，产生大量自身抗体。"},{"q":"下列哪个分子为B细胞抗原特异性识别受体","o":["CD2","MHCⅡ","MHCⅠ","BCR","TCR"],"a":3,"e":"BCR是B细胞膜表面的膜型免疫球蛋白，能特异性识别、结合并摄取抗原，是B细胞特有的抗原识别受体。"},{"q":"外周耐受中自身抗原应答的T细胞克隆清除表述正确的是","o":["TCR对组织特异自身抗原具有高亲和力","经APC提呈致此类T细胞克隆清除","这种组织特异自身抗原浓度高","TCR对组织特异自身抗原具有高亲和力、经APC提呈致此类T细胞克隆清除、这种组织特异自身抗原浓度高","TCR对组织特异自身抗原具有高亲和力、经APC提呈致此类T细胞克隆清除"],"a":3,"e":"外周组织中浓度较高的组织特异性自身抗原经APC摄取提呈，表达高亲和力TCR的自身反应性T细胞接受强信号后被诱导凋亡，即外周克隆清除。"},{"q":"以下关于补体系统的描述正确的是","o":["是存在于人和脊椎动物血清与组织液中的一组耐热蛋白质","本身具有酶活性，不需要活化的一组蛋白质","与炎症反应无关","包括30余种可溶性蛋白和膜结合蛋白","属于固有免疫系统成分，不参与特异性免疫应答"],"a":3,"e":"补体系统由30余种可溶性蛋白和膜结合蛋白组成，多为不耐热的酶原，需经级联活化才具活性，既参与固有免疫又调节适应性免疫应答。"},{"q":"最易诱导免疫耐受的细胞是","o":["T细胞","B细胞","巨噬细胞","单核细胞","NK细胞"],"a":0,"e":"T细胞耐受形成快、维持时间长，所需抗原量少，故最易诱导耐受；B细胞耐受形成慢、维持时间短，需较大剂量抗原。"},{"q":"Ig分子的独特型决定簇存在于","o":["重链C区","轻链C区","重链Ⅴ区","轻链V区","重链和轻链的V区"],"a":4,"e":"独特型决定簇即独特位，位于抗体分子重链和轻链的V区高变区，为每个抗体克隆所特有，可诱导抗独特型抗体产生。"},{"q":"TD-Ag诱导B细胞活化的第二信号是","o":["抗原信号","BCR提供的信号","树突状细胞提供的信号","FC受体提供的信号","Th细胞提供的信号"],"a":4,"e":"TD抗原激活B细胞的第一信号由BCR结合抗原产生，第二信号由Th细胞即Tfh细胞表面CD40L与B细胞CD40结合提供。"},{"q":"下列哪个分子可作为人造血干细胞的主要表面标记分子","o":["CD2","CD3","CD8","CD9","CD34"],"a":4,"e":"CD34是造血干细胞的主要表面标志，表达于造血干/祖细胞，可用于分选造血干细胞进行移植和基因治疗；CD2、CD3、CD8为T细胞标志。"},{"q":"下列哪项不属于AIDS的典型临床特点","o":["机会性感染","心、脾衰竭","恶性肿瘤","神经系统疾病","发热、体重减轻、腹泻等AIDS相关症候群"],"a":1,"e":"AIDS发病期表现为机会性感染、恶性肿瘤、神经系统病变及发热、消瘦、腹泻等AIDS相关症候群，晚期可出现肾衰竭，而非心、脾衰竭。"},{"q":"交叉配型对于以下哪种器官移植尤为重要","o":["肝脏移植","心脏移植","肺移植","骨髓移植","肾脏移植"],"a":3,"e":"骨髓和造血干细胞移植物富含免疫细胞，易发生GVHR，且供受者间次要组织相容性抗原差异多，故除HLA配型外必须交叉配型以检出受者预存抗体。"},{"q":"下面与胚胎抗原无关的是","o":["当细胞恶变时，此类抗原可重新合成","可以用于某些肿瘤的临床诊断","能引起宿主免疫系统对这种抗原的免疫应答","由胚胎组织产生","出生后逐渐消失或仅存留极微量"],"a":2,"e":"胚胎抗原由胚胎组织产生，出生后逐渐消失或仅存微量，细胞恶变时重新合成，可用作肿瘤辅助诊断；因属自身成分，不诱导宿主免疫应答。"},{"q":"位于免疫突触中央的分子对是","o":["TCR/抗原肽-MHC分子复合物","CD2/LFA-3","CD28/B7","CD40L/CD40","LFA-1/ICAM-1"],"a":0,"e":"免疫突触以TCR与抗原肽-MHC分子复合物为中心聚集，周围环绕CD28/B7、LFA-1/ICAM-1等黏附与共刺激分子对。"},{"q":"MHCⅡ类分子抗原提呈途径中，HLA-DM分子的作用是","o":["引导MHCⅡ类分子进入内体","解离抗原肽结合槽中的CLIP","引导抗原肽进入内体","促进MHCⅡ分子的折叠与装配","降解抗原肽结合槽中的Ii"],"a":1,"e":"Ii在MⅡC中被降解，仅留CLIP占据MHCⅡ类分子抗原肽结合槽，HLA-DM催化CLIP解离，使高亲和力抗原肽得以结合，形成稳定的抗原肽-MHCⅡ类分子复合物。"},{"q":"半抗原","o":["除非与载体结合，否则不能与抗体结合","是大分子物质","通常具有多肽的性质","本身不具有免疫原性","只能触发体液免疫"],"a":3,"e":"半抗原为结构简单的小分子，仅有免疫反应性而无免疫原性，须与蛋白质载体偶联后才能诱导免疫应答并产生相应抗体。"},{"q":"参与T细胞与APC细胞间非特异性相互作用的T细胞表面分子有","o":["LFA-1","LFA-3","CD40","CD80","CD86"],"a":0,"e":"LFA-1是T细胞表面黏附分子，与APC表面ICAM-1结合介导两者非特异性结合；CD80、CD86、CD40表达于APC，LFA-3为APC表面配体。"},{"q":"GVHR主要见于","o":["肾脏移植","心脏移植","骨髓移植","肺脏移植","脾脏移植"],"a":2,"e":"骨髓、造血干细胞等富含免疫细胞的移植物中，供者T细胞攻击受者组织器官引起GVHR；一般实质器官移植以宿主抗移植物反应为主。"},{"q":"介导Ⅰ型超敏反应速发相的最主要介质是","o":["组胺","白三烯","肝素","腺苷酸环化酶","血小板活化因子"],"a":0,"e":"速发相在再次接触变应原后数秒至数分钟内发生，主要由肥大细胞脱颗粒释放的组胺引起，使血管扩张、通透性增高和平滑肌收缩。"},{"q":"关于细胞因子的基本特征，叙述错误的是","o":["以特异性方式发挥作用","合成和分泌是一种自我调控的过程","可诱导产生","在较低浓度下即可发挥生物学活性","作用效应具有多样性"],"a":0,"e":"细胞因子通过受体介导发挥作用，无抗原特异性，具多效性、重叠性和网络性，极低浓度即可产生显著生物学效应。"},{"q":"关于生发中心的FDC，以下说法正确的是","o":["这是B细胞分化中的一个阶段","这是一种脂肪细胞","始终与T细胞接触","这是具备抗原提呈能力的DC","可将抗原浓缩、滞留在细胞表面"],"a":4,"e":"FDC借CR1、CR2和Fc受体捕获抗原-抗体复合物，长期滞留并浓缩于细胞表面供B细胞识别；FDC不表达MHCⅡ类分子，无抗原提呈能力。"},{"q":"交感性眼炎的主要致病机制是由于","o":["分子模拟","表位扩展","隐蔽抗原的释放","自身抗原被修饰","超抗原激活"],"a":2,"e":"眼晶状体蛋白属隐蔽抗原，外伤后释放入血液和淋巴液，激活自身反应性T细胞，攻击健侧眼组织而引起交感性眼炎。"},{"q":"MHC分子中不形成抗原结合槽的结构域是","o":["Ⅱ类分子的α1","Ⅱ类分子的β1","Ⅱ类分子的α2和β2","Ⅰ类分子的α1","Ⅰ类分子的α2"],"a":2,"e":"HLAⅡ类分子由α1和β1结构域共同构成抗原结合槽，α2与β2为Ig样结构域；Ⅰ类分子则由α1和α2形成抗原结合槽。"},{"q":"MHCⅠ类分子抗原提呈途径中，负责降解内源性抗原的分子是","o":["LMP","TAP","CLIP","HLA-DM","Ii"],"a":0,"e":"IFN-γ诱导产生的低分子量多肽LMP取代蛋白酶体催化亚单位形成免疫蛋白酶体，降解内源性抗原；TAP负责转运抗原肽。"},{"q":"下列哪个分子通常不在T细胞表面存在","o":["CD2","CD3","MHCⅠ","BCR","TCR"],"a":3,"e":"BCR是B细胞特异性识别和摄取抗原的膜型Ig；T细胞表面表达TCR、CD3、CD2及MHCⅠ类分子，不表达BCR。"},{"q":"下列属于成熟DC的是","o":["并指状DC","血液DC","朗格汉斯细胞","间质DC","隐蔽细胞"],"a":0,"e":"并指状DC是迁移至淋巴结T细胞区的成熟DC；朗格汉斯细胞、间质DC和血液DC均为未成熟DC，隐蔽细胞为淋巴管中的迁移期DC。"},{"q":"以下关于T细胞表位的描述，错误的是","o":["由TCR识别","由少于20个氨基酸组成","需要蛋白酶降解后才能释放","识别具有MHC限制","既有线性表位，又有构象表位"],"a":4,"e":"T细胞表位为蛋白抗原经APC加工后的线性表位肽，由连续排列的氨基酸构成；构象表位由不连续氨基酸经空间折叠形成，属B细胞表位。"},{"q":"与风湿性心脏病的发病机制有关的主要是","o":["免疫忽视的打破","表位扩展","分子模拟","免疫隔离部位抗原的释放","自身抗原发生改变"],"a":2,"e":"乙型溶血性链球菌的M蛋白等成分与人心肌抗原存在共同表位，抗链球菌抗体和效应T细胞交叉攻击心肌，引起风湿性心脏瓣膜病，属分子模拟。"},{"q":"由病毒编码的肿瘤抗原是","o":["CEA","MAGE-1","E1A抗原","AFP","P53蛋白"],"a":2,"e":"人腺病毒转化细胞表达的E1A抗原由病毒基因编码；CEA和AFP为胚胎抗原，MAGE-1为静止基因活化产物，突变p53为基因突变产物。"},{"q":"关于Th17细胞的叙述，错误的是","o":["Th17细胞分泌IL-21促进Th17细胞的扩增","Th17细胞分泌IL-23维持与稳定Th17细胞的特征","Th17细胞可分泌大量IL-22","Th17细胞参与病理性肠道炎症","TGF-β抑制Th17细胞分化"],"a":4,"e":"TGF-β与IL-6、IL-1β共同诱导Th0向Th17分化，是Th17分化的促进因素而非抑制因素；IL-21促进Th17扩增，IL-23维持其表型稳定。"},{"q":"由Ⅳ型超敏反应引起的自身免疫病是","o":["自身免疫性溶血性贫血","毒性弥漫性甲状腺肿","重症肌无力","系统性红斑狼疮","1型糖尿病"],"a":4,"e":"1型糖尿病由CTL持续破坏胰岛β细胞所致，属T细胞介导的Ⅳ型超敏反应性自身免疫病；自身免疫性溶血性贫血、重症肌无力、Graves病由自身抗体介导。"},{"q":"提供T细胞活化的第二信号的分子对是","o":["CD28-B7","CD4-MHCⅡ类分子","CD8-MHCⅠ类分子","TCR-抗原肽","TCR-MHC分子"],"a":0,"e":"T细胞表面的CD28与APC表面B7（CD80/CD86）结合提供第二信号；TCR识别抗原肽-MHC复合物为第一信号，CD4、CD8为共受体。"},{"q":"以下属于Ⅱ型超敏反应性疾病的是","o":["新生儿溶血症","系统性红斑狼疮","血清病","接触性皮炎","青霉素过敏性休克"],"a":0,"e":"新生儿溶血症由母体抗Rh的IgG经胎盘进入胎儿体内，与胎儿红细胞结合后激活补体并介导调理吞噬而溶血，属Ⅱ型超敏反应；血清病为Ⅲ型，接触性皮炎为Ⅳ型。"},{"q":"CTLA4的配体是","o":["CD28","CD40L","CD79a/CD79b","CD80/CD86","LFA-1"],"a":3,"e":"CTLA-4与CD28共享配体B7（CD80/CD86），但亲和力更高，竞争性结合后传递抑制信号；CTLA-4/Ig融合蛋白即借此阻断共刺激。"},{"q":"关于中性粒细胞正确的叙述是","o":["来源于淋巴样前体细胞","含有嗜天青颗粒","主要功能为巡视、清除病原微生物","在慢性炎症中起关键作用","可与IgE结合"],"a":2,"e":"中性粒细胞起源于骨髓髓样前体细胞，是固有免疫中数量最多的吞噬细胞，受炎症刺激迅速迁移至感染灶，吞噬并杀伤清除病原微生物，为急性炎症的主要细胞。"},{"q":"介导T细胞抑制的共刺激分子","o":["CD4","CD8","CD16","CD28","CTLA-4"],"a":4,"e":"CTLA-4是共抑制分子，表达于活化的T细胞，与CD80/CD86结合后招募磷酸酶、阻断共刺激信号，从而抑制T细胞活化与增殖；CD28则提供活化信号。"},{"q":"与诱发慢性哮喘无关的因素是","o":["Th2细胞","嗜酸性粒细胞","IL-4","IFN-γ","嗜酸性粒细胞趋化因子"],"a":3,"e":"慢性哮喘由Th2细胞、嗜酸性粒细胞、IL-4、IL-5、IL-13及嗜酸性粒细胞趋化因子介导的气道慢性炎症所致；IFN-γ属Th1型细胞因子，起拮抗作用。"},{"q":"特异性细胞免疫的效应细胞是","o":["Th1细胞和Th0细胞","Th1细胞和CTL细胞","Th0细胞和Th2细胞","Th0细胞和CTL细胞","Th2细胞和Th17细胞"],"a":1,"e":"Th1细胞通过分泌IFN-γ等引起以单核/巨噬细胞浸润为主的炎症，CTL特异性杀伤靶细胞，二者共同构成特异性细胞免疫的效应细胞。"},{"q":"合成和分泌抗体的细胞是","o":["B细胞","Th1","Th2","浆细胞","CTL"],"a":3,"e":"B细胞受抗原刺激后分化为浆细胞，其为终末细胞，胞质富含粗面内质网，能大量合成并分泌特异性抗体；B细胞本身以膜Ig构成BCR，不分泌抗体。"},{"q":"人类B细胞分化成熟的场所是","o":["胸腺","骨髓","法氏囊","淋巴结","脾"],"a":1,"e":"人类B细胞在骨髓中分化成熟，骨髓为中枢免疫器官；鸟类B细胞在法氏囊成熟，胸腺则是T细胞分化成熟场所。"},{"q":"下列细胞因子中，对T细胞增殖分化没有作用的是","o":["IL-2","IL-6","IL-8","IL-10","IL-12"],"a":2,"e":"IL-8即CXCL8，是趋化因子，主要趋化和活化中性粒细胞，不参与T细胞增殖分化；IL-2、IL-6、IL-10、IL-12均影响T细胞。"},{"q":"绝大多数T细胞分化成熟的场所是","o":["骨髓","法氏囊","脾脏","胸腺","淋巴结"],"a":3,"e":"T细胞来源于骨髓的淋巴样干细胞，在胸腺微环境经阳性和阴性选择发育为成熟T细胞并迁出；骨髓则是B细胞发育成熟的场所。"},{"q":"肿瘤免疫学的理论和实践基础在于肿瘤细胞具有","o":["肿瘤抗原","共刺激分子","MHCⅠ类分子","MHCⅡ类分子","免疫抑制分子"],"a":0,"e":"肿瘤细胞表达肿瘤特异性抗原和肿瘤相关抗原，是免疫系统识别与攻击的靶点，也是肿瘤免疫诊断、免疫治疗及预后判断的分子基础。"},{"q":"能刺激B淋巴细胞的分化增殖，产生抗体的细胞因子是","o":["Th1分泌的细胞因子","Th2分泌的细胞因子","Th3分泌的细胞因子","Th17分泌的细胞因子","Th22分泌的细胞因子"],"a":1,"e":"Th2细胞分泌IL-4、IL-5、IL-6、IL-10、IL-13等，可促进B细胞增殖、分化和类别转换并辅助抗体生成；Th1细胞主要介导细胞免疫。"},{"q":"对巨噬细胞具有趋化和激活作用的是","o":["IL-1","IL-6","IL-8","MIP-1α/β","TNF-α"],"a":3,"e":"CCL3（MIP-1α）和CCL4（MIP-1β）可趋化和活化巨噬细胞，IFN-γ、GM-CSF亦增强其功能；IL-8趋化中性粒细胞，MCP-1主要募集单核细胞。"},{"q":"有关环孢素A的描述错误的是","o":["主要作用是降低T细胞活性","抑制细胞因子的释放","用于治疗急性移植排斥反应","从真菌代谢产物中提取","也用于治疗肿瘤"],"a":4,"e":"环孢素A从真菌代谢产物中提取，与亲环素结合后抑制钙调磷酸酶，阻断IL-2基因转录，用于防治移植排斥和自身免疫病，不用于治疗肿瘤。"},{"q":"MBL活化途径的最主要的C3转化酶是","o":["C1s","C4b2a","C3bBb","C3bBbP","D因子"],"a":1,"e":"MBL与病原体表面甘露糖残基结合后，由MASP活化C4和C2，形成C4b2a作为C3转化酶，继而形成C4b2a3b裂解C5。"},{"q":"目前临床上肾脏移植面临的主要困难之一是移植排斥反应，请问诱导该反应的主要抗原属于","o":["Forssmann抗原","异种抗原","同种异型抗原","血型抗原","独特型抗原"],"a":2,"e":"供受者间HLA等位基因差异所表达的多态性产物属同种异型抗原，是引起同种移植排斥的主要组织相容性抗原。"},{"q":"关于抗体，下列描述错误的是","o":["抗体都是体外产生的","抗体主要存在于血液、体液、黏膜表面及分泌液中","抗体是能与相应抗原特异性结合的球蛋白","抗体都是免疫球蛋白","抗体是指具有免疫功能的球蛋白"],"a":0,"e":"抗体由B细胞受抗原刺激后分化为浆细胞在体内产生，其化学本质为球蛋白，主要存在于血清、体液和黏膜分泌液中。"},{"q":"TD-Ag引起免疫应答的特点是","o":["产生体液免疫应答的细胞为B1细胞","只引起体液免疫应答，不引起细胞免疫应答","可诱导T、B淋巴细胞产生免疫应答","只引起细胞免疫应答，不能引起体液免疫应答","不可诱导免疫记忆细胞形成"],"a":2,"e":"胸腺依赖性抗原同时含T细胞表位和B细胞表位，需Th细胞辅助才能激活B细胞，故既诱导体液免疫又诱导细胞免疫，并产生免疫记忆。"},{"q":"辅助性T细胞的表面标志之一","o":["CD4","CD5","CD8","CD19","CD21"],"a":0,"e":"辅助性T细胞表达CD4与TCRαβ-CD3复合物，CD4是MHCⅡ类分子的共受体，结合其β2结构域并辅助TCR识别；CD8为CTL标志，CD19、CD21为B细胞标志。"},{"q":"γδT细胞所不能识别的抗原是","o":["表达于感染细胞表面的热休克蛋白","表达于感染细胞表面的CD1分子提呈的脂类抗原","表达于APC表面的抗原肽-MHC分子复合物","表达于感染细胞表面的某些病毒蛋白","表达于感染细胞表面的磷酸化抗原"],"a":2,"e":"γδT细胞识别热休克蛋白、脂类、多糖和磷酸化抗原，不受经典MHC限制；抗原肽-MHC复合物由αβT细胞的TCR识别。"},{"q":"NK细胞所不具备的作用和特征是","o":["表达杀伤活化受体","具有免疫调节作用","表达IgFc受体","具有吞噬作用","表达杀伤抑制受体"],"a":3,"e":"NK细胞表达杀伤活化受体和抑制性受体，具免疫调节及ADCC作用，但无吞噬功能；吞噬由巨噬细胞和中性粒细胞执行。"},{"q":"HLAⅡ类分子与抗原肽结合的部位是","o":["α1和β1结构域","α1和α2结构域","β1和β2结构域","α1和β2m结构域","α2和β2m结构域"],"a":0,"e":"HLAⅡ类分子α链和β链的胞外段各有α1、α2和β1、β2两个结构域，其中α1和β1共同围成抗原结合槽，两端开放，容纳13～17个氨基酸的抗原肽。"},{"q":"HLA基因分型已在法医上被用于对死亡者“验明正身”，其依据是","o":["高度多态性","共显性表达","连锁不平衡","HLA基因高度易变","HLA基因易重组"],"a":0,"e":"HLA是人体多态性最丰富的基因系统，已命名等位基因近4万个，随机个体间基因型几乎不可能相同，故可用于个体识别和亲子鉴定。"},{"q":"TIL治疗肿瘤属于","o":["过继免疫","人工主动免疫","自然主动免疫","自然被动免疫","人工主动免疫和自然主动免疫相结合"],"a":0,"e":"将体外扩增活化的肿瘤浸润淋巴细胞回输荷瘤宿主体内直接杀伤肿瘤，属过继免疫细胞治疗，为被动免疫而非主动免疫。"},{"q":"T细胞活化后表达的抑制性分子是","o":["CTLA-4","KAR","TCR","IL-1R","IL-2R"],"a":0,"e":"CTLA-4于T细胞活化后诱导表达，与B7结合的亲和力高于CD28，竞争性结合后传递抑制信号，下调或终止T细胞应答。"},{"q":"参与同种异体移植排斥反应的关键效应细胞是","o":["T淋巴细胞","B淋巴细胞","NK细胞","巨噬细胞","DC"],"a":0,"e":"同种反应性T细胞是参与同种异型移植排斥反应的关键效应细胞，包括直接识别供者APC的CD4+和CD8+T细胞，介导急性细胞性排斥。"},{"q":"B细胞以BCR介导内化抗原后，其抗原肽-MHC分子复合物形成的部位","o":["细胞膜","内质网","MHC-Ⅱ类小室","高尔基体","蛋白酶体"],"a":2,"e":"B细胞经BCR介导内吞抗原后，抗原在MⅡC即MHCⅡ类小室中被组织蛋白酶降解，并在HLA-DM辅助下与MHCⅡ类分子结合形成抗原肽-MHCⅡ类分子复合物。"},{"q":"对TI-1抗原叙述错误的是","o":["常被称为B细胞丝裂原","诱导B细胞应答比TD-Ag早","低浓度时特异活化相应B细胞","高浓度时多克隆活化B细胞","可诱导记忆性B细胞"],"a":4,"e":"TI-1抗原单独刺激不足以诱导抗体类别转换、亲和力成熟和记忆B细胞形成，这些是TD抗原应答的特征；其低浓度激活特异性B细胞，高浓度多克隆活化B细胞。"},{"q":"人工被动免疫制剂不包括","o":["破伤风抗毒素","静脉注射用人免疫球蛋白","胎盘免疫球蛋白","白喉类毒素","人狂犬病免疫球蛋白"],"a":3,"e":"白喉类毒素是外毒素经甲醛脱毒制成，接种后诱导机体主动产生抗体，属人工主动免疫；其余均为含抗体的被动免疫制剂。"},{"q":"下列哪一过程不需要APC的参与","o":["T细胞的充分活化","T细胞的发育成熟","CTL的细胞毒效应","胸腺细胞的阴性选择","T细胞的中枢耐受"],"a":2,"e":"CTL经TCR识别靶细胞表面抗原肽-MHCⅠ类分子复合物后直接杀伤靶细胞，此过程不需APC参与；T细胞活化、发育和阴性选择均依赖APC或胸腺基质细胞。"},{"q":"T细胞表面传递抗原识别信号的分子是","o":["CD2","CD3","CD4","CD8","CD28"],"a":1,"e":"TCR识别pMHC后，由与之非共价结合的CD3分子胞内段ITAM传递活化信号；CD4、CD8为共受体，CD28传递共刺激信号。"},{"q":"能与免疫球蛋白Fc段补体结合点相结合的补体成分是","o":["C4","C1q","C1r","C1s","C2"],"a":1,"e":"抗体与抗原结合后构象改变，暴露Fc段补体结合位点并与C1q的球状头部结合，启动C1r、C1s活化，进而形成C3转化酶，起始经典途径。"},{"q":"活化后可产生大量Ⅰ型干扰素的DC是","o":["滤泡样DC","并指状DC","朗格汉斯细胞","间质DC","浆细胞样DC"],"a":4,"e":"浆细胞样DC来源于共同淋巴样前体，活化后经TLR7/9识别病毒核酸，快速产生大量Ⅰ型干扰素参与抗病毒固有免疫；经典DC主要承担抗原提呈。"},{"q":"以下关于抗原交叉反应性的叙述，错误的是","o":["不同蛋白质抗原间可能存在交叉反应","不同半抗原间可能存在交叉反应","抗原之间存在交叉反应的结构基础是拥有共同抗原表位","具有交叉反应性的不同抗原称为交叉抗原","接种牛痘疫苗可以预防天花，就是因为抗原间的交叉反应性"],"a":1,"e":"交叉反应的分子基础是共同抗原表位，蛋白质等大分子抗原间可因此交叉反应，接种牛痘预防天花即典型例证；半抗原须与载体偶联才具免疫原性，不同半抗原之间不构成交叉抗原。"},{"q":"可促进Th2细胞生成的细胞因子是","o":["IL-2","IL-4","IL-12","IFN-γ","TGF-β"],"a":1,"e":"IL-4是诱导Th0向Th2分化的关键细胞因子，并上调转录因子GATA3；IL-12、IFN-γ则诱导向Th1分化。"},{"q":"传递B细胞活化信号到细胞质中的主要是","o":["CD4","CD19","CD21","CD79","BCR"],"a":3,"e":"BCR复合物中CD79a/CD79b胞质区含ITAM，磷酸化后募集Syk等下游分子，将BCR识别抗原的信号转入胞内；CD19为共受体。"},{"q":"传递TCR识别抗原信号的分子是","o":["CD2","CD3","CD4","CD5","CD8"],"a":1,"e":"CD3与TCR非共价结合成TCR-CD3复合物，其胞质区含ITAM，TCR识别pMHC后由CD3向胞内传递活化信号，CD4、CD8仅作为共受体起辅助作用。"},{"q":"下列哪一项不属于自身免疫病的防治原则","o":["去除引起免疫耐受异常的因素","补充免疫分子以增强机体的免疫功能","抑制对自身抗原的免疫应答","重建对自身抗原的特异性免疫耐受","预防和控制微生物感染"],"a":1,"e":"自身免疫病的防治包括去除诱因、抑制对自身抗原的免疫应答、重建特异性免疫耐受及预防控制感染；补充免疫分子增强免疫功能属免疫增强疗法。"},{"q":"新生儿从母乳中获得的抗体是","o":["IgG类抗体","IgM类抗体","IgA类抗体","IgD类抗体","IgE类抗体"],"a":2,"e":"母乳尤其初乳富含SIgA，婴儿经哺乳获得，属自然被动免疫，可保护消化道和呼吸道黏膜，减少肠道和呼吸道感染。"},{"q":"关于阳性选择，以下说法正确的是","o":["阳性选择发生于SP细胞","发生于胸腺皮质","经过阳性选择，DP分化为成熟T细胞","获得自身免疫耐受","获得TCR多样性"],"a":1,"e":"阳性选择发生在胸腺皮质，DP细胞的TCR与皮质胸腺上皮细胞表面自身抗原肽-MHC分子以适当亲和力结合后存活，并分化为单阳性细胞。"},{"q":"细胞增殖程度除用3H-TdR掺入法外，还可应用的检测方法是","o":["LDH释放法","MTT比色法","ADCC试验","ELISA","ELISOP法"],"a":1,"e":"MTT被活细胞线粒体脱氢酶还原为甲臜，其生成量与活细胞数成正比，可反映细胞增殖；LDH释放法测细胞毒性，ELISA测可溶性分子。"},{"q":"与HLAⅠ类分子结合的CD分子是","o":["CD2","CD3","CD4","CD8","CD152"],"a":3,"e":"CD8是MHCⅠ类分子的共受体，其α链胞膜外的Ig样结构域结合MHCⅠ类分子重链α3结构域，辅助TCR识别内源性抗原肽；CD4则结合MHCⅡ类分子。"},{"q":"用于肾衰竭导致的贫血、癌症或癌症化疗导致的贫血、失血后贫血的细胞因子首选","o":["G-CSF","EPO","SCF","TNF-α","IL-11"],"a":1,"e":"EPO作用于红系祖细胞，促进其增殖分化，故慢性肾衰竭、肿瘤化疗及失血所致贫血均以EPO为首选；G-CSF主要升高中性粒细胞。"},{"q":"HLA完全相同的供受者间进行移植，发生排斥反应的原因是","o":["移植物没有充分血液供应","受者产生封闭抗体","供者患有先天免疫缺陷","常染色体编码的mH抗原不匹配","受者患有后天免疫缺陷"],"a":3,"e":"HLA相合的供受者间仍可因次要组织相容性抗原不匹配而排斥，此类抗原包括Y染色体基因编码产物及常染色体编码的mH抗原。"},{"q":"成熟DC不具有以下哪些特点","o":["高表达MHCⅡ类分子","高表达共刺激分子","能活化初始T细胞","摄取加工抗原的能力强","提呈抗原的能力强"],"a":3,"e":"成熟DC低表达模式识别受体，识别和摄取、加工抗原的能力弱，但高表达MHCⅡ类分子和共刺激分子，提呈抗原、激活初始T细胞的能力强。"},{"q":"下列可引起Ⅲ型超敏反应的物质是","o":["细胞因子","单核巨噬细胞","IgA","IgE","免疫复合物"],"a":4,"e":"Ⅲ型超敏反应由中等大小可溶性免疫复合物沉积于血管基底膜、激活补体并招募中性粒细胞所致，致病的核心是免疫复合物而非单纯抗原或抗体。"},{"q":"下列哪一项与自身免疫病的发生无关","o":["胸腺功能异常","EB病毒感染","胆囊炎","输精管结扎","眼外伤"],"a":2,"e":"胆囊炎为胆道感染性疾病，与自身免疫无关；EB病毒感染、输精管结扎和眼外伤可分别经交叉反应和隐蔽抗原释放诱发自身免疫病。"},{"q":"以下关于抗原的叙述错误的是","o":["免疫学的本质是区别“自己”和“非己”，非己物质就是抗原","抗原是指所有能激活和诱导免疫应答的物质","抗原是免疫分子的重要组成部分","抗原通常是指能被TCR或BCR特异性识别的物质","机体免疫细胞识别的抗原通常是蛋白质"],"a":2,"e":"抗原是能被TCR或BCR特异性识别的物质，是免疫应答的靶标；免疫分子指抗体、补体、细胞因子及膜分子等，抗原不属免疫分子。"},{"q":"BCR识别抗原产生的活化信号传导是通过","o":["Igα和Igβ","CD19","CD21","CD40","CD81"],"a":0,"e":"BCR胞质区短，抗原信号由BCR复合物中Igα/Igβ即CD79a/CD79b胞质区ITAM磷酸化后募集下游分子转导；CD19为共受体。"},{"q":"可与iC3b及C3d结合，增强B细胞对抗原应答的分子是","o":["CD2","CD19","CD21","CD28","CD40"],"a":2,"e":"CD21（CR2）可结合包被于抗原上的C3d和iC3b，带动CD19向BCR聚集，显著增强BCR信号并降低B细胞活化阈值。"},{"q":"B1细胞主要存在于","o":["腹膜腔和派氏集合淋巴结中","肠道固有层和派氏集合淋巴结中","腹膜腔和脾脏中","扁桃体和腹膜腔中","肠道固有层和腹膜腔中"],"a":4,"e":"B1细胞主要定居于腹膜腔、胸膜腔和肠道黏膜固有层，约占B细胞5%～10%，具自我更新能力，可自发分泌天然抗体IgM。"},{"q":"诊断布氏菌病的瑞特试验属于","o":["反向间接凝集","间接凝集","直接凝集","协同凝集","间接凝集抑制"],"a":2,"e":"瑞特试验以布氏菌悬液作颗粒性抗原，直接与患者血清中相应抗体结合出现凝集，属直接凝集反应；间接凝集需先将可溶性抗原吸附于载体颗粒。"},{"q":"免疫功能相关基因中与炎症和应激反应密切相关的基因是","o":["Bf基因","TAP基因","PSMB基因","HSP70基因","HLA-DM基因"],"a":3,"e":"HSP70基因家族位于HLAⅢ类基因区，其产物作为分子伴侣参与应激和炎症反应；TAP、PSMB、HLA-DM基因均与抗原加工提呈有关。"},{"q":"中和作用最强的Ig是","o":["IgM","IgG","IgE","IgA","IgD"],"a":1,"e":"IgG在血清和胞外液中含量最高、分布最广、亲和力高，是抗感染的主力抗体，其中和毒素和病毒的作用最强；IgM分子量大但亲和力较低。"},{"q":"Th2细胞分泌的能刺激嗜酸性粒细胞分化的细胞因子是","o":["IL-2","IL-5","IL-6","IL-8","IL-10"],"a":1,"e":"IL-5由Th2细胞分泌，促进嗜酸性粒细胞增殖、分化和活化并趋化其聚集，是抗寄生虫免疫和Ⅰ型超敏反应的重要细胞因子。"},{"q":"HLA分子多态性的主要原因是","o":["连锁不平衡","HLA基因是复等位基因","HLA分子可以裂解","HLA基因高度易变","HLA基因发生有效重组机会较多"],"a":1,"e":"HLA复合体是人体多态性最丰富的基因系统，同一基因座位存在众多复等位基因，且呈共显性表达，构成群体中HLA型别的高度多样性。"},{"q":"与体液免疫应答异常有关的免疫缺陷病是","o":["X连锁无丙种球蛋白血症","阵发性夜间血红蛋白尿","慢性肉芽肿病","WAS","遗传性血管神经性水肿"],"a":0,"e":"X连锁无丙种球蛋白血症由BTK基因突变致B细胞发育阻滞，血清各型Ig极度降低，反复发生化脓性细菌感染，属原发性B细胞缺陷。"},{"q":"对食物过敏的最佳预防方法是","o":["脱敏治疗","免疫生物疗法","过敏反应试验","避免接触过敏原","服用抗过敏药"],"a":3,"e":"过敏性疾病由变应原介导，检出并避免接触变应原是最有效的防治方法；脱敏治疗和药物治疗属替代或对症手段。"},{"q":"MHC分子参与下列哪种细胞的分化过程","o":["红细胞","中性粒细胞","嗜酸性粒细胞","嗜碱性粒细胞","T细胞"],"a":4,"e":"MHC分子在胸腺内介导T细胞的阳性选择和阴性选择，决定T细胞发育成熟及MHC限制性；红细胞和粒细胞的分化不依赖MHC。"},{"q":"补体活性片段所不具备的生物学作用是","o":["调理作用","炎症介质作用","中和作用","免疫调节作用","清除免疫复合物作用"],"a":2,"e":"补体活性片段可介导调理吞噬、炎症介质作用、免疫调节和清除免疫复合物；中和作用由抗体Fab段封闭病原体结合位点完成，不属补体功能。"},{"q":"EB病毒的受体是","o":["CD2","CD8","CD19","CD21","CD28"],"a":3,"e":"CD21即CR2，是B细胞共受体成分，也是EB病毒受体，病毒经CD21进入B细胞，与传染性单核细胞增多症和B细胞淋巴瘤发生相关。"},{"q":"介导Ⅰ型超敏反应晚期相的最主要介质是","o":["组胺","白三烯","肝素","腺苷酸环化酶","血小板活化因子"],"a":1,"e":"Ⅰ型超敏反应迟发相以嗜酸性粒细胞浸润为主，白三烯C4、D4、E4及PGD2、PAF等新合成脂类介质引起支气管持续痉挛和黏膜水肿，其中白三烯作用最强。"},{"q":"对体液免疫二次应答Ab产生，叙述错误的是","o":["再次接受较少量相同Ag刺激即可诱发","潜伏期大约为初次应答时的一半","主要为IgG，亲和力高且较均一","达平台期快，平台高且时间长","下降期短或无"],"a":4,"e":"再次应答潜伏期短、抗体浓度上升快、平台高且维持久、所需抗原量小、以高亲和力IgG为主；其下降期缓慢而长，并非短或无。"},{"q":"淋巴样干细胞可以分化为","o":["T细胞","红细胞","血小板","巨噬细胞","嗜碱性粒细胞"],"a":0,"e":"造血干细胞先分化为髓样和淋巴样干细胞，后者经胸腺发育为T细胞，并可分化为B细胞和NK细胞；红细胞、血小板和粒细胞源于髓样干细胞。"},{"q":"不成熟B细胞的mIg表达模式是","o":["IgM","IgA","IgG","IgM、IgD","IgE"],"a":0,"e":"未成熟B细胞仅表达mIgM，受抗原刺激可致阴性选择或受体编辑；成熟B细胞同时表达mIgM和mIgD。"},{"q":"与多发性硬化症相关联的HLA分子是","o":["HLA-B27","HLA-DR2","HLA-DR3","HLA-DR4","HLA-DR5"],"a":1,"e":"多发性硬化症与HLA-DR2呈强关联，相对危险度约4.8；强直性脊柱炎与HLA-B27、类风湿关节炎与HLA-DR4关联。"},{"q":"能与亲和素特异性结合的是","o":["抗原","补体","过氧化物酶","生物素","抗体"],"a":3,"e":"亲和素与生物素呈极高亲和力的非共价结合，一分子亲和素可结合四个生物素，故生物素-亲和素系统常用于免疫检测的信号放大。"},{"q":"下列细胞因子中，能诱导Th0细胞向Th2细胞分化的有","o":["IL-2","IL-4","IL-12","TNF-α","IFN-γ"],"a":1,"e":"IL-4诱导Th0向Th2分化并上调转录因子GATA3；IL-12与IFN-γ诱导向Th1分化，TGF-β与IL-6、IL-23诱导向Th17分化。"},{"q":"有关重症联合免疫缺陷病的治疗中，下列哪项不正确","o":["骨髓移植术是较理想的治疗手段之一","输血时应使用新鲜血","禁忌接种活疫苗或活菌苗","有细菌感染时，应选用强效抗生素","可给予丙种球蛋白以提高体液免疫力"],"a":1,"e":"SCID患者T细胞缺陷，输新鲜血中的活淋巴细胞可引发致死性移植物抗宿主病，须输经照射处理或冻存的血制品。"},{"q":"关于肿瘤免疫的描述，错误的是","o":["实验证实在某些肿瘤细胞表面存在肿瘤特异性抗原","血清癌胚抗原升高见于多种肿瘤","人乳头瘤病毒与人宫颈癌发生有关","血清甲胎蛋白抗体水平升高可以辅助诊断原发性肝癌","抗EB病毒抗体阳性可以辅助诊断鼻咽癌"],"a":0,"e":"官方答案为【实验证实在某些肿瘤细胞表面存在肿瘤特异性抗原】，但依据教材，正确答案为【血清甲胎蛋白抗体水平升高可以辅助诊断原发性肝癌】。TSA确实存在，而临床检测的是血清甲胎蛋白抗原水平，非抗体。"},{"q":"下列哪一项是AIDS的典型免疫异常改变","o":["补体活性降低","迟发性皮肤超敏反应减弱或缺乏","血清IgG、IgA升高","CD4＋/CD8＋T细胞比值下降","体液免疫功能正常"],"a":3,"e":"HIV主要感染CD4+T细胞，使其数目持续下降而CD8+T细胞相对不变，CD4/CD8比值降低甚至倒置，是AIDS最具特征性的免疫学改变。"},{"q":"免疫标记技术的示踪物质不包括","o":["荧光素","免疫毒素","酶","化学发光物质","放射性同位素"],"a":1,"e":"免疫标记技术的示踪物有酶、荧光素、放射性核素、化学发光物质和胶体金；免疫毒素由抗体与毒素偶联而成，属导向治疗制剂。"},{"q":"亲代与子代间必然有一个HLA单倍型相同是因为","o":["单倍型遗传方式","高度多态性现象","连锁不平衡","性连锁遗传","等位基因同源染色体之间的交换"],"a":0,"e":"HLA基因群紧密连锁，同源染色体间交换率仅约1%，以单倍型整体遗传，子代必从父母各得一条，故与亲代至少一条单倍型相同。"},{"q":"以下属于原发性B细胞缺陷病的是","o":["DiGeorge综合征","慢性肉芽肿病","X连锁无丙种球蛋白血症","阵发性夜间血红蛋白尿","遗传性血管神经性水肿"],"a":2,"e":"X连锁无丙种球蛋白血症由X染色体上BTK基因突变引起，B细胞发育成熟障碍、血清Ig极低，属原发性B细胞缺陷；DiGeorge综合征为T细胞缺陷。"},{"q":"机体免疫监视功能低下时易发生","o":["免疫耐受","自身免疫病","移植排斥反应","超敏反应","肿瘤"],"a":4,"e":"免疫监视指识别并清除体内突变细胞，功能低下时突变细胞逃避监视而克隆扩增，易发生肿瘤；免疫自稳紊乱则导致自身免疫病。"},{"q":"不能用于分离外周血T细胞的方法是","o":["密度梯度离心法","FACS","免疫磁珠法","免疫吸附分离法","抗原肽-MHC分子四聚体技术分析"],"a":0,"e":"Ficoll密度梯度离心只能按密度分离出外周血单个核细胞，其中含T、B细胞和单核细胞，不能单独获得T细胞，故不用于分离纯化T细胞。"},{"q":"补体激活的三条途径的共同末端通路是补体的","o":["合成阶段","识别阶段","活化阶段","膜攻击阶段","降解阶段"],"a":3,"e":"三条途径前端反应各异，但均形成C5转化酶裂解C5，随后C5b与C6～C9组装攻膜复合物，即三条途径共有的膜攻击阶段。"},{"q":"关于造血干细胞移植，正确的是","o":["造血干细胞主要来源于骨髓和脾","对HLA配型的要求没有器官移植高","移植排斥反应弱于器官移植","不适用于治疗先天性免疫缺陷病","移植成功后可形成移植耐受"],"a":4,"e":"造血干细胞移植成功后可形成供受者免疫细胞共存的嵌合状态，对供者抗原产生特异性耐受；其HLA配型要求高，GVHD是影响疗效的首要因素。"},{"q":"关于调节性T细胞的叙述，哪项是不正确的","o":["过继转移调节性T细胞可用于打破免疫耐受","自然产生的调节性T细胞来源于胸腺","调节性T细胞在外周耐受形成的过程中发挥作用","自然产生的调节性T细胞可通过细胞-细胞间的直接接触发挥免疫抑制作用","调节性T细胞也可通过诱导产生"],"a":0,"e":"调节性T细胞抑制免疫应答、维持外周耐受，过继转移Treg用于治疗自身免疫病和防治移植排斥，打破耐受则需清除或抑制Treg。"},{"q":"用免疫球蛋白免疫同一种属不同个体的动物诱导的抗体，其所针对的特异性抗原主要是","o":["同种型抗原","同种异型抗原","异种抗原","移植抗原","独特型抗原"],"a":1,"e":"同一种属不同个体Ig恒定区存在遗传性差异，即同种异型抗原（Gm、Km因子），用它免疫异体可诱导针对该表位的抗体。"},{"q":"Graves病患者血清中存在的自身抗体是","o":["抗TSHR抗体","抗TSH抗体","抗内因子抗体","抗胰岛素受体抗体","抗乙酰胆碱受体抗体"],"a":0,"e":"Graves病患者产生抗TSHR抗体，模拟TSH持续刺激甲状腺上皮细胞分泌过量甲状腺素，属特殊类型Ⅱ型超敏反应；抗AChR抗体见于重症肌无力。"},{"q":"Th1细胞对Tc细胞（CTL）的辅助作用是","o":["分泌细胞因子，促进CTL的增殖、分化","协助传递第一信号","促进CTL表面MHCⅡ类分子的表达","促进CTL表面MHCⅠ类分子的表达","促进CTL释放穿孔素"],"a":0,"e":"Th1细胞分泌IL-2和IFN-γ，IL-2促进CD8+CTL活化、增殖并分化为效应细胞，IFN-γ上调靶细胞MHCⅠ类分子表达，从而辅助CTL发挥杀伤作用。"},{"q":"补体促进吞噬细胞的吞噬作用，被称为补体的","o":["炎症介质作用","调理作用","清除免疫复合物","溶菌和细胞毒作用","中和作用"],"a":1,"e":"补体C3b与抗体Fc段可分别与吞噬细胞表面CR1和FcγR结合，促进吞噬细胞黏附并吞噬被调理的颗粒，称为调理作用。"},{"q":"存在于不同种属之间的共同抗原称为","o":["异种抗原","隐蔽抗原","同种异型抗原","异嗜性抗原","独特型抗原"],"a":3,"e":"异嗜性抗原又称Forssman抗原，是存在于人、动物和微生物等不同种属间的共同抗原，如链球菌成分与人心肌、肾小球基底膜的共同抗原。"},{"q":"下列哪一种物质与Ⅰ型超敏反应无关","o":["组胺","备解素","激肽","白三烯","前列腺素"],"a":1,"e":"组胺、激肽、白三烯和前列腺素均为肥大细胞等释放的生物活性介质；备解素是旁路途径的补体调节蛋白，与Ⅰ型超敏反应无关。"},{"q":"参与Ⅰ型超敏反应的细胞是","o":["巨噬细胞","NK细胞","T细胞","肥大细胞","树突状细胞"],"a":3,"e":"肥大细胞表面高表达FcεRⅠ，其膜IgE与变应原交联后脱颗粒，释放组胺、白三烯、PAF等生物活性介质引起速发相反应，是Ⅰ型超敏反应的主要效应细胞。"},{"q":"B细胞识别特异性抗原","o":["需要细胞因子","具有MHCⅠ类分子限制性","通过CD3传递抗原信号","具有MHCⅡ类分子限制性","没有MHC限制性"],"a":4,"e":"BCR可直接结合天然抗原表位，无需APC加工提呈，也不受MHC限制；TCR识别pMHC才具有MHC限制性。"},{"q":"脾脏和淋巴结生发中心主要由（ ）聚积形成","o":["T淋巴细胞","B淋巴细胞","粒细胞","巨噬细胞","NK细胞"],"a":1,"e":"生发中心由抗原特异性B细胞在Tfh细胞辅助下增殖形成，内含滤泡DC网络，是B细胞体细胞高频突变、亲和力成熟和抗体类别转换的场所。"},{"q":"人类MHC炎症相关基因不包括","o":["肿瘤坏死因子基因家族","转录调节基因或类转录因子基因家族","热休克蛋白基因家族","C型凝集素受体基因家族","MHCⅠ类链相关分子（MIC）基因家族"],"a":3,"e":"HLAⅢ类基因区的炎症相关基因包括TNF、LTA、LTB、MIC基因家族和HSP70基因家族；C型凝集素受体基因不位于该区，其产物是NK细胞受体。"},{"q":"下列关于PD-1的表述，不确切的是","o":["PD-1是表达于T、B细胞和髓系细胞的抑制性受体","PD-1基因缺陷小鼠更容易发生自身免疫性疾病","PD-1胞浆段含有ITIM基序，招募磷酸酶，抑制TCR信号","PD-1作用和Fas相似，诱导T细胞激活后的凋亡（AICD）","PD-L1在APCs、内皮细胞，甚至肿瘤细胞表面都有表达"],"a":3,"e":"PD-1胞质段含ITIM，招募SHP-2磷酸酶削弱TCR信号，属抑制性受体；诱导活化T细胞凋亡的是Fas/FasL介导的AICD。"},{"q":"最早发现的人类肿瘤特异性抗原是","o":["CEA","T抗原","MAGE-蛋白","EIA抗原","EBV蛋白"],"a":2,"e":"Boon等用黑色素瘤特异性CTL筛选cDNA文库，鉴定出MAGE、BAGE等抗原，MAGE是最早发现的人类肿瘤特异性抗原；CEA属胚胎抗原。"},{"q":"黏附分子的正确概念是","o":["细胞在正常分化、成熟和活化过程中，出现或消失的表面标记","介导细胞之间或细胞与基质之间相互接触和结合的一类分子","由活化的细胞分泌的调节多种细胞生理功能的小分子多肽","体液中正常存在的具有酶活性和自我调节作用的一组大分子系统","广泛存在于血清、组织液和细胞膜表面，具有精密调控机制的蛋白质反应系统"],"a":1,"e":"黏附分子是介导细胞间或细胞与细胞外基质间相互接触和结合的一类膜分子，以受体-配体形式发挥作用，参与免疫细胞附着与迁移。"},{"q":"可诱导初始T细胞活化的免疫细胞是","o":["树突状细胞","B1细胞","巨噬细胞","肥大细胞","上皮细胞"],"a":0,"e":"树突状细胞是体内功能最强的专职性抗原提呈细胞，高表达MHCⅡ类分子及B7等共刺激分子，能有效刺激初始T细胞活化增殖。"},{"q":"关于再次应答，下列说法错误的是","o":["主要产生高亲和力的IgG抗体","抗体浓度增加快","抗体维持时间短","诱发再次应答所需抗原剂量小","再次应答较初次应答的潜伏期短"],"a":2,"e":"再次应答潜伏期短、抗体浓度上升快、维持时间长、所需抗原剂量小，并以高亲和力IgG类抗体为主。"},{"q":"未成熟B淋巴细胞表达的膜免疫球蛋白是","o":["mIgA","mIgM","mIgE","mIgD","mIgG"],"a":1,"e":"未成熟B细胞仅表达mIgM，受抗原刺激可致阴性选择或受体编辑；进入外周表达mIgD后成为成熟（初始）B细胞。"},{"q":"NK细胞在抗肿瘤作用中的特点不包括","o":["需预先致敏才能杀伤肿瘤细胞","无肿瘤特异性","无MHC限制性","需双信号刺激才能活化","机体抗肿瘤的第一道防线"],"a":0,"e":"NK细胞无需预先致敏，无肿瘤特异性和MHC限制性，通过活化与抑制性受体信号失衡直接杀伤肿瘤，是抗肿瘤的第一道防线。"},{"q":"不识别由MHC分子递呈的蛋白质抗原，只识别由CD1分子递呈的脂类或糖脂类抗原的细胞是","o":["Th细胞","CTL细胞","NKT细胞","NK细胞","APC细胞"],"a":2,"e":"NKT细胞为CD1d限制性T细胞，TCR识别CD1d提呈的糖脂和磷脂抗原，不识别MHC提呈的蛋白抗原，活化后快速分泌IL-4和IFN-γ。"},{"q":"以下说法正确的是","o":["CD40L是位于B细胞表面的第二信号分子，是CD40的配体","CD40是位于B细胞表面的第二信号分子，是CD40L的受体","CD40L是位于B细胞表面的第二信号分子，是CD34的配体","CD40是位于B细胞表面的第二信号分子，是CD34的受体","CD40和CD40L都是位于B细胞表面的第二信号分子，两者的作用恰恰相反"],"a":1,"e":"CD40组成性表达于B细胞表面，是B细胞活化的关键共刺激分子，其配体CD40L表达于活化的Tfh细胞，两者结合提供B细胞活化的第二信号。"},{"q":"HLAⅡ类分子的抗原肽结合部位（即抗原肽结合槽）是","o":["α1和α2","α3","α1和β1","α2和β2","β2m"],"a":2,"e":"HLAⅡ类分子的α、β链各有两个胞外结构域，α1与β1共同构成两端开放的抗原肽结合槽，可容纳13～17个氨基酸的抗原肽；α2与β2为Ig样区。"},{"q":"下列哪个不是成熟T细胞和B细胞定居的场所","o":["扁桃体","胸腺","脾","肠淋巴结","腹股沟淋巴结"],"a":1,"e":"胸腺是T细胞发育成熟的中枢免疫器官；扁桃体、脾、淋巴结及肠相关淋巴组织均为外周免疫器官，是成熟T、B细胞定居和产生应答的场所。"},{"q":"半抗原的特性是","o":["同时具有免疫原性和免疫反应性","具有免疫反应性而不具有免疫原性","含有多个抗原表位","具有免疫原性而不具有免疫反应性","不具有免疫反应性和免疫原性"],"a":1,"e":"半抗原仅有免疫反应性而无免疫原性，与蛋白质载体偶联后获得免疫原性；完全抗原则两种特性兼备。"},{"q":"下述属于抗体的负反馈调节的是","o":["ICs-C3d复合物","免疫记忆","ITAM","提高抗原呈递效率","与BCR竞争结合抗原"],"a":4,"e":"血中抗体增多后与抗原表位竞争性结合，阻断抗原与BCR结合，从而抑制B细胞继续产生抗体；FcγRⅡB与BCR交联亦传递抑制信号。"},{"q":"双抗体夹心ELISA检测人血清IL-2水平，所用的酶标记特异性抗体是","o":["酶标记的包被抗体","酶标记羊抗人IL-2抗体","酶标记羊抗鼠IL-2抗体","酶标记羊抗鼠Ig抗体","酶标记羊抗人Ig抗体"],"a":1,"e":"双抗体夹心法以固相包被抗体捕获IL-2，再用酶标记的抗人IL-2抗体识别结合于固相的IL-2，加底物显色定量，故酶标二抗须针对人IL-2。"},{"q":"一种细胞因子可增强另一种细胞因子的功能，这种作用的特点称为细胞因子的","o":["多效性","重叠性","协同性","拮抗性","网络性"],"a":2,"e":"协同性指两种细胞因子共同作用时效应大于各自单独作用之和，如IL-2与IFN-γ协同增强杀伤活性；一种细胞因子抑制另一种的功能则称拮抗性。"},{"q":"祖B细胞发育阶段的特点有","o":["表达κ或者λ链","表达Igα/Igβ","出现轻链基因VJ重排","表达IgD","表达IgM"],"a":1,"e":"祖B细胞阶段已表达Igα/Igβ，与μ链组成前BCR样复合物转导信号；κ、λ轻链VJ重排始于前B细胞，IgM、IgD表达见于未成熟及成熟B细胞。"},{"q":"需要做溶血空斑试验的情况是","o":["研究药物对B细胞功能的影响","检测红细胞完整性","研究单核细胞吞噬功能","测定自身免疫性溶血患者血清抗体滴度","检测肿瘤患者的NK细胞活性"],"a":0,"e":"溶血空斑试验以SRBC免疫动物，计数脾脏中分泌抗体的浆细胞形成的空斑，反映B细胞产生抗体的功能，故用于评价药物对B细胞的影响。"},{"q":"哪种来源的肿瘤在不同个体或不同组织中表达相同的抗原","o":["所有的肿瘤","病毒诱发的肿瘤","化学致癌物诱发的肿瘤","放射线辐射诱发的肿瘤","后天免疫缺陷导致的肿瘤"],"a":1,"e":"同一种病毒诱发的肿瘤无论组织来源或宿主种类如何，均表达相同的病毒肿瘤抗原且免疫原性较强；理化因素诱发的肿瘤抗原则呈高度个体特异性。"},{"q":"采用皮试方法检测细胞免疫功能时常用的抗原是","o":["青霉素","脂多糖","结核菌素","PHA","PWM"],"a":2,"e":"皮内注射PPD后72小时观察局部硬结，属Ⅳ型超敏反应，可反映体内致敏T细胞的存在与功能，故用于检测细胞免疫功能并辅助诊断结核感染。"},{"q":"关于T细胞的共刺激分子，错误的是","o":["以受体和配体的形式结合","为T细胞的进一步活化提供共刺激信号","加强APC和T细胞间的直接接触","具有抗原特异性","激活的专职APC高表达"],"a":3,"e":"共刺激分子以受体-配体方式结合，为T细胞活化提供第二信号并加强APC与T细胞接触，其表达无抗原特异性，活化的专职APC高表达。"},{"q":"琼脂扩散试验属于","o":["间接血凝试验","补体结合试验","沉淀反应","免疫荧光试验","ELISA"],"a":2,"e":"琼脂扩散为可溶性抗原与相应抗体在凝胶中相对扩散，于比例合适处形成肉眼可见沉淀线，属凝胶内沉淀反应。"},{"q":"以下抗原免疫原性较弱的是","o":["乙肝病毒表面抗原","多聚赖氨酸","抗原抗体复合物","鸡卵清白蛋白","金黄色葡萄球菌外毒素"],"a":1,"e":"多聚赖氨酸为单一氨基酸的直链聚合物，结构简单、表位单一，免疫原性弱；分子量大且结构复杂的蛋白质抗原则免疫原性强。"},{"q":"用牛痘预防天花的学者是","o":["Pasteur","Jenner","Koch","Landsteiner","Ehrlich"],"a":1,"e":"英国医生Jenner观察到挤奶女工接触牛痘后不感染天花，遂以牛痘接种预防天花获得成功，提出vaccination概念，开创了人工主动免疫的先河。"},{"q":"除B细胞和T细胞外，与抗体产生有关的细胞还有","o":["FDC细胞","嗜酸性粒细胞","嗜碱性粒细胞","肥大细胞","NK细胞"],"a":0,"e":"FDC借CR1、CR2和Fc受体捕获并浓缩抗原-抗体复合物，供生发中心B细胞识别，参与亲和力成熟和抗体产生。"},{"q":"关于中枢耐受，叙述正确的是","o":["中枢耐受的形成机制与外周耐受的形成机制相同","中枢耐受是指已经发育成熟的T、B细胞，遇内源性或外源性抗原形成的免疫耐受","中枢耐受是指在胚胎期及出生后T、B细胞发育的过程中，遇自身抗原所形成的耐受","中枢耐受的形成主要是由非自身抗原诱导产生的","中枢耐受主要是通过免疫忽视和克隆无能或失活机制使免疫系统对抗原呈现无反应状态"],"a":2,"e":"中枢耐受指T、B细胞在胸腺和骨髓发育过程中接触自身抗原后形成的耐受，机制为克隆清除和受体编辑；外周耐受由免疫忽视、克隆失能等机制形成。"},{"q":"关于T细胞，下列说法错误的是","o":["Th1细胞和Th2细胞均是CD4＋ T细胞","Th2细胞介导细胞免疫","Th1细胞分泌IL-2","Th2细胞分泌IL-4","Th1细胞和Th2细胞均是辅助性T细胞，只是辅助对象不同"],"a":1,"e":"Th2细胞分泌IL-4、IL-5、IL-10、IL-13，主要辅助B细胞产生抗体、参与抗寄生虫和过敏反应；介导细胞免疫、活化巨噬细胞的是Th1细胞。"},{"q":"系统性红斑狼疮（SLE）致病机制属于","o":["Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅲ型超敏反应","Ⅳ型超敏反应","免疫缺陷病"],"a":2,"e":"SLE患者产生大量抗核抗体，与可溶性自身抗原形成中等大小循环免疫复合物，沉积于肾小球和皮肤血管壁并激活补体，属Ⅲ型超敏反应。"},{"q":"浆细胞的主要聚居场所是","o":["骨髓","胸腺","脾","淋巴结","黏膜相关淋巴组织"],"a":0,"e":"骨髓是抗体产生细胞即浆细胞的主要居留地，长寿命浆细胞在骨髓中存活数年并持续分泌抗体，再次应答的抗体主要在骨髓产生。"},{"q":"在下列黏附分子对中，可为T细胞活化提供最重要的协同刺激信号的是","o":["CD28与B7","CTLA-4与B7","CD2与LFA-3","CD40与CD40L","ICOS与ICOSL"],"a":0,"e":"CD28与APC表面B7（CD80/CD86）结合提供T细胞活化最重要的第二信号，促进IL-2转录；CTLA-4与同一配体结合则传递抑制信号。"},{"q":"根据HLA单体型遗传特征，同胞兄弟姐妹之间有一个单体型相同的几率为","o":["10%","25%","50%","75%","100%"],"a":2,"e":"同胞间HLA单倍型组合有全相合、半相合和全不合三种，概率分别为25%、50%和25%，故有一条单倍型相同者占50%。"},{"q":"机体免疫防御反应异常增高，可引发","o":["肿瘤","超敏反应","严重感染","免疫缺陷病","自身免疫病"],"a":1,"e":"免疫防御应答过强或持续时间过长，可致组织损伤和功能异常，即发生超敏反应；应答过低或缺如则发生免疫缺陷病和感染。"},{"q":"以下不属于Ⅰ型超敏反应性疾病的是","o":["荨麻疹","支气管哮喘","血清过敏性休克","过敏性鼻炎","链球菌感染后的肾小球肾炎"],"a":4,"e":"链球菌感染后肾小球肾炎由Ⅱ、Ⅲ型超敏反应介导，以Ⅲ型为主；荨麻疹、哮喘、过敏性鼻炎和血清过敏性休克均属IgE介导的Ⅰ型。"},{"q":"以下关于淋巴细胞再循环的路径正确的是","o":["中枢免疫器官→外周血→外周免疫器官或组织","中枢免疫器官→外周血→中枢免疫器官","外周免疫器官或组织→外周血→外周免疫器官或组织","外周免疫器官或组织→外周血→中枢免疫器官","外周免疫器官或组织→外周血→中枢免疫器官→外周血→外周免疫器官或组织"],"a":2,"e":"定居于外周免疫器官的淋巴细胞经淋巴管入血，再穿出高内皮微静脉归巢至外周淋巴器官或组织，如此反复循环，不进入中枢免疫器官。"},{"q":"下列关于HLAⅡ类分子的说法正确的是","o":["由α链和β2m链组成","提呈外源性抗原","分布在所有有核细胞的表面","由HLA-A、B、C等基因编码","可与CD8分子结合"],"a":1,"e":"HLAⅡ类分子由α链和β链组成异源二聚体，表达于专职APC及活化T细胞表面，其抗原结合槽由α1和β1构成，提呈外源性抗原肽供CD4+T细胞识别。"},{"q":"SCID的主要表现是","o":["细胞免疫缺陷","体液免疫缺陷","吞噬细胞缺陷","补体缺陷","体液和细胞免疫均缺陷"],"a":4,"e":"重症联合免疫缺陷病由T细胞与B细胞发育或功能同时障碍所致，表现为体液免疫和细胞免疫均缺陷，患儿反复发生严重感染。"},{"q":"以下哪种抗原物质的免疫原性相对较强","o":["抗原来源与人类的亲缘关系较近","抗原的分子量小于10kD","抗原的结构复杂","脂类抗原","由单一的氨基酸组成的抗原"],"a":2,"e":"抗原分子量越大、结构越复杂、含表位越多，免疫原性越强；脂类抗原、单一氨基酸组成的多聚物及与人类亲缘关系近的蛋白免疫原性均弱。"},{"q":"抗CD3单克隆抗体一般用于治疗和预防","o":["非霍奇金淋巴瘤","急性移植排斥反应","急性髓样细胞白血病","持续性哮喘","获得性免疫缺陷综合征"],"a":1,"e":"抗CD3单抗与T细胞CD3结合，经调理吞噬和补体依赖细胞毒清除T细胞，用于治疗和预防急性移植排斥反应。"},{"q":"下列过程中，体现MHC限制性的是","o":["巨噬细胞吞噬细菌","ADCC作用","B细胞识别外来抗原","Tc细胞杀伤靶细胞","NK细胞杀伤肿瘤细胞"],"a":3,"e":"CD8+CTL的TCR识别靶细胞表面抗原肽-MHCⅠ类分子复合物，杀伤受自身MHC限制；NK杀伤、ADCC和巨噬细胞吞噬均无MHC限制性。"},{"q":"下列关于IgE的说法哪项是错误的","o":["在五类Ig中血清含量最低","有CH4区","可介导Ⅰ型超敏反应","有亲细胞性","在种系发育过程中最早产生"],"a":4,"e":"个体发育中最早合成的是IgM；IgE在五类Ig中血清含量最低、含CH4区，为亲细胞抗体并介导Ⅰ型超敏反应。"},{"q":"下列哪种细胞不是由造血干细胞分化而来的","o":["红细胞","中性粒细胞","胸腺细胞","树突状细胞","成纤维细胞"],"a":4,"e":"成纤维细胞源于间充质细胞，不属造血干细胞分化产物；红细胞、中性粒细胞、胸腺细胞和树突状细胞均源自骨髓造血干细胞。"},{"q":"导致机体对肿瘤细胞产生免疫耐受的因素不包括","o":["肿瘤抗原大部分属于自身抗原","肿瘤细胞MHC分子表达下调或丢失","抗原提呈细胞表面的B7、CD40分子表达下调","肿瘤细胞具有异质性","肿瘤细胞产生抑制性的细胞因子"],"a":3,"e":"肿瘤抗原多为自身抗原、MHC和共刺激分子表达下调、分泌抑制性细胞因子均可诱导耐受；异质性造成抗原调变和亚克隆逃逸，非耐受的诱导因素。"},{"q":"与风湿性心脏病发病机制关系密切的是","o":["抗HLA抗体","免疫复合物沉积","同心肌反应的NK细胞","抗与心脏有交叉反应的A族溶血性链球菌抗原的抗体","高水平的类风湿因子"],"a":3,"e":"A族溶血性链球菌表面成分与人心肌存在共同抗原，抗链球菌抗体及致敏T细胞经交叉反应攻击心肌和心瓣膜，引起风湿性心脏瓣膜病。"},{"q":"可清除突变细胞，防止肿瘤发生的免疫功能是","o":["免疫防御功能","免疫监视功能","免疫稳定功能","抗感染作用","吞噬功能"],"a":1,"e":"免疫监视指免疫系统识别并清除基因突变产生的肿瘤细胞，功能低下易致肿瘤；免疫防御针对病原体，免疫自稳清除衰老损伤细胞。"},{"q":"对人类来说，来源于下列哪种动物的抗原的免疫原性相对较强","o":["金丝猴","熊猫","鹤","娃娃鱼","金龙鱼"],"a":4,"e":"亲缘关系越远，抗原结构差异越大，免疫原性越强；金龙鱼属鱼类，与人类亲缘关系最远，故其抗原对人体的免疫原性最强。"},{"q":"胞内段带有ITAM的分子是","o":["CTLA-4","PD-1","CD3","BCR","CD94/NKG2C"],"a":2,"e":"CD3由γ、δ、ε、ζ、η链组成，各链胞质区均含ITAM，负责将TCR识别pMHC的信号转入胞内；CTLA-4与PD-1胞内段为ITIM。"},{"q":"存在于树突状细胞表面，与HIV免疫逃逸有关的受体是","o":["Fc受体","DC-SING受体","CXCR","CCR","CX3CR"],"a":1,"e":"DC表面的DC-SIGN以高亲和力结合HIV gp120，内吞病毒颗粒并储存于胞内使其免于失活，随后传递给CD4+T细胞，参与免疫逃逸。"},{"q":"关于白三烯的描述错误的是","o":["可使平滑肌收缩","可使毛细血管收缩","可使毛细血管通透性增加","可使外分泌腺分泌增加","在迟发相发挥主要作用"],"a":1,"e":"白三烯可使支气管平滑肌强烈持久收缩、毛细血管扩张、通透性增加和黏膜腺体分泌增多；使毛细血管收缩的是肾上腺素等，故该描述有误。"},{"q":"关于肿瘤免疫的叙述错误的是","o":["细胞免疫是抗肿瘤免疫的主要机制","抗体在抗肿瘤中并不发挥主要作用","静止和活化的巨噬细胞均能杀瘤细胞","NK细胞是抗肿瘤的第一道防线","增强抗体具有促进肿瘤生长的作用"],"a":2,"e":"只有活化的巨噬细胞才具较强杀瘤活性，可经非特异吞噬、ADCC及分泌TNF、NO杀伤肿瘤；静止巨噬细胞杀瘤作用很弱，其主要作用是提呈肿瘤抗原。"},{"q":"关于Th1和Th2细胞所分泌的细胞因子，下列哪种说法是错误的","o":["Th1细胞分泌的细胞因子包括IFN-γ和TNF-α","Th2细胞分泌的细胞因子包括IL-4、IL-10","Th1细胞分泌的细胞因子可引起巨噬细胞和NK细胞活化","Th2细胞分泌的细胞因子可活化CD8＋T细胞","Th1细胞分泌的细胞因子能抑制Th2细胞的活性"],"a":3,"e":"Th2细胞分泌IL-4、IL-5、IL-10、IL-13，辅助B细胞产生抗体并拮抗Th1；活化CD8+T细胞主要依赖Th1细胞分泌的IL-2和IFN-γ。"},{"q":"用于肿瘤靶向治疗的免疫毒素是指","o":["抗肿瘤的单克隆抗体（单抗）","抗肿瘤单抗与放射性核素的交联物","抗肿瘤单抗与抗癌化疗剂的交联物","抗肿瘤单抗与毒素的交联物","抗肿瘤单抗与酶的交联物"],"a":3,"e":"免疫毒素是抗肿瘤单抗与蓖麻毒素、白喉毒素等毒性蛋白交联的偶联物，借抗体特异性将毒素导向肿瘤细胞实现靶向杀伤；与核素或化疗药交联者另称放射免疫偶联物和抗体药物偶联物。"},{"q":"不表达HLAⅠ类抗原的细胞是","o":["淋巴细胞","成熟红细胞","血小板","网织红细胞","肝细胞"],"a":1,"e":"HLAⅠ类分子表达于所有有核细胞表面，成熟红细胞已失去细胞核，故不表达HLAⅠ类抗原；淋巴细胞、血小板和肝细胞均可表达。"},{"q":"下列选项中可改变自身组织和细胞的免疫原性的有","o":["外伤、异体组织移植","外伤、感染、电离辐射、药物","外伤、肿瘤、免疫接种","肿瘤、免疫接种、药物","外伤手术、免疫接种、药物"],"a":1,"e":"生物、物理如冷热与电离辐射、化学如药物以及外伤感染等因素，可使自身组织蛋白结构改变、修饰或释放，从而获得免疫原性。"},{"q":"对NK细胞抗肿瘤效应的叙述，错误的是","o":["无特异性","无需抗原致敏，即可直接杀瘤","可依赖抗体通过ADCC方式杀瘤","依赖补体，通过CDC方式杀瘤","无MHC限制性"],"a":3,"e":"NK细胞杀伤肿瘤无特异性、无MHC限制性、无需预先致敏，可经FcγRⅢ（CD16）介导ADCC；依赖补体的CDC属抗体功能。"},{"q":"关于抗毒素的使用，错误的是","o":["可能发生过敏反应","治疗时要早期足量","可作为免疫增强剂给儿童多次注射","对过敏机体应采取脱敏疗法","可用于紧急预防或治疗"],"a":2,"e":"抗毒素为异种蛋白，反复注射易诱发超敏反应，不能作为免疫增强剂使用；应用时须早期足量，皮试阳性者行脱敏注射。"},{"q":"诱导T细胞耐受较为有效的方法是","o":["肌内注射大剂量TI抗原","皮下注射大剂量TI抗原","皮下注射大剂量TD抗原","静脉注射大剂量TI抗原","静脉注射大剂量TD抗原"],"a":4,"e":"TD抗原依赖Th细胞，大剂量静脉注射时抗原经脾脏APC提呈而缺乏共刺激信号，易诱导T细胞耐受；皮下注射易致敏，TI抗原不能诱导T细胞耐受。"},{"q":"未成熟DC的特点是","o":["高表达共刺激分子","高表达MHC分子","有效提呈抗原","有效摄取抗原","高表达肽-MHC分子复合物"],"a":3,"e":"未成熟DC高表达模式识别受体，能有效识别和摄取外源性抗原，但MHCⅡ类分子和共刺激分子表达低，提呈能力弱。"},{"q":"关于补体经典激活途径，描述错误的是","o":["抗原抗体复合物是其主要激活物","分为识别和活化两个阶段","C4是C1的底物，C4b很不稳定","C1q分子有6个结合部位，必须与IC结合后才能激活后续的补体成分","激活顺序为C123456789"],"a":4,"e":"经典途径活化顺序为C1、C4、C2、C3、C5～C9，C4先于C2被裂解；C1q须与IgG或IgM的Fc段结合后才能激活C1r、C1s。"},{"q":"能刺激CTL分化增殖和活化的细胞因子是","o":["Th1分泌的细胞因子","Th2分泌的细胞因子","Th3分泌的细胞因子","Th17分泌的细胞因子","Treg分泌的细胞因子"],"a":0,"e":"Th1细胞分泌IFN-γ、IL-2等，促进CTL活化、增殖并增强其杀伤活性；Th2细胞分泌IL-4、IL-5，主要辅助体液免疫。"},{"q":"为预防感染性疾病进行预防接种，目前使用减毒活疫苗比使用灭活疫苗普遍，下述原因中不正确的是","o":["接种活疫苗能使机体产生特异性体液免疫和细胞免疫，而灭活疫苗很难诱导细胞免疫","减毒活疫苗刺激机体产生特异性保护，其持续时间一般较灭活疫苗长","减毒疫苗株能在机体内增殖并抑制或干扰野毒株增殖和致病性，而灭活疫苗不能","减毒活疫苗可应用于免疫缺陷或低下的患者，因为它可诱导机体产生分泌型抗体","减毒活疫苗株虽有返祖为野毒株的可能性，但其概率极低"],"a":3,"e":"减毒活疫苗可在体内增殖，免疫缺陷者和孕妇接种有发生严重感染的危险，故不能用于免疫低下者；其免疫持久，可诱导细胞和黏膜免疫。"},{"q":"下列细胞因子具有趋化作用的是","o":["IL-1、IL-8、IL-3","IFN、MCP-1","IL-8、MCP-1","TNF、IL-4","IL-1、IL-6"],"a":2,"e":"CXCL8（IL-8）趋化中性粒细胞，CCL2（MCP-1）趋化单核细胞，二者均属趋化因子；IL-1和TNF为促炎因子，无趋化活性。"},{"q":"遗传性血管神经性水肿是由哪类补体缺陷引起","o":["C3缺陷","C4缺陷","C9缺陷","C1q缺陷","C1INH缺陷"],"a":4,"e":"C1INH是C1r、C1s的抑制物，其缺陷使C1持续活化、裂解C4与C2，生成血管活性片段使血管通透性增高，引起遗传性血管神经性水肿。"},{"q":"用于治疗和紧急预防细菌外毒素所致疾病的是","o":["抗毒素血清","丙种球蛋白","免疫毒素","抗淋巴细胞丙种球蛋白","细胞因子"],"a":0,"e":"抗毒素血清含中和外毒素的抗体，可中和游离外毒素，用于破伤风、白喉等外毒素所致疾病的治疗和紧急预防，属人工被动免疫。"},{"q":"HPV疫苗可预防","o":["宫颈癌","乳腺癌","黑色素瘤","成人T细胞白血病","前列腺癌"],"a":0,"e":"HPV疫苗诱导针对人乳头瘤病毒的中和抗体，阻断HPV感染，可预防宫颈癌及HPV相关的口腔癌，属预防性肿瘤疫苗。"},{"q":"补体激活过程中产生的哪一种产物可固定于细菌或其他颗粒性物质的表面","o":["C2a","C3a","C3b","C4a","C5b"],"a":2,"e":"C3b以及C4b、iC3b可共价结合于细菌等颗粒表面，作为调理素与吞噬细胞补体受体结合促进吞噬；C3a、C4a、C5a为游离炎症介质。"},{"q":"用于检测淋巴细胞HLA抗原的血清学方法是","o":["补体结合试验","双向扩散试验","补体依赖的细胞毒试验","混合淋巴细胞反应","放射免疫检测"],"a":2,"e":"以补体依赖的细胞毒试验检测HLA抗原，即微量淋巴细胞毒试验：待检淋巴细胞加HLA抗血清与补体，阳性者细胞膜被破坏而着色，据此判定HLA型别。"},{"q":"NK细胞杀伤瘤细胞的机制不包括","o":["吞噬肿瘤细胞","ADCC","表达FasL","释放穿孔素","释放TNF"],"a":0,"e":"NK细胞杀伤肿瘤不依赖吞噬，而通过释放穿孔素/颗粒酶、表达FasL及TNF途径诱导靶细胞凋亡，并可经ADCC杀伤抗体包被的肿瘤细胞。"},{"q":"与HIV播散有关的主要免疫细胞为","o":["T淋巴细胞","B淋巴细胞","巨噬细胞","NK细胞","中性粒细胞"],"a":2,"e":"HIV可感染单核/巨噬细胞，并随其迁移播散至脑、肺、淋巴结等组织，巨噬细胞是病毒储存库和体内播散的重要载体。"},{"q":"T细胞表面的协同信号分子受体是","o":["CD4分子","CD8分子","CD28分子","CD40分子","ICAM-1"],"a":2,"e":"CD28是T细胞最重要的共刺激受体，与APC表面B7结合传递第二信号；CD40则是APC（如B细胞）表面的共刺激分子。"},{"q":"介导B细胞活化的共刺激分子是","o":["CD3","CD19","CD21","CD40","CD81"],"a":3,"e":"B细胞组成性表达CD40，与活化Tfh细胞的CD40L结合，提供B细胞活化最重要的共刺激信号；CD19、CD21、CD81为共受体成分。"},{"q":"3～6个月婴儿易患呼吸道感染，主要是因为哪类Ig不足","o":["IgM","IgG","IgE","sIgA","IgD"],"a":3,"e":"3～6个月婴儿从母体获得的IgG逐渐减少，自身SIgA合成尚不足，黏膜局部防御薄弱，故易患呼吸道感染。"},{"q":"以下对于补体介导的细胞毒作用的生物学意义描述错误的是","o":["参与抗细菌","参与抗病毒（如流感病毒）","参与抗寄生虫","引起机体自身细胞溶解，导致组织损伤","引起癌变"],"a":4,"e":"补体介导的细胞毒作用参与抗细菌、抗病毒和抗寄生虫防御，也可在Ⅱ型超敏反应中溶解自身细胞造成组织损伤，但不引起细胞癌变。"},{"q":"CD20属于","o":["致癌病毒产物","基因突变产物","正常组织中的隐蔽抗原","胚胎抗原","分化抗原"],"a":4,"e":"CD20是B细胞谱系在其分化成熟不同阶段表达的表面标志，属分化抗原，可作为B细胞淋巴瘤诊断和靶向治疗的靶点。"},{"q":"下列哪种分子属于人类组织相容性抗原（即移植抗原）","o":["CD分子","细胞因子","黏附分子","HLA分子","Ig分子"],"a":3,"e":"人类主要组织相容性抗原即HLA分子，因高度多态性成为最重要的同种异型抗原，是引起同种异体移植排斥反应的主要移植抗原。"},{"q":"青霉素可以引起的超敏反应是","o":["Ⅰ、Ⅱ型超敏反应","Ⅰ、Ⅱ、Ⅲ型超敏反应","Ⅱ、Ⅳ型超敏反应","Ⅰ、Ⅱ、Ⅲ、Ⅳ型超敏反应","Ⅰ、Ⅱ、Ⅳ型超敏反应"],"a":3,"e":"青霉素降解产物作为半抗原可诱发Ⅰ型休克，也可经Ⅱ型（溶血性贫血）、Ⅲ型（血清病）和Ⅳ型（接触性皮炎）机制致病，四型均可发生。"},{"q":"Ig的类别转换主要发生在哪个过程中","o":["从IgG转换为IgM、IgA等","从IgM转换为IgG、IgA等","从IgD转换为IgM、IgA等","从IgE转换为IgG、IgA等","从IgA转换为IgM、IgG等"],"a":1,"e":"类别转换时重链V区不变，Cμ基因改接Cγ、Cα或Cε，故由应答中首先分泌的IgM转为IgG、IgA或IgE。"},{"q":"关于GVHR的描述，正确的是","o":["发生和受者与供者间HLA型别不符相关","病理特点为大量巨噬细胞和淋巴细胞浸润","常见于胸腺、脾脏移植","受者体内预存抗体引起","宿主T细胞被供者组织相容性抗原激活"],"a":0,"e":"GVHR是移植物中供者T细胞被受者组织相容性抗原激活后增殖，攻击宿主组织器官，故其发生取决于供受者间HLA型别是否相符，HLA不合是主要诱因。"},{"q":"CD8分子是哪种细胞的标志","o":["B细胞","辅助性T细胞","细胞毒性T细胞","活化的巨噬细胞","中性粒细胞"],"a":2,"e":"CD8是细胞毒性T细胞的标志分子，作为共受体与MHCⅠ类分子结合，辅助TCR识别内源性抗原肽并参与信号转导；CD4则是Th细胞的标志。"},{"q":"介导NK细胞ADCC作用的受体","o":["FcγRⅠ（CD64）","FcγRⅡ（CD32）","FcγRⅢ（CD16）","FcεR（CD23）","FcαR（CD89）"],"a":2,"e":"NK细胞表达FcγRⅢA（CD16），与IgG包被靶细胞的Fc段结合后释放穿孔素、颗粒酶杀伤靶细胞；CD64、CD32主要分布于单核巨噬细胞。"},{"q":"单阳性胸腺细胞是指","o":["CD3＋CD4-CD8-细胞","CD3＋CD4＋CD8-细胞或CD3＋CD4-CD8＋细胞","CD2＋CD4-CD8-细胞","CD3-CD4＋CD8-细胞","CD3-CD4-CD8＋细胞"],"a":1,"e":"单阳性胸腺细胞为经阳性选择后只表达CD4或CD8的成熟细胞，即CD4+CD8-或CD4-CD8+，并表达CD3。"},{"q":"区别B1和B2细胞的重要表面标志","o":["CD3","CD5","CD40","CD79","CD86"],"a":1,"e":"B1细胞表达CD5与mIgM，B2细胞不表达CD5而表达mIgM和mIgD，故CD5是区分两者的重要表面标志；CD19、CD20、CD79为B细胞通用标志。"},{"q":"下列抗原因素与自身免疫病诱发机制无关的是","o":["表位扩展","自身抗原的改变","隐蔽抗原的释放","分子模拟","抗原基因突变"],"a":4,"e":"自身免疫病可由隐蔽抗原释放、自身抗原改变、分子模拟和表位扩展等抗原相关因素诱发；抗原基因突变是肿瘤新生抗原产生的机制，与自身免疫病无关。"},{"q":"类风湿因子属于哪一类免疫球蛋白","o":["IgA","IgD","IgE","IgG","IgM"],"a":4,"e":"类风湿因子是针对变性IgG Fc段的自身抗体，以IgM类为主，少数为IgG、IgA，可形成免疫复合物沉积于关节滑膜和肾小球。"},{"q":"对人类而言，HLA抗原属于","o":["异种抗原","改变的自身抗原","同种异型抗原","隐蔽抗原","异嗜性抗原"],"a":2,"e":"HLA是同一物种不同个体间存在的不同抗原，属同种异型抗原，为人体多态性最高的同种异型抗原，也是介导同种移植排斥的主要移植抗原。"},{"q":"BCR识别的对象是","o":["抗原肽-MHCⅠ类分子复合物","抗原肽-MHCⅡ类分子复合物","TD抗原","被APC加工处理过的抗原肽","被DC提呈的抗原"],"a":2,"e":"BCR直接识别未经加工提呈的完整天然抗原，无MHC限制性，无需APC处理；TD抗原为蛋白质，具完整天然构象，故为其识别对象。"},{"q":"促使Th0细胞向Th1细胞方向分化的细胞因子是","o":["IL-3","IL-4","IL-13","IL-10","IFN-γ"],"a":4,"e":"IL-12和IFN-γ诱导Th0向Th1细胞分化，Th1关键转录因子为T-bet；IL-4诱导向Th2分化，TGF-β与IL-6诱导向Th17分化。"},{"q":"初次应答中产生的抗体主要是","o":["IgA","IgD","IgE","IgG","IgM"],"a":4,"e":"初次应答潜伏期长，最先产生IgM，随后产生的IgG亲和力低、维持时间短；再次应答才以高亲和力IgG为主。"},{"q":"引起变态反应性甲状腺炎（桥本甲状腺炎）的抗原属","o":["异种抗原","同种异型抗原","异嗜性抗原","自身抗原","独特型抗原"],"a":3,"e":"桥本甲状腺炎由抗甲状腺球蛋白、抗甲状腺过氧化物酶自身抗体及自身反应性T细胞攻击甲状腺滤泡上皮所致，抗原属自身抗原。"},{"q":"一位患者患多种细菌感染，并发现补体C3成分完全缺乏，不会影响的功能是","o":["细菌的裂解作用","过敏毒素的产生","细菌的调理作用","中性粒细胞趋化因子的产生","中性粒细胞的吞噬作用"],"a":4,"e":"C3缺乏使C3转化酶和C5转化酶组装障碍，溶菌、过敏毒素产生、调理吞噬和C5a趋化作用均受损；中性粒细胞本身的吞噬功能不依赖补体。"},{"q":"E-选择素最初表达于","o":["血管内皮细胞","巨噬细胞","单核细胞","中性粒细胞","血小板"],"a":0,"e":"E-选择素静息时不表达，在IL-1、TNF-α等刺激下由血管内皮细胞合成并表达于膜表面，介导白细胞沿内皮滚动，是炎症早期黏附的关键分子。"},{"q":"BCR和下列哪项受体交联后产生抑制信号","o":["CD40","CR2","FcγRⅡb","FcεRI","FcμR"],"a":2,"e":"FcγRⅡB（CD32b）胞质段含ITIM，与BCR交联后招募磷酸酶，负反馈抑制B细胞活化及抗体分泌。"},{"q":"下列哪种细胞因子可促进巨噬细胞杀灭其胞内寄生的结核杆菌","o":["IL-1","IL-4","SCF","IFN-γ","G-CSF"],"a":3,"e":"IFN-γ与巨噬细胞表面受体结合，经JAK-STAT1通路激活巨噬细胞，增强呼吸爆发和吞噬体融合，从而提高其杀灭胞内结核分枝杆菌的能力。"},{"q":"对B细胞内化抗原描述错误的是","o":["内化的抗原可经MHCⅡ类分子途径提呈","只有产生了第一信号，B细胞才能内化抗原","内化的抗原可经MHCⅠ类分子途径提呈","B细胞活化的第一信号是抗原与BCR结合后产生","抗原信息提呈给抗原特异性Th细胞"],"a":2,"e":"B细胞以BCR摄取抗原后经MHCⅡ类分子途径提呈给CD4+Th细胞，不经MHCⅠ类分子途径提呈；其活化的第一信号由BCR结合抗原产生。"},{"q":"T细胞活化所需的第二信号主要是","o":["CD8与MHCⅠ类分子作用","CD4与MHCⅡ类分子作用","CD40与CD40L之间作用","CD28与B7分子之间的作用","CD152与B7分子之间的作用"],"a":3,"e":"T细胞活化的第二信号由T细胞CD28与APC表面B7（CD80/CD86）结合产生，可促进IL-2基因转录；CD152与B7结合则传递抑制信号。"},{"q":"向初始T细胞提供第二活化信号的重要共刺激分子是","o":["CD28/B7","CTLA-4/B7","CD4/MHCⅡ类分子","CD8/MHCⅠ类分子","ICOS/ICOSL"],"a":0,"e":"初始T细胞活化时，CD28与APC表面B7结合提供最重要的第二信号；CTLA-4传递抑制信号，ICOS作用于活化后的T细胞。"},{"q":"关于TSA的正确叙述是","o":["只存在于某种肿瘤细胞表面而不存在于正常细胞的新抗原","特异性高，大部分是超抗原","诱发宿主免疫反应无MHC限制性","在胚胎发育时期曾经出现过","一般是9个氨基酸的短肽"],"a":0,"e":"肿瘤特异性抗原仅表达于某种或某几种肿瘤细胞而不存在于正常细胞，如理化因素诱发的肿瘤新抗原，是肿瘤免疫治疗的理想靶点。"},{"q":"关于Ig的叙述哪项是错误的","o":["IgM是分子量最大的免疫球蛋白","血清中含量最多的是IgG，含量最少的是IgA","在肠道内起保护作用的Ig主要是sIgA","机体的抗感染作用在体液中主要是IgG","唯一能通过胎盘的Ig是IgG，初生婴儿从母乳中获得的Ig是sIgA"],"a":1,"e":"血清中含量最高的是IgG，最少的是IgE，仅占Ig总量的0.002%；IgA占10%～15%，并非最少。"},{"q":"广泛应用于治疗病毒感染性疾病的细胞因子是","o":["IL-1","IL-2","TNF-α","IFN-α","TGF-β"],"a":3,"e":"IFN-α属Ⅰ型干扰素，由病毒感染细胞和pDC产生，能诱导细胞建立抗病毒状态，临床广泛用于乙型、丙型肝炎及带状疱疹等病毒感染性疾病。"},{"q":"对抗原致免疫耐受描述错误的是","o":["抗原剂量过高或过低都可导致免疫耐受","单体抗原较其聚体容易导致免疫耐受","特殊的抗原表位及抗原表位的变异均可导致免疫耐受","不易被Mϕ处理提呈的抗原易致免疫耐受","皮下注射抗原易致免疫耐受"],"a":4,"e":"皮下或皮内注射最难诱导耐受，口服和静脉注射最易；抗原剂量过低或过高、单体抗原及不易被巨噬细胞处理提呈者均易致耐受。"},{"q":"下列关于DC的分类方法，目前最为认可的是","o":["经典DC和调节DC","经典DC和胸腺DC","经典DC和浆细胞样DC","经典DC和间质DC","经典DC和滤泡DC"],"a":2,"e":"目前最认可的分类是按来源将DC分为骨髓髓样前体来源的经典DC和淋巴样前体来源的浆细胞样DC，另有单核细胞来源DC。"},{"q":"关于特异性变应原脱敏疗法描述错误的是","o":["少量多次","短间隔","反复皮下注射","诱导产生特异性IgG","诱导特异性Treg细胞产生"],"a":1,"e":"特异性变应原脱敏采用剂量由小到大、浓度由低到高、长间隔反复皮下注射或舌下含服，诱导特异性IgG和Treg以恢复耐受；小剂量短间隔多次注射是异种免疫血清脱敏的方法。"},{"q":"关于同种反应性T细胞的直接识别机制，不正确的是","o":["不同于经典抗原识别","过客白细胞发挥重要作用","受者T细胞直接识别自身APC表面抗原肽-MHC分子复合物","受者T细胞直接识别供者APC表面抗原肽-MHC分子复合物","主要在急性排斥反应的早期起作用"],"a":2,"e":"直接识别指受者T细胞直接识别供者APC表面的抗原肽-同种异型MHC分子复合物，无需自身APC加工提呈，过客白细胞作用关键，主要参与急性排斥早期。"},{"q":"人体内抗病毒、中和毒素、抗真菌最重要的抗体类别是","o":["IgA","IgM","IgG","IgE","IgD"],"a":2,"e":"IgG体内分布广、半衰期长、亲和力高，具中和毒素与病毒、调理吞噬、ADCC及激活补体等作用，是抗感染主力；SIgA主司黏膜局部免疫，IgM出现最早。"},{"q":"脱敏治疗可用于","o":["输血反应","肾小球肾炎","血清病","接触性皮炎","血清过敏症"],"a":4,"e":"异种免疫血清脱敏用于抗毒素皮试阳性又必须使用者，小剂量短间隔20～30分钟多次注射使致敏靶细胞分批脱敏，可防止再次注射抗毒素引起血清过敏性休克。"},{"q":"巨噬细胞产生的内热原是","o":["IL-1","IL-12","补体","TNF-β","FcR"],"a":1,"e":"官方答案为【IL-12】，但依据教材，正确答案为【IL-1】。内源性致热原主要为IL-1、TNF-α和IL-6，由巨噬细胞等产生并作用于下丘脑体温调节中枢；IL-12主要促进Th1细胞分化。"},{"q":"接受病毒刺激后可产生大量Ⅰ型干扰素的免疫细胞是","o":["髓样树突状细胞","浆细胞样树突状细胞","滤泡树突状细胞","B淋巴细胞","巨噬细胞"],"a":1,"e":"浆细胞样树突状细胞受病毒核酸刺激后活化，可快速产生大量Ⅰ型干扰素，参与抗病毒固有免疫；髓样DC主要执行抗原提呈。"},{"q":"能刺激嗜酸性粒细胞分化为杀伤蠕虫的效应细胞的是","o":["IL-5","IL-7","IL-11","EPO","GM-CSF"],"a":0,"e":"IL-5由Th2细胞分泌，强力促进嗜酸性粒细胞的增殖、分化和活化，使其成为杀伤蠕虫的效应细胞，是抗蠕虫免疫的关键细胞因子。"},{"q":"合成分泌抗体的最主要细胞是","o":["嗜酸性粒细胞","T细胞","B细胞","浆细胞","肥大细胞"],"a":3,"e":"浆细胞是B细胞分化的终末细胞，胞质富含粗面内质网，专司合成分泌抗体；B细胞须活化后才能大量分泌抗体。"},{"q":"HLAⅠ类分子的轻链又称","o":["a1","β2m","β1","α2","α3"],"a":1,"e":"HLAⅠ类分子由α链即重链与β2微球蛋白即轻链非共价结合而成，β2m由第15号染色体基因编码，不具多态性。"},{"q":"传递B细胞活化的第二信号分子是","o":["CD21","CD28","CD40","CD40L","CD81"],"a":2,"e":"Tfh细胞表达的CD40L与B细胞组成性表达的CD40结合，向B细胞传递活化第二信号，促其增殖和类别转换；CD28与B7结合提供的是T细胞活化的第二信号。"},{"q":"以下关于免疫应答的说法错误的是","o":["是指免疫系统识别和清除抗原物质的整个过程","包括固有免疫和适应性免疫","免疫应答总是对机体有利","固有免疫是适应性免疫的先决条件","适应性免疫可促进固有免疫应答的发生"],"a":2,"e":"免疫应答在清除抗原的同时可造成组织损伤，如超敏反应、自身免疫病和移植排斥，故并非总是对机体有利；固有免疫为适应性应答提供先决条件。"},{"q":"可通过内分泌形式作用于远处靶细胞的细胞因子是","o":["TNF-α","IL-2","IL-3","IL-4","IL-5"],"a":0,"e":"多数细胞因子以自分泌或旁分泌方式局部作用，TNF-α可进入血液循环，以内分泌方式作用于远处的靶细胞。"},{"q":"能直接杀伤肿瘤细胞或病毒感染细胞的细胞因子是","o":["IFN-γ和IL-4","TGF-β和LT","IL-4和IL-6","CSF和IFN-β","TNF-α和LT"],"a":4,"e":"TNF-α与LT（TNF-β）可直接杀伤肿瘤细胞并诱导其凋亡；IFN-γ主要活化巨噬细胞、增强抗原提呈，IL-4促进Th2分化。"},{"q":"借助抗原识别受体捕获抗原的细胞是","o":["巨噬细胞","树突状细胞","并指细胞","朗格汉斯细胞","B细胞"],"a":4,"e":"B细胞表面BCR即膜IgM，可直接结合并浓集抗原，经内吞加工后提呈给Th细胞，是借助抗原识别受体捕获抗原的细胞；巨噬细胞和DC靠PRR或吞噬摄取抗原。"},{"q":"新生儿不易患传染病，其免疫力的获得主要是通过","o":["人工自动免疫","人工被动免疫","自然被动免疫","隐性感染","潜伏感染"],"a":2,"e":"母体IgG经胎盘、初乳中SIgA经哺乳转移给胎儿和新生儿，属自然被动免疫，可在短期内保护新生儿免受相应传染病侵袭。"},{"q":"参与T细胞抗原识别的CD分子有","o":["CD3、CD4、CD8","CD3、CD4、CD28","CD2、CD8、CD28","CD2、CD4、CD28","CD2、CD4、CD152"],"a":0,"e":"CD3含ITAM，负责转导TCR识别pMHC产生的第一信号，CD4、CD8作为共受体分别结合MHCⅡ、Ⅰ类分子并辅助信号转导，三者均参与抗原识别。"},{"q":"能促进T细胞生长的细胞因子是","o":["IL-1","IL-2","IFN-γ","TNF-α","TNF-β"],"a":1,"e":"IL-2与T细胞表面IL-2受体结合，是T细胞存活、增殖和分化的必需信号，属T细胞自分泌生长因子。"},{"q":"吞噬细胞主要包括","o":["NK细胞和单核-巨噬细胞","单核-巨噬细胞和中性粒细胞","中性粒细胞和树突状细胞","NK细胞和中性粒细胞","中性粒细胞和APC"],"a":1,"e":"吞噬细胞主要包括单核-巨噬细胞和中性粒细胞，二者经PRR识别、吞噬病原体，并通过氧依赖和氧非依赖杀菌系统将其杀伤清除。"},{"q":"对HLA基因复合体描述错误的是","o":["位于第6号染色体短臂","每个Ⅱ类基因亚区又有2个或2个以上功能基因座位","经典的Ⅰ类基因包括A、B、C 3个座位","经典的Ⅱ类基因由DP、DQ、DR 3个亚区组成","专门编码人类白细胞抗原"],"a":4,"e":"HLA复合体含128个功能基因座，除编码HLAⅠ、Ⅱ类分子外，还编码补体成分、TNF、TAP等免疫功能相关分子，并非只编码白细胞抗原。"},{"q":"关于自身抗体的正确说法是","o":["检出自身抗体即可诊断患有自身免疫病","检出自身反应性T细胞即可诊断患自身免疫病","自身抗体有助于清除衰老变性的自身细胞","健康个体没有自身抗体产生","自身抗体都能导致组织损伤"],"a":2,"e":"天然自身抗体参与清除衰老、变性的自身细胞及代谢产物，维持自身稳定；检出自身抗体或自身反应性T细胞并不等于患有自身免疫病。"},{"q":"B1细胞通过表面BCR可直接识别","o":["感染细胞表面的热休克蛋白","自身组织细胞表面的MHCⅠ类分子","C反应蛋白","细菌脂多糖","细菌表面的岩藻糖"],"a":3,"e":"B1细胞BCR多样性有限，直接识别细菌脂多糖、荚膜多糖和葡聚糖等多糖类TI抗原，无需Th辅助即迅速产生IgM。"},{"q":"与艾滋病发病密切相关的主要受体是","o":["CD3","CD4","CD8","CD28","CD40"],"a":1,"e":"HIV包膜糖蛋白gp120与CD4高亲和力结合，继而与CXCR4或CCR5结合使病毒侵入CD4+T细胞、单核巨噬细胞和DC，导致CD4+T细胞进行性减少。"},{"q":"B1细胞接受多糖类抗原刺激后可产生","o":["以IgM为主的高亲和性抗体","以IgG为主的高亲和性抗体","以IgM为主的低亲和性抗体","以IgG为主的低亲和性抗体","IgM和IgG两种不同类型的抗体"],"a":2,"e":"B1细胞受细菌多糖刺激后48小时内即产生以IgM为主的低亲和力抗体，增殖分化过程中一般不发生抗体类别转换。"},{"q":"在补体激活的经典途径中，没有被裂解的组分是","o":["C2","C3","C4","C5","C6"],"a":4,"e":"经典途径中C1、C4、C2、C3、C5依次被裂解，C6不被裂解，仅与C5b、C7、C8结合并聚合C9，形成膜攻击复合物完成溶细胞作用。"},{"q":"与宫颈癌发病有关的病原是","o":["EBV","HTLV-1","HIV","HCV","HPV"],"a":4,"e":"高危型HPV如16、18型的E6、E7蛋白分别降解p53和Rb，使宫颈上皮细胞增殖失控并恶变，故HPV感染与宫颈癌发生密切相关。"},{"q":"关于T细胞介导的抗肿瘤免疫，错误的是","o":["受MHC限制","CD8＋T细胞是主要效应细胞","抗原致敏的T细胞才能杀伤肿瘤细胞","Th细胞不参与抗肿瘤免疫反应","在肿瘤免疫应答中起重要作用"],"a":3,"e":"CD4+Th细胞通过分泌细胞因子并辅助CD8+CTL活化，间接参与抗肿瘤免疫；CTL是主要效应细胞，杀伤受MHCⅠ类分子限制。"},{"q":"单纯疱疹病毒感染的树突状细胞对该病毒抗原最可能的加工提呈途径是","o":["经蛋白酶体降解为多肽，由MHCⅠ类分子提呈给CD8＋T细胞","经溶酶体降解为多肽，由MHCⅠ类分子提呈给CD8＋T细胞","经蛋白酶体降解为多肽，由MHCⅡ类分子提呈给CD4＋T细胞","经吞噬溶酶体降解为多肽，由MHCⅡ类分子提呈给CD4＋T细胞","经溶酶体降解为多肽，由MHCⅡ类分子提呈给CD4＋T细胞"],"a":0,"e":"病毒在DC内复制，其蛋白属内源性抗原，经泛素化后由蛋白酶体降解为肽，经TAP转运至内质网与MHCⅠ类分子结合，提呈给CD8+T细胞。"},{"q":"在体外培养中，选择性刺激人类T细胞增殖的物质","o":["PWM","SPA","LDH","LPS","PHA"],"a":4,"e":"PHA是T细胞丝裂原，与细胞表面受体结合可非特异性诱导人静息T细胞活化和增殖；LPS主要刺激小鼠B细胞，SPA为葡萄球菌蛋白A。"},{"q":"T细胞通过哪个分子促进B细胞增殖、分化和抗体产生","o":["CD2","CD40L","CD152","PD-1","ICOS"],"a":1,"e":"活化T（Tfh）细胞表达CD40L，与B细胞CD40结合提供第二信号，并分泌IL-4、IL-21促进B细胞增殖、类别转换和分化为浆细胞。"},{"q":"抗IL-6R单抗（Tocilizumab）、IL-1R拮抗剂可用于治疗","o":["类风湿关节炎","重症联合免疫缺陷病","失血后贫血","哮喘","晚期肺癌"],"a":0,"e":"IL-6和IL-1参与滑膜炎症与关节破坏，抗IL-6R单抗和IL-1R拮抗剂阻断其受体信号，可用于治疗类风湿关节炎。"},{"q":"三条补体激活途径都必须具备的成分是","o":["C1s和C1r","C4和C2","B因子和D因子","C3及C5～C9","D因子和P因子"],"a":3,"e":"三条途径前端激活方式不同，但都形成C3转化酶裂解C3，并组装C5b～C9膜攻击复合物，故C3和C5～C9为共同成分。"},{"q":"B1细胞不具备的抗体应答特点是","o":["产生以IgM为主的低亲和力抗体","可发生Ig类别转换","无免疫记忆","在机体早期抗感染免疫发挥作用","识别病原体的某些多糖抗原被激活"],"a":1,"e":"B1细胞受多糖抗原刺激后48小时内产生以IgM为主的低亲和力抗体，一般不发生类别转换，也无免疫记忆，主要在早期抗感染中发挥作用。"},{"q":"对细胞免疫应答起负调节作用的细胞因子是","o":["IL-1","IL-2","IL-6","IL-12","TGF-β"],"a":4,"e":"TGF-β抑制T细胞增殖、分化和细胞因子产生，并促进Treg分化，对细胞免疫起负调节；IL-2、IL-12则增强细胞免疫应答。"},{"q":"以下属于巨噬细胞表面的调理性受体的是","o":["Toll样受体","干扰素受体","甘露糖受体","补体C3受体","巨噬细胞炎性蛋白-1α/β受体"],"a":3,"e":"调理性受体包括IgGFc受体和补体C3b/C4b受体即CR1，识别病原体-抗体或病原体-C3b复合物，促进吞噬；甘露糖受体属模式识别受体，不介导调理。"},{"q":"胸腺细胞阴性选择的结果是","o":["T细胞获得对抗原识别的MHC限制性","T细胞对自身抗原形成中枢免疫耐受","T细胞分化为单阳性未成熟T细胞","T细胞分化为记忆T细胞","T细胞对外源性抗原形成外周免疫耐受"],"a":1,"e":"胸腺阴性选择清除与自身抗原肽-MHC高亲和力结合的T细胞克隆，使T细胞对自身抗原形成中枢免疫耐受；获得MHC限制性是阳性选择的结果。"},{"q":"用人IgG免疫动物，理论上不可能诱导产生的抗体是","o":["抗κ链抗体","抗λ链抗体","抗γ链抗体","抗独特型抗体","抗α链抗体"],"a":4,"e":"人IgG重链为γ链，轻链为κ或λ链，故可诱导抗γ链、抗κ链、抗λ链及抗独特型抗体；α链是IgA的重链，IgG分子中不存在，不能诱导相应抗体。"},{"q":"同时参与补体三种激活途径的成分是","o":["C1","C4和C2","C3","B因子","抗体"],"a":2,"e":"C3是三条补体激活途径的共同组分，血浆浓度最高，经各自的C3转化酶裂解为C3a和C3b后进入共同末端通路；C1、C4、C2、B因子仅参与特定途径。"},{"q":"最不易引起免疫耐受的情况是","o":["新生期注射可溶性抗原","成年期注射可溶性抗原","新生期注射颗粒性抗原","成年期注射颗粒性抗原","成年期注射佐剂与颗粒性抗原"],"a":3,"e":"颗粒性抗原免疫原性强，成年个体免疫系统成熟，最难诱导耐受；新生期注射及可溶性抗原均较易诱导耐受。"},{"q":"氯苯那敏抗过敏的作用原理是","o":["稳定肥大细胞","松弛平滑肌","促IgE合成转变为IgG合成","灭活组胺","拮抗组胺"],"a":4,"e":"氯苯那敏与组胺竞争效应细胞膜上的组胺受体，阻断组胺引起的血管扩张和平滑肌收缩，属拮抗生物活性介质的作用。"},{"q":"关于过继免疫的叙述错误的是","o":["输入物质为抗原","免疫力出现快","维持时间不定","多用于治疗","输入物质为免疫活性细胞"],"a":0,"e":"过继免疫是输入体外活化扩增的免疫活性细胞如LAK、TIL、CTL或抗体等效应物质，使受者迅速获得免疫力，输入物不是抗原；其免疫力出现快，维持时间不定，多用于治疗。"},{"q":"下列哪种抗原，不是颗粒性抗原","o":["金黄色葡萄球菌","伤寒杆菌","红细胞","抗原包被的乳胶微粒","细菌外毒素"],"a":4,"e":"颗粒性抗原包括细菌、红细胞、乳胶微粒等颗粒状物质；细菌外毒素是细菌分泌的可溶性蛋白，属可溶性抗原，与颗粒性抗原相对。"},{"q":"肺炎支原体感染后产生抗红细胞抗体是因为","o":["免疫功能缺陷","遗传因素决定","自身抗原发生改变","交叉抗原的存在","隐蔽抗原的释放"],"a":2,"e":"肺炎支原体感染可改变人红细胞膜蛋白的免疫原性，使自身抗原变成“异己”而被识别，刺激产生抗红细胞抗体，引起溶血性贫血。"},{"q":"补体激活旁路途径中形成C3转化酶需要下列哪种补体固有成分","o":["C1","C2","C3","C4","C5"],"a":2,"e":"旁路途径中C3b与B因子结合后被D因子裂解，形成C3bBb即C3转化酶，故必须有C3参与；C1、C2、C4为经典途径成分。"},{"q":"在机体针对肿瘤抗原的免疫记忆功能中，发挥重要作用的免疫细胞是","o":["NK细胞","中性粒细胞","巨噬细胞","γδT细胞","CD4＋T细胞"],"a":4,"e":"CD4+T细胞可分化为记忆细胞，再次接触肿瘤抗原时迅速扩增并辅助CTL，是抗肿瘤免疫记忆的重要细胞；NK细胞和中性粒细胞无免疫记忆。"},{"q":"最易引起免疫耐受的抗原是","o":["颗粒性抗原","可溶性抗原","大分子聚合状态抗原","细菌","马血清白蛋白加佐剂"],"a":1,"e":"可溶性、小分子、结构单一的抗原易诱导免疫耐受；颗粒性、大分子、结构复杂的抗原及加佐剂者更易诱导免疫应答。"},{"q":"可用于转移性乳腺癌治疗的单克隆抗体是","o":["抗CD20","抗CD33","抗CD52","抗Her2/CD340","抗EGFR"],"a":3,"e":"曲妥珠单抗为抗Her-2人源化单克隆抗体，用于Her-2过表达的转移性乳腺癌；抗CD20用于淋巴瘤，抗EGFR用于结直肠癌。"},{"q":"参与旁路途径激活补体的物质是","o":["IgG","IgM","IgD","LPS","MBL"],"a":3,"e":"LPS为革兰阴性菌细胞壁成分，提供接触表面使C3b沉积，经B因子和D因子形成C3bBb而激活旁路途径；MBL启动凝集素途径。"},{"q":"B细胞抗原识别受体是","o":["TCR","CD3","FcR","CR2","mIg"],"a":4,"e":"B细胞抗原识别受体即膜型免疫球蛋白，成熟B细胞同时表达mIgM和mIgD，可直接识别天然构象表位；TCR和CD3为T细胞标志。"},{"q":"下列哪组趋化因子受体是HIV在巨噬细胞和T淋巴细胞上的辅助受体","o":["CCR2、CXCR4","CCR1、CXCR2","CCR5、CXCR4","CCR5、CX3CR1","XCR1、CCR5"],"a":2,"e":"HIV的gp120与CD4结合后需再结合辅助受体，CXCR4介导T细胞嗜性株感染，CCR5介导巨噬细胞嗜性株感染。"},{"q":"可以用于亲子鉴定的方法是","o":["声音识别","指纹检测","HLA型别检测","Ig血清型检测","面部识别"],"a":2,"e":"HLA具有高度多态性并呈单倍型遗传，子代两条单倍型分别来自父母，故检测HLA型别可判断亲子关系，也用于骨髓移植供者选择。"},{"q":"细胞间相互作用不受MHC限制的是","o":["树突状细胞与Th细胞","Th细胞与B细胞","NK细胞与靶细胞","CTL细胞与靶细胞","巨噬细胞与Th细胞"],"a":2,"e":"NK细胞经杀伤活化受体和抑制受体直接识别靶细胞表面配体，不受MHC限制；DC与Th、Th与B、巨噬细胞与Th、CTL与靶细胞的作用均受MHC限制。"},{"q":"以下哪项不是IgFcR的功能","o":["介导吞噬调理","介导免疫球蛋白通过胎盘","参与B细胞抗原识别","介导ADCC作用","介导肥大细胞脱颗粒"],"a":2,"e":"FcγR介导调理吞噬、ADCC，FcRn转运IgG通过胎盘，FcεRⅠ介导肥大细胞脱颗粒；B细胞识别抗原由BCR及CD79a/CD79b完成，与Fc受体无关。"},{"q":"不能通过诱导免疫耐受治疗的是","o":["花粉过敏症","肝癌","系统性红斑狼疮","同种异体皮肤移植","类风湿关节炎"],"a":1,"e":"诱导免疫耐受用于治疗超敏反应、自身免疫病及防治移植排斥；肝癌需增强抗肿瘤免疫应答，而非诱导耐受。"},{"q":"下列淋巴细胞中，不属于固有免疫细胞的是","o":["γδT细胞","αβT细胞","NKT细胞","NK细胞","B1细胞"],"a":1,"e":"αβT细胞经胸腺发育、具MHC限制性，是适应性免疫的主要细胞；γδT细胞、NKT细胞、NK细胞和B1细胞均参与固有免疫应答。"},{"q":"CSF可以归类于","o":["集落刺激因子","白细胞介素","干扰素","肿瘤坏死因子家族","趋化因子家族"],"a":0,"e":"CSF即集落刺激因子，包括GM-CSF、M-CSF、G-CSF、EPO、SCF和TPO，刺激造血干细胞或祖细胞增殖分化为相应谱系血细胞。"},{"q":"NKT细胞表面TCR识别的配体分子是","o":["HLAⅠ类分子","CD1分子递呈的糖脂和磷脂成分","MHCⅠ/抗原肽复合物","MHCⅡ/抗原肽复合物","糖蛋白"],"a":1,"e":"NKT细胞即CD1d限制性T细胞，其TCR识别CD1d分子提呈的糖脂和磷脂类抗原，不受MHC限制，活化后迅速分泌IL-4、IFN-γ并发挥细胞毒作用。"},{"q":"TI抗原单独可以诱导","o":["抗体亲和力成熟","Ig类别转换","记忆B细胞形成","B1细胞的免疫应答","B2细胞的免疫应答"],"a":3,"e":"TI抗原无需Th细胞辅助即可直接激活B细胞，主要激活B1细胞和边缘区B细胞，仅产生IgM，无类别转换、亲和力成熟和免疫记忆。"},{"q":"耐受原表位是指","o":["能诱导免疫耐受的Ag所具有的表位","能诱导B细胞活化的表位","能诱导Ts细胞活化的Ag表位","能诱导Mφ活化的表位","能诱导Th细胞活化的Ag表位"],"a":2,"e":"耐受原表位指能诱导Ts细胞活化、进而抑制免疫应答的抗原表位，与能诱导Th细胞活化的免疫原表位相对应。"},{"q":"下列哪种属于免疫抑制剂","o":["左旋咪唑","转移因子","卡介苗","西咪替丁","硫唑嘌呤"],"a":4,"e":"硫唑嘌呤为嘌呤类似物，抑制DNA复制和淋巴细胞增殖，属免疫抑制剂；左旋咪唑、转移因子和卡介苗均为免疫增强剂。"},{"q":"介导Ⅰ型超敏反应的抗体主要是","o":["IgA","IgD","IgE","IgG","IgM"],"a":2,"e":"IgE为亲细胞抗体，其Fc段与肥大细胞、嗜碱性粒细胞表面高亲和力FcεRⅠ结合使机体致敏，再次接触变应原时交联受体触发脱颗粒。"},{"q":"有关癌胚抗原，正确的是","o":["只存在于某种肿瘤细胞表面","对宿主无免疫原性","在所有的肿瘤中均可检查到","结合在细胞表面不易脱落","可以用作肿瘤的特异性诊断标志"],"a":1,"e":"CEA为胚胎期合成、出生后极微量的自身抗原，在结肠癌等腺癌中升高，因属自身成分对宿主无免疫原性，只能作辅助诊断而非特异性标志。"},{"q":"能刺激T细胞前体细胞的生长与分化的细胞因子是","o":["IL-4","IL-7","IL-11","EPO","GM-CSF"],"a":1,"e":"IL-7由骨髓基质细胞产生，作用于表达IL-7R的淋巴系祖细胞，促进T细胞前体细胞的生长、分化与存活，IL-7R缺陷可致T-B+重症联合免疫缺陷。"},{"q":"下列哪项不属于黏膜相关淋巴组织","o":["派尔集合淋巴结","阑尾","上皮细胞下散在的淋巴组织","扁桃体","肠系膜淋巴结"],"a":4,"e":"肠系膜淋巴结是引流肠道的固有淋巴结，属外周免疫器官；派尔集合淋巴结、阑尾、扁桃体及上皮下散在淋巴组织均位于黏膜，属黏膜相关淋巴组织。"},{"q":"抗体特异性结合病原体表面抗原，增强吞噬细胞对该病原体的吞噬作用，被称为抗体的","o":["中和作用","凝集作用","调理作用","ADCC作用","结合抗原作用"],"a":2,"e":"抗体Fab段结合病原体、Fc段与吞噬细胞FcγR结合，借桥联作用促进吞噬，称调理作用；中和作用指阻断病原体黏附或中和毒素。"},{"q":"具有抗原提呈功能的固有免疫细胞不包括","o":["郎格罕细胞","巨噬细胞","树突状细胞","并指状细胞","中性粒细胞"],"a":4,"e":"具有抗原提呈功能的细胞包括树突状细胞、朗格汉斯细胞、并指状细胞和巨噬细胞；中性粒细胞以吞噬杀菌为主，不表达MHCⅡ类分子，无提呈功能。"},{"q":"与HLA-B27阳性关联的是","o":["类风湿性关节炎","系统性红斑狼疮","乳糜泻","肾小球性肾炎咯血综合征","强直性脊柱炎"],"a":4,"e":"HLA-B27与强直性脊柱炎呈强阳性关联，患者携带率高达58%～97%；HLA-DR4与类风湿关节炎关联，HLA-DQ2/DQ8与乳糜泻关联。"},{"q":"CD8主要表达于","o":["CTL","B细胞","NK细胞","Th","APC"],"a":0,"e":"CD8是MHCⅠ类分子的共受体，表达于CTL表面，辅助TCR识别抗原肽-MHCⅠ复合物；Th表达CD4，B细胞以BCR识别抗原。"},{"q":"容易引起免疫耐受的抗原注入途径顺序为","o":["腹腔注射＞皮下注射＞静脉注射","腹腔注射＞静脉注射＞皮下注射","静脉注射＞皮下注射＞腹腔注射","静脉注射＞腹腔注射＞皮下注射","皮下注射＞腹腔注射＞静脉注射"],"a":3,"e":"抗原注入途径影响耐受诱导，口服最易，其次为静脉注射、腹腔注射、肌内注射，皮下和皮内注射最难，故顺序为静脉注射＞腹腔注射＞皮下注射。"},{"q":"既表达MHCⅠ类分子，又表达MHCⅡ类分子的细胞是","o":["红细胞","嗜碱性粒细胞","B细胞","中性粒细胞","肥大细胞"],"a":2,"e":"B细胞组成性表达MHCⅠ类和Ⅱ类分子，是专职性抗原提呈细胞；红细胞无核，中性粒细胞、嗜碱性粒细胞和肥大细胞不表达MHCⅡ类分子。"},{"q":"在支气管哮喘发生过程中，以下哪种物质对维持支气管处于持续性哮喘状态有重要作用","o":["组胺","白三烯","5-羟色胺","前列腺素","激肽原酶"],"a":1,"e":"LTC4、LTD4、LTE4与平滑肌受体结合，使支气管平滑肌强烈而持久收缩，并增加黏膜腺体分泌，是维持哮喘持续状态的重要介质。"},{"q":"识别细菌或病毒非甲基化CpG DNA的TLR是","o":["TLR1","TLR3","TLR5","TLR7","TLR9"],"a":4,"e":"TLR9表达于内体膜，识别细菌和病毒的非甲基化CpG DNA，激活后诱导Ⅰ型干扰素和促炎因子；TLR3识别dsRNA，TLR7识别ssRNA。"},{"q":"T细胞中参与非特异性免疫应答的亚群是","o":["Th细胞","Tc细胞","TCRαβ＋细胞","TCRγδ＋细胞","记忆性T细胞"],"a":3,"e":"TCRγδ+T细胞属固有免疫细胞，识别抗原不依赖MHC，主要分布于黏膜和皮肤，参与非特异性免疫应答；Th、Tc和记忆T细胞均属αβT细胞。"},{"q":"以下哪项措施对硕大利什曼原虫胞内感染的BALB/c鼠有保护作用","o":["注射IL-4","注射IL-10","注射TGF-β","注射IL-13和IL-14","注射IL-12和IL-18"],"a":4,"e":"IL-12与IL-18可激活NK、ILC1及Th1细胞大量分泌IFN-γ，增强巨噬细胞杀灭胞内原虫的能力。该原虫正是通过减少巨噬细胞产生IL-12来抑制Th1应答。"},{"q":"环孢霉素A主要抑制的免疫细胞是","o":["B淋巴细胞","NK细胞","巨噬细胞","T细胞","中性粒细胞"],"a":3,"e":"环孢素A与他克莫司分别与亲环素、FKBP结合并抑制钙调磷酸酶，阻断IL-2基因转录，选择性抑制T细胞活化增殖，对B细胞影响较小。"},{"q":"关于免疫记忆细胞叙述错误的是","o":["再次遇到抗原时能迅速增殖与分化","仅限于B细胞","可存活数月至数年","参加淋巴细胞再循环","已接受抗原刺激"],"a":1,"e":"记忆细胞包括记忆T细胞和记忆B细胞，均在抗原刺激后形成，可存活数月至数年，参与淋巴细胞再循环，再次接触抗原迅速应答。"},{"q":"DNA疫苗","o":["是将编码病原体有效免疫原的基因插入病毒基因组中","是将编码病原体有效免疫原的基因插入细菌基因组中","可用于表达蛋白质、多糖和脂类抗原","可诱导细胞免疫和体液免疫","不易于保存和运输"],"a":3,"e":"DNA疫苗是将编码保护性抗原的基因克隆入真核表达质粒直接接种，抗原在体内表达后既诱导体液免疫也诱导细胞免疫，且便于保存和运输。"},{"q":"胸腺组织中双阳性T细胞是指","o":["CD3、CD4双阳性","CD4、CD8双阳性","CD80、CD86双阳性","CD3、CD28双阳性","CD3、CD8双阳性"],"a":1,"e":"胸腺细胞发育经双阴性、双阳性、单阳性三个阶段，DP细胞同时表达CD4和CD8，经阳性选择后其中一种表达下调成为SP细胞。"},{"q":"体表物理屏障作用不包括","o":["致密上皮细胞的机械屏障作用","上皮细胞的迅速更新作用","呼吸道上皮细胞纤毛的定向摆动作用","黏膜上皮细胞表面分泌物的冲洗作用","黏膜上皮细胞表面分泌物的抗菌作用"],"a":4,"e":"分泌物的杀菌、抑菌作用属化学屏障，由溶菌酶、抗菌肽、乳酸等实现。物理屏障仅包括致密上皮的机械阻挡、上皮细胞更新及纤毛摆动与分泌液的黏附冲洗。"},{"q":"在局部黏膜抗感染免疫中发挥重要作用的免疫球蛋白是","o":["IgG","IgM","IgE","IgD","sIgA"],"a":4,"e":"SIgA为二聚体，经黏膜上皮细胞分泌至呼吸道、消化道分泌液，是黏膜局部抗感染的主要抗体，可阻止病原体黏附于上皮细胞。"},{"q":"用于治疗丙种球蛋白缺乏症和预防麻疹、传染性肝炎等的是","o":["抗毒素血清","人免疫球蛋白制剂","免疫毒素","抗淋巴细胞丙种球蛋白","细胞因子"],"a":1,"e":"人免疫球蛋白制剂含多克隆IgG，用于治疗丙种球蛋白缺乏症等抗体缺陷病，也可对麻疹、甲型和乙型肝炎提供被动免疫保护。"},{"q":"关于CD4＋T细胞，正确的说法是","o":["其数量占总T细胞的30%～35%","识别抗原时受MHCⅠ类分子的限制","主要分化为CTL细胞","其TCR主要是αβ型","其效应细胞不具有免疫抑制作用"],"a":3,"e":"CD4+T细胞占外周血T细胞约60%～65%，其TCR绝大多数为αβ型，识别MHCⅡ类分子提呈的抗原肽；CTL为CD8+T细胞。"},{"q":"初始T细胞表达哪些MHC分子","o":["MHCⅠ、Ⅱ、Ⅲ类分子","MHCⅠ、Ⅱ类分子","MHCⅠ、Ⅲ类分子","MHCⅡ类分子","MHCⅠ类分子"],"a":4,"e":"MHCⅠ类分子表达于所有有核细胞，初始T细胞只表达MHCⅠ类分子；MHCⅡ类分子主要表达于DC、巨噬细胞和B细胞等专职APC。"},{"q":"关于抗体在移植排斥中的作用，正确的是","o":["抗体与抗原结合后直接激活补体参与移植排斥","抗体通过TLR作用参与移植排斥","增强抗体可导致急性移植排斥反应","阻断抗体Fc段可保护移植物不被排斥","参与ADCC作用的抗体多为IgM"],"a":0,"e":"抗体与移植物血管内皮细胞表面抗原结合后，经经典途径激活补体形成膜攻击复合物，直接损伤血管内皮并引起血管内凝血，是超急性排斥的重要机制。"},{"q":"巨噬细胞表面可识别病原菌表面岩藻糖残基的分子是","o":["清道夫受体","Toll样受体","CD14分子","甘露糖受体","调理性受体"],"a":3,"e":"甘露糖受体表达于巨噬细胞和cDC膜表面，可识别细菌、真菌表面的甘露糖和岩藻糖残基，介导内吞和吞噬。"},{"q":"关于新生儿溶血症描述错误的是","o":["全身换血可治疗新生儿溶血症","母子间ABO血型不符可引起此病","可以采用给患儿注射抗Rh抗体预防此病","可以采用给Rh阴性母亲注射抗Rh抗体预防此病","母子间Rh血型不符可引起此病"],"a":2,"e":"预防新生儿溶血症应在Rh阴性母亲分娩后24～48小时内给母亲注射抗Rh抗体，清除进入母体的Rh阳性红细胞；给患儿注射无预防作用。"},{"q":"用针对哪个CD分子的单克隆抗体可以分离出B淋巴细胞","o":["CD19","CD79a","CD80","CD81","CD86"],"a":0,"e":"CD19为B细胞特征性标志，用抗CD19单克隆抗体可分离B淋巴细胞；CD79a位于胞内，CD80、CD86仅在活化B细胞表达。"},{"q":"机体免疫自稳功能失调，可引发","o":["免疫缺陷病","病毒持续感染","肿瘤","超敏反应","自身免疫病"],"a":4,"e":"免疫自稳通过免疫调节和免疫耐受清除损伤、衰老细胞，维持内环境稳定；该功能紊乱时免疫系统攻击自身组织，导致自身免疫病。"},{"q":"下列哪一项不属于隐蔽抗原的特点","o":["与免疫系统在解剖位置上处于隔绝状态","胚胎期未曾与免疫系统发生接触","与自身免疫系统接触可诱导免疫应答","需经生物、物理或化学因素改变才引起自身免疫反应","外伤、手术、感染等情况下可引起自身免疫病"],"a":3,"e":"隐蔽抗原指解剖上与免疫系统隔绝、胚胎期未曾接触的成分，外伤或感染使其释放即可致自身免疫病；须经理化因素改变才致病者是改变的自身抗原。"},{"q":"AFP主要用于诊断","o":["宫颈癌","乳腺癌","黑色素瘤","肝癌","前列腺癌"],"a":3,"e":"甲胎蛋白是胚胎期合成、出生后降至微量的胚胎抗原，肝癌细胞可重新大量表达，是原发性肝癌的常用血清标志物。"},{"q":"以完整蛋白形式激活T细胞，并不受MHC限制的抗原是","o":["完全抗原","超抗原","半抗原","TD抗原","TI抗原"],"a":1,"e":"超抗原不经加工，直接以完整蛋白连接MHCⅡ类分子抗原结合槽外侧与TCR的Vβ区，非特异性激活大量T细胞克隆，无MHC限制性。"},{"q":"下列哪一个为NK细胞抑制性功能受体","o":["CD16","CD56","MHCⅠ","KIR","KAR"],"a":3,"e":"KIR属免疫球蛋白超家族的杀伤细胞抑制受体，识别自身MHCⅠ类分子后启动抑制信号，防止NK细胞杀伤正常细胞；CD16为活化性受体。"},{"q":"对减毒活疫苗叙述有误的是","o":["用减毒或无毒活病原体制成","接种后产生类似隐性感染","比死疫苗更安全","保存要求比死疫苗高","能诱导产生细胞免疫"],"a":2,"e":"减毒活疫苗在体内存在回复突变的危险，免疫缺陷者和孕妇不宜接种，安全性低于灭活疫苗；但其免疫原性强，可诱导体液和细胞免疫。"},{"q":"关于CD8＋T细胞，下列哪种说法是错误的","o":["可通过合成穿孔素和颗粒酶溶解靶细胞","可诱导靶细胞凋亡","不能杀伤CD4＋T细胞","通过相互作用的表面分子识别靶细胞","对靶细胞的杀伤具有特异性"],"a":2,"e":"CD8+CTL以TCR识别靶细胞抗原肽-MHCⅠ类分子复合物，凡表达MHCⅠ类分子的有核细胞包括活化CD4+T细胞均可被杀伤。"},{"q":"重症肌无力的损伤机制属于","o":["Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅲ型超敏反应","Ⅳ型超敏反应","与超敏反应无关"],"a":1,"e":"抗AChR抗体阻断乙酰胆碱与运动终板受体结合，导致肌无力，属抗体介导细胞表面受体功能障碍的特殊类型Ⅱ型超敏反应。"},{"q":"适应性免疫的特点是","o":["可产生免疫记忆","无针对病原体的特异性","经遗传获得","包括物理屏障和化学屏障作用","感染早期迅速发挥作用"],"a":0,"e":"适应性免疫由T、B细胞克隆性识别抗原，具特异性、多样性和记忆性，再次接触同一抗原可产生更快更强的应答；固有免疫无记忆。"},{"q":"Th细胞活化B细胞主要靠下列哪两种分子间的相互作用","o":["CD4和MHCⅡ类分子","CD40L和CD40","B7和CD28","B7和CTLA-4","ICAM和LFA-1"],"a":1,"e":"Tfh细胞表达CD40L，与B细胞组成性表达的CD40结合，提供B细胞活化最重要的第二信号，促使其增殖、类别转换和抗体产生。"},{"q":"B细胞的抑制性受体是","o":["CD20","CD40","CD79a","CD80","CD86"],"a":0,"e":"CD20是B细胞特有膜分子，交联后参与调节B细胞活化与增殖，是抗CD20单抗清除B细胞的基础；CD22、CD72和FcγRⅡb为经典抑制性受体。"},{"q":"常用分离巨噬细胞的方法是","o":["补体结合试验","ADCC效应","E花环形成","对玻璃和塑料制品的黏附性","凝集反应"],"a":3,"e":"巨噬细胞具有黏附于玻璃和塑料表面的特性，可利用此差异经贴壁法分离纯化；补体结合试验、凝集反应和ADCC均属功能检测方法。"},{"q":"有补体参与的生物学作用是","o":["中和毒素作用","ADCC作用","低渗溶解红细胞","沉淀作用","特异性抗体介导的红细胞溶解"],"a":4,"e":"特异性抗体与红细胞表面抗原结合后激活补体经典途径，形成膜攻击复合物导致红细胞溶解；中和毒素与ADCC均不依赖补体。"},{"q":"A族乙型溶血性链球菌感染后引起肾小球肾炎是由于","o":["链球菌与肾小球基底膜具有相似表位","促进隐蔽抗原的释放","免疫功能缺陷","自身抗原的改变","免疫调节功能异常"],"a":0,"e":"链球菌M蛋白与肾小球基底膜存在共同抗原表位，抗链球菌抗体经分子模拟与基底膜交叉结合造成免疫损伤，也可形成循环免疫复合物沉积。"},{"q":"下列哪种补体成分与C3转化酶的形成无关","o":["C3","C2","C4","C5","B因子"],"a":3,"e":"C3转化酶由C4b2a（经典与凝集素途径）或C3bBb（旁路途径）组成，其形成涉及C4、C2、C3和B因子；C5是C5转化酶的底物，不参与C3转化酶组装。"},{"q":"能特异性杀伤肿瘤的免疫细胞是","o":["CTL","Mφ","Th","Treg","DC"],"a":0,"e":"CTL经TCR识别肿瘤抗原肽-MHCⅠ类复合物，通过穿孔素/颗粒酶和Fas/FasL途径特异性杀伤肿瘤细胞；NK细胞为非特异性杀伤。"},{"q":"B细胞活化所需的双信号是","o":["SmIg-Ag表位，SmIg-MHCⅠ类分子结合","SmIg-Ag表位，SmIg-MHCⅡ类分子结合","Igα，Igβ与Ag表位结合","sIg-Ag表位，CD40-CD40L","半抗原决定簇-MHCⅡ类分子结合"],"a":3,"e":"B细胞活化的第一信号由BCR（sIg）识别抗原表位产生，第二信号最重要的是CD40与活化Tfh细胞表面CD40L的结合。"},{"q":"哺乳类动物的中枢免疫器官包括","o":["淋巴结和脾脏","胸腺和骨髓","法氏囊和胸腺","骨髓和黏膜相关淋巴组织","淋巴结和骨髓"],"a":1,"e":"人和哺乳类动物的中枢免疫器官为骨髓和胸腺，是免疫细胞发生、分化和成熟的场所；法氏囊为禽类特有的中枢免疫器官。"},{"q":"关于γδT细胞，描述错误的是","o":["不受MHC限制","受体缺乏多样性","多为CD4－、CD8－细胞","识别非肽类分子","主要分布在外周血"],"a":4,"e":"γδT细胞在胸腺分化成熟后主要定居于皮肤及肠道、呼吸道、泌尿生殖道黏膜和皮下组织，而非外周血；其TCR多样性有限，识别非肽类抗原且不受MHC限制，多为CD4-CD8-细胞。"},{"q":"补体固有成分中含量最少的","o":["C3","C8","C1q","C5","D因子"],"a":4,"e":"D因子在血浆补体固有成分中浓度最低，约1～2mg/L，是旁路途径的关键酶；C3含量最高，C1q、C5、C8均高于D因子。"},{"q":"体液免疫应答过程中，Th0细胞活化的第一信号是","o":["MHC-Ⅰ类分子与CD8分子间相互作用","MHC-Ⅱ类分子与CD8分子间相互作用","MHC-Ⅱ类分子-抗原肽与TCR间相互作用","IL-2与IL-2受体间相互作用","协同刺激分子与相应受体的相互作用"],"a":2,"e":"CD4+Th细胞的TCR识别APC提呈的抗原肽-MHCⅡ类分子复合物，产生第一信号；共刺激分子与受体结合提供第二信号。"},{"q":"TCR识别抗原的特点是","o":["TCR可识别天然的抗原或抗原肽-MHC分子复合物","TCR可识别游离的抗原肽","TCR只能识别抗原分子中的构象决定基","TCR只能识别抗原肽-MHC分子复合物","TCR只能识别天然的抗原"],"a":3,"e":"TCR不能识别游离抗原或抗原表位，只能识别APC或靶细胞表面由MHC分子提呈的抗原肽-MHC分子复合物，此即MHC限制性。"},{"q":"Th2细胞不分泌的细胞因子是","o":["IL-4","IL-5","IL-10","IL-13","IFN-γ"],"a":4,"e":"Th2细胞分泌IL-4、IL-5、IL-10和IL-13，不产生IFN-γ；IFN-γ是Th1细胞和NK细胞的代表性细胞因子，可抑制Th2细胞。"},{"q":"用于检测CTL杀伤活性的常用实验是","o":["发光免疫分析","ELISPOT","LDH释放法","溶血反应","ELISA"],"a":2,"e":"乳酸脱氢酶释放法以靶细胞膜受损后LDH释放量反映杀伤活性，操作简便且无放射性，是检测CTL和NK细胞杀伤功能的常用方法。"},{"q":"可溶性IL-4R、抗IL-4单抗、抗IL-5单抗可用于治疗","o":["失血后贫血","重症联合免疫缺陷病","银屑病","哮喘","晚期肺癌"],"a":3,"e":"可溶性IL-4R阻断IL-4与受体结合，抗IL-4单抗抑制Th2分化，抗IL-5单抗减少嗜酸性粒细胞，三者均针对Th2型炎症，故用于哮喘治疗。"},{"q":"关于DC在抗原提呈过程中作用的叙述，错误的是","o":["DC既具有免疫激活作用，也能诱导免疫耐受","DC既能激活初始T细胞，也能激活记忆T细胞","DC既能提呈外源性抗原，也能提呈内源性抗原","DC既能激活CD4＋T细胞，也能激活CD8＋T细胞","DC既能提呈抗原给T细胞，也能提呈抗原给B细胞"],"a":4,"e":"DC将抗原加工为抗原肽-MHC复合物提呈给T细胞，可激活初始与记忆T细胞、CD4与CD8 T细胞，并参与中枢及外周耐受；B细胞识别的是天然抗原，不由DC提呈。"},{"q":"关于整合素分子的结构和功能，下述哪项是错误的","o":["属于IgSF","由一条α链和一条β链组成","以β链不同而分组","参与黏附功能","可结合细胞外基质"],"a":0,"e":"整合素由α、β两条肽链非共价结合成异二聚体，按β链不同分组，介导细胞与细胞及细胞外基质的黏附；其胞外区不含Ig样结构域，不属于IgSF。"},{"q":"对TI-1抗原描述错误的是","o":["低浓度时激活抗原特异性B细胞","可诱导产生记忆B细胞","高浓度时多克隆活化B细胞","又称B细胞丝裂原","诱导B细胞应答比TD抗原早"],"a":1,"e":"TI-1抗原单独作用仅诱导低亲和力IgM，不足以诱导类别转换、亲和力成熟和记忆B细胞形成；其高浓度多克隆活化B细胞，低浓度特异性激活B细胞。"},{"q":"对多种免疫细胞具有抑制作用的细胞因子是","o":["IL-1β","IL-6","IL-10","IL-18","TNF-α"],"a":2,"e":"IL-10由Th2细胞、Treg和巨噬细胞产生，可抑制Th1细胞、巨噬细胞和DC的活化及MHCⅡ类分子表达，是重要的抑制性细胞因子。"},{"q":"MHCⅠ类分子抗原提呈途径中，识别抗原肽并产生应答的细胞是","o":["Th","CTL","γδT","NKT","NK"],"a":1,"e":"MHCⅠ类分子途径提呈内源性抗原肽，由CD8+CTL识别并产生杀伤效应；MHCⅡ类分子途径则将外源性抗原肽提呈给CD4+Th细胞。"},{"q":"超急性排斥反应主要由","o":["ABO血型抗体或抗MHCⅠ类分子抗体引起","TDTH细胞和Tc引起","移植物供血不足引起","中性粒细胞浸润引起","自身抗体引起"],"a":0,"e":"受者体内预存的抗ABO血型IgM及抗供者HLA的抗体与移植物血管内皮细胞结合，激活补体并引起血管内凝血，导致超急性排斥反应。"},{"q":"MHCⅡ类分子抗原提呈途径中，识别抗原肽，并产生应答的细胞是","o":["Th","CTL","γδT","B1","B2"],"a":0,"e":"MHCⅡ类分子途径将外源性抗原肽提呈给CD4+T细胞，CD4+Th识别后活化，辅助B细胞产生抗体并活化巨噬细胞。"},{"q":"可诱导肿瘤特异性免疫应答的是","o":["LAK细胞","TIL","抗独特型抗体疫苗","生物导弹","肿瘤疫苗"],"a":4,"e":"肿瘤疫苗以肿瘤抗原免疫荷瘤宿主，主动诱导针对该抗原的特异性T细胞应答；LAK、TIL和生物导弹属被动或导向治疗。"},{"q":"能够与抗原肽结合并将抗原肽提呈到细胞膜表面的功能分子是","o":["B细胞受体","MHC分子","协同刺激分子","T细胞受体","细胞因子受体"],"a":1,"e":"MHC分子以抗原肽结合槽结合经加工产生的抗原肽，形成抗原肽-MHC复合物并表达于细胞膜表面供TCR识别；TCR、BCR和共刺激分子均不承担此功能。"},{"q":"下列对Tr1和Th3描述错误的是","o":["CD4＋Tr1主要分泌IL-10","CD4＋Th3主要分泌TGF-β","Tr1可调控炎症性自身免疫反应和诱发移植耐受","Th3通常在口服耐受和黏膜免疫中发挥作用","它们都属于Foxp3＋调节性T细胞"],"a":4,"e":"Tr1主要分泌IL-10，Th3主要分泌TGF-β，参与调控炎症性自身免疫和口服耐受，二者均不表达Foxp3，有别于CD4+CD25+Foxp3+的Treg。"},{"q":"下列关于sIgA的描述错误的是","o":["由两个单体IgA、一个J链和一个分泌片组成","单体IgA由淋巴结中的浆细胞产生","分泌片由黏膜上皮细胞产生","分泌片的功能是保护sIgA不被蛋白水解酶破坏","母亲可将sIgA通过乳汁传递给婴儿"],"a":1,"e":"分泌型IgA由黏膜固有层浆细胞产生的二聚体经黏膜上皮细胞摄取，与分泌片结合后分泌至黏膜表面，分泌片保护其铰链区免受蛋白酶降解。"},{"q":"关于宿主对肿瘤免疫应答的特点，正确的是","o":["在肿瘤进行性生长时，肿瘤患者的免疫功能会受到肿瘤的抑制","当有细胞恶变时，CTL发挥第一线的抗肿瘤作用","细胞免疫和体液免疫在抗肿瘤免疫中同样重要","固有免疫是抗肿瘤免疫的主力，特异性免疫起协同作用","免疫功能低下的人和免疫功能正常的人发生肿瘤的几率相似"],"a":0,"e":"肿瘤进行性生长时可分泌免疫抑制因子并诱导抑制性细胞，使宿主免疫功能下降，属肿瘤免疫逃逸机制。抗肿瘤以特异性T细胞为主，固有免疫具双向作用。"},{"q":"以下关于抗体分子结构域的说法，错误的是","o":["轻链有2个结构域","IgA和IgD的重链有4个结构域","IgE和IgM的重链有5个结构域","IgG的重链有4个结构域","抗体的Fab段有2个结构域"],"a":4,"e":"Fab段由重链VH、CH1与轻链VL、CL共4个结构域组成；IgG、IgA、IgD重链含4个结构域，IgM、IgE重链含5个结构域，轻链均为2个结构域。"},{"q":"下列哪项不是HLA基因复合体编码的产物","o":["HLAⅠ类分子的重链","HLAⅠ类分子的β2m链","HLAⅡ类分子的α链","HLAⅡ类分子的β链","C2、C4、TNF"],"a":1,"e":"β2m由15号染色体上的非HLA基因编码，与HLAⅠ类分子重链非共价结合后表达于细胞表面；HLA复合体编码Ⅰ类重链、Ⅱ类α链和β链以及C2、C4、TNF等。"},{"q":"关于Ⅳ型超敏反应描述正确的是","o":["以中性粒细胞浸润为主的炎症","抗原注入后4小时达到反应高峰","补体参与炎症的发生","能通过血清Ig被动转移","以单个核细胞浸润为主的炎症"],"a":4,"e":"Ⅳ型超敏反应由效应T细胞介导，以单核/巨噬细胞和淋巴细胞浸润为主的炎症为特征，通常在接触抗原后24～72小时达高峰。"},{"q":"免疫防御功能低下的机体易发生","o":["肿瘤","超敏反应","自身免疫病","反复感染","免疫增生性疾病"],"a":3,"e":"免疫防御指抵御病原体入侵，功能低下或缺陷时表现为反复感染，见于免疫缺陷病；免疫监视低下则易发生肿瘤。"},{"q":"用IFN-α治疗效果显著的是","o":["再生障碍性贫血","类风湿关节炎","毛细胞白血病","多发性硬化症","血小板减少"],"a":2,"e":"IFN-α对毛细胞白血病疗效显著，也用于慢性髓细胞白血病、卡波西肉瘤以及乙型、丙型肝炎的抗病毒治疗。"},{"q":"关于巨噬细胞抗肿瘤作用的描述，错误的是","o":["可特异杀伤肿瘤细胞","作为抗原提呈的APC","分泌TNF、NO等细胞毒性因子间接杀伤肿瘤细胞","巨噬细胞表面有Fc受体，可通过特异性抗体介导的ADCC效应杀伤肿瘤细胞","非特异吞噬和杀伤肿瘤细胞"],"a":0,"e":"巨噬细胞杀伤肿瘤不具抗原特异性，靠非特异吞噬、ADCC、调理作用及分泌TNF、NO等间接杀伤；作为专职APC提呈肿瘤抗原可诱导特异性应答，但杀伤本身无特异性。"},{"q":"关于B1细胞错误的描述是","o":["表面标记大多为CD5＋、CD11＋、CD23－、mIgM＋","识别Ag谱较窄，主要包括TI-Ag和变性的自身成分","个体发育过程中出现较晚","产生的免疫应答以IgM为主，无Ig类别转换和免疫记忆","具有自我更新的能力"],"a":2,"e":"B1细胞在个体发育中出现早，主要分布于腹腔、胸腔和肠黏膜固有层，表达CD5和mIgM，具自我更新能力，识别TI抗原和变性自身抗原，主要产生IgM。"},{"q":"淋巴结中初始B细胞主要存在于","o":["初级淋巴滤泡","次级淋巴滤泡","髓质区","生发中心","深皮质区"],"a":0,"e":"初级淋巴滤泡主要含未受抗原刺激的初始B细胞；受抗原刺激后形成生发中心者称次级淋巴滤泡，深皮质区为T细胞定居区。"},{"q":"关于初始T细胞与APC间黏附分子的非特异性结合，错误的是","o":["发生在淋巴结的副皮质区","包括LFA-1与ICAM-1的结合","包括CD2与LFA-3的结合","是不可逆的","为TCR识别特异性抗原肽提供机会"],"a":3,"e":"初始T细胞与APC表面黏附分子（LFA-1/ICAM-1、CD2/LFA-3）的结合短暂而可逆，使两细胞靠拢，为TCR扫描识别特异性pMHC提供机会。"},{"q":"NADPH氧化酶系统缺陷导致","o":["链球菌感染","慢性肉芽肿病","桥本病","白细胞黏附功能缺陷","DiGeorge综合征"],"a":1,"e":"慢性肉芽肿病因吞噬细胞NADPH氧化酶系统缺陷，不能产生超氧阴离子等活性氧，杀菌功能低下，反复发生化脓性感染，多为X连锁遗传。"},{"q":"接种预防性疫苗获得免疫保护的主要原理是","o":["诱导高水平的IgM","诱导大量的细胞因子","诱导特异性抗病原体关键蛋白的中和性抗体IgG","诱导补体活性片断产生","诱导特异性T细胞应答"],"a":2,"e":"预防性疫苗模拟自然感染，诱导针对病原体关键保护性抗原的特异性中和抗体（以IgG为主）及记忆细胞，再次接触病原体时迅速产生再次应答。"},{"q":"以下属于巨噬细胞表面的模式识别受体的是","o":["IgG FcR","单核细胞趋化蛋白-1受体","肿瘤坏死因子受体","Toll样受体","补体C4受体"],"a":3,"e":"Toll样受体是表达于巨噬细胞等固有免疫细胞膜或胞内的模式识别受体，识别PAMP和DAMP；FcγR和补体受体属调理吞噬受体。"},{"q":"适应性免疫应答","o":["时相是在感染后数分钟至96小时","可遗传","具有特异性","先天获得","吞噬细胞是主要效应细胞"],"a":2,"e":"适应性免疫应答由T、B细胞克隆性识别抗原后活化、增殖、分化产生，具有高度特异性、记忆性和获得性；固有免疫才在感染后数分钟至数小时内起作用。"},{"q":"免疫耐受是指机体对","o":["任何抗原都不发生反应的状态","改变的自身成分不发生反应的状态","自身组织成分不发生反应的状态","某种抗原不发生反应的状态","超抗原不发生反应的状态"],"a":3,"e":"免疫耐受是免疫系统接受某种特定抗原刺激后产生的特异性无应答状态，具有特异性和获得性，并非对所有抗原或全部自身成分都不反应。"},{"q":"下列哪项不是调节性T细胞的作用特点","o":["分泌抑制性细胞因子","通过细胞间直接接触抑制","抑制APC抗原提呈","抑制肿瘤的发生","抑制自身免疫性疾病的发生"],"a":3,"e":"Treg分泌IL-10、TGF-β，通过细胞接触、竞争IL-2和表达CTLA-4抑制APC及效应T细胞，维持自身耐受，但同时也抑制抗肿瘤免疫。"},{"q":"与G-CSF联合应用于外周血干细胞移植的重组细胞因子药物是","o":["LT","IL-6","IFN-γ","SCF","IL-4"],"a":3,"e":"干细胞因子SCF与G-CSF联合用于外周血造血干细胞动员和移植，可提高CD34+细胞采集量。"},{"q":"下列关于脾的描述错误的是","o":["是胚胎时期的造血器官","是人体最大的外周免疫器官","结构上与淋巴管道相连","定居最多的免疫细胞是B细胞","是对血源性抗原产生免疫应答的主要场所"],"a":2,"e":"脾在结构上不与淋巴管道相连，无淋巴窦而含大量血窦，是胚胎期造血器官和人体最大的外周免疫器官，以B细胞为主，对血源性抗原应答。"},{"q":"抗体介导的超敏反应有","o":["Ⅰ、Ⅱ、Ⅳ型超敏反应","Ⅰ、Ⅱ、Ⅲ型超敏反应","Ⅰ、Ⅲ、Ⅳ型超敏反应","Ⅱ、Ⅲ、Ⅳ型超敏反应","Ⅱ、Ⅲ型超敏反应"],"a":1,"e":"Ⅰ、Ⅱ、Ⅲ型超敏反应均由抗体介导，分别为IgE、细胞表面抗原的抗体和免疫复合物；Ⅳ型由效应T细胞介导，属细胞型超敏反应。"},{"q":"关于记忆B细胞，下列说法错误的是","o":["合成大量IgM","接触同一抗原可迅速活化","在生发中心形成","与静息B细胞的大小相似","介导B细胞的再次免疫"],"a":0,"e":"记忆B细胞不分泌抗体，再次接触同一抗原时迅速活化增殖并分化为浆细胞，主要产生高亲和力IgG而非大量IgM。"},{"q":"补体的三种激活途径均必须有下列哪种成分参与","o":["C1q","C4和C2","C3","B因子","D因子"],"a":2,"e":"C3是三条补体激活途径的共同组分，血浆含量最高，各途径形成的C3转化酶均裂解C3，故C3缺乏时三条途径均受损。"},{"q":"用于主动特异免疫治疗肿瘤的是","o":["IL-2、INF-α","短小棒状杆菌","独特型抗体瘤苗","放射免疫疗法","输入肿瘤特异性T淋巴细胞"],"a":2,"e":"抗独特型抗体瘤苗模拟肿瘤抗原表位，免疫后可诱导机体产生特异性抗肿瘤应答，属主动特异性免疫治疗；输入TIL属过继治疗。"},{"q":"各种天然免疫球蛋白单体分子共有的特性是","o":["与靶细胞结合后均能介导ADCC效应","具有两个完全相同的抗原结合部位","轻链与重链之间通过J链结合","与抗原结合后均能激活补体","与颗粒性抗原结合后均能介导调理作用"],"a":1,"e":"天然Ig单体均由两条相同重链和两条相同轻链构成，含两个完全相同的抗原结合部位；ADCC、激活补体和调理作用仅部分类别具备。"},{"q":"X连锁慢性肉芽肿病（CGD）属于哪类免疫缺陷病","o":["T淋巴细胞缺陷病","B淋巴细胞缺陷病","联合免疫缺陷病","补体缺陷病","吞噬细胞缺陷病"],"a":4,"e":"X连锁慢性肉芽肿病由吞噬细胞NADPH氧化酶亚基基因突变引起，属吞噬细胞缺陷病，表现为反复化脓性感染。"},{"q":"属于CXC趋化性细胞因子，对中性粒细胞具有趋化作用的IL是","o":["IL-1","IL-2","IL-3","IL-4","IL-8"],"a":4,"e":"IL-8属CXC亚族趋化因子，是趋化并激活中性粒细胞最强的细胞因子之一，可促其脱颗粒并上调黏附分子；IL-1主要作为内源性致热原和促炎因子。"},{"q":"TD抗原引起免疫应答的特点是","o":["可形成记忆细胞","只诱导细胞免疫应答","产生免疫应答的细胞为B1细胞","只诱导体液免疫应答","可直接诱导T、B细胞产生免疫应答"],"a":0,"e":"TD抗原需Th细胞辅助，可诱导抗体类别转换和亲和力成熟，并形成记忆T细胞和记忆B细胞，产生迅速高效的再次应答。"},{"q":"IgG通过经典途径激活补体至少需要","o":["1个","2个","3个","4个","5个"],"a":1,"e":"一个C1q分子须同时与两个以上IgG的Fc段结合才能被稳定激活，故IgG经经典途径激活补体至少需要两个相邻IgG分子；IgM单个分子即可。"},{"q":"以下关于B细胞表位的描述，错误的是","o":["由BCR识别","大多为构象表位","识别受MHC限制","无需蛋白酶降解就可识别","一般由10个左右氨基酸组成"],"a":2,"e":"B细胞表位多位于抗原表面，为构象表位，由BCR直接识别，无需APC加工，也不受MHC限制；受MHC限制是T细胞表位被TCR识别的特点。"},{"q":"关于Th1型细胞因子，说法不正确的是","o":["包括IFN-γ、TNF和IL-12","促进Th1细胞进一步增殖","抑制Th2细胞增殖","可增强细胞介导的抗胞内病原体感染","促进IgE型抗体的生成"],"a":4,"e":"Th1型细胞因子以IFN-γ、TNF-α为主，促进Th1增殖、抑制Th2、增强对胞内病原体的细胞免疫；IgE的生成由Th2细胞分泌的IL-4、IL-13诱导。"},{"q":"抗CD3、抗CD25等单克隆抗体作为免疫抑制剂在临床上首先治疗下列哪种疾病","o":["慢性乙型病毒性肝炎","肝细胞癌","肾移植后急性排斥反应","类风湿性关节炎","持续性哮喘"],"a":2,"e":"抗CD3和抗CD25单抗最初用于防治肾移植后急性排斥反应，前者清除T细胞，后者阻断IL-2受体α链而抑制T细胞增殖。"},{"q":"以下关于轻链的说法，错误的是","o":["轻链分子量约为25kD，约由214个氨基酸残基构成","轻链分为κ链和λ链两种","一个免疫球蛋白分子中的两条轻链可以相同，也可以是不同型别","同一个体内存在分别带有κ链或λ链的抗体分子","5类免疫球蛋白中都可出现κ链和λ链"],"a":2,"e":"一个完整抗体分子两条轻链的型别总是相同的，同一B细胞克隆只表达一种轻链；同一个体内可并存带κ链或λ链的抗体，五类Ig的轻链均可为κ或λ型。"},{"q":"下列细胞因子中，哪一个对T细胞增殖至关重要","o":["IL-2","IL-4","IL-6","IL-10","IL-12"],"a":0,"e":"IL-2是T细胞自分泌生长因子，与IL-2受体结合为T细胞增殖分化所必需；阻断IL-2/IL-2R通路可抑制移植排斥反应。"},{"q":"PSA属于","o":["致癌病毒产物","基因突变产物","正常组织中的隐蔽抗原","胚胎抗原","分化抗原"],"a":4,"e":"前列腺特异性抗原PSA由前列腺上皮细胞表达，属分化抗原，肿瘤细胞可保留或增强表达，是前列腺癌诊断和靶向治疗的靶点。"},{"q":"下列APC中，抗原提呈功能最强的是","o":["巨噬细胞","树突状细胞","上皮细胞","B细胞","内皮细胞"],"a":1,"e":"DC是体内功能最强的专职性APC，高表达MHCⅡ类分子和共刺激分子，能有效激活初始T细胞；巨噬细胞和B细胞主要激活已活化的T细胞。"},{"q":"下列哪项属于人工主动免疫","o":["注射丙种球蛋白预防麻疹","接种卡介苗预防结核","注射胸腺肽治疗恶性肿瘤","静脉注射CIK细胞治疗肿瘤","注射破伤风抗毒素治疗破伤风"],"a":1,"e":"接种卡介苗使机体主动产生针对结核分枝杆菌的特异性免疫并形成记忆，属人工主动免疫；注射丙种球蛋白和破伤风抗毒素属人工被动免疫。"},{"q":"可刺激多种造血细胞分化成熟的细胞因子是","o":["TGF","IL","TNF","IFN","CSF"],"a":4,"e":"集落刺激因子作用于多能造血干细胞及各阶段造血祖细胞，诱导其分化增殖为相应谱系细胞，包括GM-CSF、G-CSF、M-CSF、EPO、SCF和TPO。"},{"q":"抗体J链的功能是","o":["结合sIgA并转运到黏膜表面","保护Ig铰链区不受蛋白酶水解","将重链连接起来","将轻链和重链偶联","将免疫球蛋白单体分子连接成多聚体"],"a":4,"e":"J链由浆细胞合成，富含半胱氨酸，通过二硫键将Ig单体连接成二聚体（SIgA）或五聚体（IgM）；分泌片保护铰链区并介导转运。"},{"q":"B细胞的体细胞高频突变是指","o":["B细胞在任何时候都可能发生突变，频率远高于普通体细胞","B细胞在分裂时发生突变的频率远高于普通体细胞","B细胞在骨髓中阴性选择时突变的频率远高于普通体细胞","B细胞的突变频率远高于普通体细胞，大约高10倍","B细胞的突变频率远高于普通体细胞，大约高100倍"],"a":1,"e":"体细胞高频突变发生于生发中心中心母细胞增殖分裂时，V区CDR基因碱基突变率约为体细胞自发突变的100万倍，需抗原诱导和Tfh辅助，是亲和力成熟的基础。"},{"q":"关于B细胞形成的耐受，以下正确的是","o":["只有低剂量TD抗原可诱导","诱导成功所需时间短","耐受状态持续时间短","只有低剂量TI抗原可诱导","容易形成耐受"],"a":2,"e":"B细胞形成耐受需抗原量大，发生缓慢（1～2周），维持时间短（数周）；T细胞耐受形成快，持续数月至数年。"},{"q":"关于正常人丙种球蛋白制剂，下述哪项是错误的","o":["包括胎盘球蛋白和血浆丙种球蛋白","可用于某些传染病的应急预防和潜伏期治疗","可达到防止发病，减轻症状，缩短病程的效果","只含IgG类抗体","一般为多价抗血清"],"a":3,"e":"丙种球蛋白制剂主要含IgG，也含少量IgA和IgM，并非只含IgG；其抗体谱广，可用于传染病的应急预防和潜伏期治疗。"},{"q":"进行抗肿瘤主动免疫治疗时，可给患者输入","o":["单克隆抗体","淋巴因子激活的杀伤细胞","灭活瘤苗","肿瘤浸润淋巴细胞","IL-10"],"a":2,"e":"主动免疫治疗是给患者输入能激发自身抗肿瘤应答的制剂，如X线照射灭活的瘤苗、DC瘤苗等；单抗、LAK与TIL属被动免疫或过继免疫治疗。"},{"q":"结核菌素试验检测的免疫细胞是","o":["B细胞","T细胞","中性粒细胞","NK细胞","浆细胞"],"a":1,"e":"结核菌素试验为典型的迟发型超敏反应，皮内注射PPD后由致敏T细胞识别抗原、释放细胞因子招募巨噬细胞形成局部硬结，可反映T细胞功能。"},{"q":"对中性粒细胞具有趋化和激活作用的是","o":["MIP-1α/β","MCP-1","IL-1β","IL-6","IL-8"],"a":4,"e":"IL-8即CXCL8，属CXC家族趋化因子，由感染部位上皮细胞和巨噬细胞产生，可趋化并激活中性粒细胞；MCP-1、MIP-1α/β主要募集单核/巨噬细胞。"},{"q":"可抑制T细胞活化的配对分子是","o":["B7/CD28","CTLA-4/B7","LFA-1/ICAM-1","CD40L/CD40","CD2/LFA-3"],"a":1,"e":"CTLA-4表达于活化的T细胞，与B7结合的亲和力显著高于CD28，竞争性结合后向T细胞传递抑制信号，下调或终止T细胞活化。"},{"q":"可用于检测人类B细胞功能的实验是","o":["E花环试验","溶血空斑试验","肥达氏反应","结核菌素试验","乳酸脱氢酶释放法"],"a":1,"e":"溶血空斑试验用绵羊红细胞免疫小鼠后检测脾脏抗体形成细胞数量，反映B细胞产生抗体的功能；E花环试验用于检测T细胞。"},{"q":"动物血清抗毒素对人而言，属于","o":["异种抗原","同种异型抗原","独特型抗原","异嗜性抗原","自身抗原"],"a":0,"e":"动物血清抗毒素多来源于马，其蛋白质对人属异种抗原，可刺激人体产生抗马血清抗体，再次注射可引起血清过敏性休克。"},{"q":"属于TSA的是","o":["甲胎蛋白（AFP）","胚胎硫糖蛋白抗原（FSA）","癌胚抗原（CEA）","人恶性黑色素瘤基因编码的MZ2-E抗原","γ-胚胎蛋白"],"a":3,"e":"MZ2-E由MAGE-1基因编码，仅表达于黑色素瘤等肿瘤细胞，属肿瘤特异性抗原；AFP、CEA、FSA、γ-胚胎蛋白均为胚胎期表达、出生后低表达的胚胎抗原。"},{"q":"用于器官移植受者，阻止移植排斥反应发生，延长移植物存活时间的是","o":["抗毒素血清","丙种球蛋白","免疫毒素","抗淋巴细胞丙种球蛋白","细胞因子"],"a":3,"e":"抗淋巴细胞丙种球蛋白由人淋巴细胞免疫动物制备，可清除受者T细胞、抑制细胞免疫，临床用于防治移植排斥反应、延长移植物存活时间。"},{"q":"尚未发现对肿瘤细胞有杀伤作用的免疫细胞是","o":["细胞毒T细胞","NK细胞","嗜碱性粒细胞","活化巨噬细胞","淋巴因子激活的杀伤细胞"],"a":2,"e":"嗜碱性粒细胞是Ⅰ型超敏反应的主要效应细胞，释放组胺等介质；CTL、NK细胞、活化的巨噬细胞及LAK细胞均有杀伤肿瘤细胞的作用。"},{"q":"关于体细胞高频突变，以下说法正确的是","o":["Ig恒定区基因也可能发生","不需要抗原诱导","不需要Th细胞的辅助","导致BCR的多样性","最终结果导致抗体亲和力下降"],"a":3,"e":"体细胞高频突变发生于生发中心，需抗原诱导和Tfh细胞辅助，仅累及Ig基因V区，增加BCR多样性并导致抗体亲和力成熟。"},{"q":"促进红细胞的细胞因子是","o":["EPO","IL-11","TPO","IL-10","IL-4"],"a":0,"e":"EPO刺激红系祖细胞增殖分化，临床用于肾性贫血；TPO主要促进血小板生成，IL-11亦作用于巨核系。"},{"q":"集落刺激因子是","o":["IL","IFN","TNF","CSF","TGF"],"a":3,"e":"集落刺激因子是能刺激造血干细胞和造血祖细胞分化、增殖形成相应细胞集落的细胞因子，包括GM-CSF、G-CSF、M-CSF、EPO、SCF和TPO。"},{"q":"介导NK细胞、巨噬细胞、中性粒细胞发挥ADCC效应的Ig主要是","o":["IgA","IgM","IgE","IgD","IgG"],"a":4,"e":"IgG的Fc段可与NK细胞、巨噬细胞和中性粒细胞的FcγR结合，通过桥联介导ADCC，是介导该效应的主要抗体类别。"},{"q":"柯萨奇病毒感染引发糖尿病的主要机制是","o":["隐蔽抗原的释放","表位扩展","免疫忽视","分子模拟","自身抗原改变"],"a":3,"e":"柯萨奇病毒某些蛋白与胰岛β细胞抗原表位结构相似，感染后诱生的抗体和效应T细胞交叉攻击胰岛细胞，属病原体感染所致分子模拟引发的自身免疫病。"},{"q":"下列哪种免疫缺陷病应用基因治疗已经获得成功","o":["ADA缺陷病","CGD","WAS","CVID","Bruton病"],"a":0,"e":"ADA缺陷致严重联合免疫缺陷，将正常ADA基因经逆转录病毒载体转入患者CD34+造血干细胞，已使部分患者获益，是成功的基因治疗范例。"},{"q":"发生机制主要与表位扩展有关的疾病是","o":["风湿性心脏病","慢性反复发作性实验性过敏反应性脑脊髓膜炎","自身交感性眼炎","毒性弥漫性甲状腺肿","长期服用α-甲基多巴引起的自身免疫性溶血性贫血"],"a":1,"e":"表位扩展指自身免疫应答由针对少数表位扩展到更多表位，使损伤不断加重，是慢性反复发作性实验性过敏反应性脑脊髓膜炎迁延及自身免疫病进展的重要机制。"},{"q":"抗原提呈能力最强的APC是","o":["DC","Mϕ","B细胞","内皮细胞","成纤维细胞"],"a":0,"e":"DC是体内功能最强的专职性APC，高表达MHCⅡ类分子和共刺激分子，是唯一能直接激活初始T细胞的APC；巨噬细胞和B细胞仅激活已活化或记忆T细胞。"},{"q":"可通过ADCC效应杀伤肿瘤细胞的淋巴细胞是","o":["γδT细胞","B细胞","αβT细胞","NKT细胞","NK细胞"],"a":4,"e":"NK细胞表达FcγRⅢ（CD16），与包被肿瘤细胞的IgG Fc段结合后经ADCC杀伤靶细胞，是介导该效应的主要淋巴细胞。"},{"q":"关于免疫耐受下述正确的是","o":["是由于射线照射或药物引起的","对所有的抗原均不产生免疫应答","成年动物较容易诱导形成免疫耐受","T细胞较B细胞容易形成免疫耐受","抗原在体内消失后耐受性仍持续存在"],"a":3,"e":"T细胞耐受形成快、所需抗原量低、维持时间长；B细胞耐受形成慢、维持时间短，故T细胞较B细胞更易诱导耐受。"},{"q":"使胎儿Rh＋红细胞发生溶解破坏的主要抗体是","o":["免疫抗体IgA","免疫抗体IgM","天然抗体IgM","免疫抗体IgG","亲细胞性IgE"],"a":3,"e":"Rh阴性母体产生的抗Rh抗体为IgG，可经胎盘进入胎儿血循环，与Rh阳性红细胞结合后经激活补体和ADCC使其溶解破坏，引起新生儿溶血症。"},{"q":"CD28分子的配体是","o":["CD58","ICAM-1","MHCⅠ类分子","TCR","CD80/CD86"],"a":4,"e":"CD28的配体为APC表面的CD80（B7-1）和CD86（B7-2），二者结合提供T细胞活化的第二信号；CD58是CD2的配体。"},{"q":"下列关于B1细胞的描述，错误的是","o":["对细菌多糖抗原应答","mIgM＋","表达CD5","无免疫记忆性","易发生体细胞高频突变"],"a":4,"e":"B1细胞为CD5+、mIgM+的固有免疫样B细胞，主要对细菌多糖等TI抗原应答，直接产生IgM，无免疫记忆，不发生生发中心内的体细胞高频突变。"},{"q":"经典途径中激活补体能力最强的免疫球蛋白是","o":["IgG","IgE","血清型IgA","sIgA","IgM"],"a":4,"e":"IgM为五聚体，含5个Fc段，结合抗原后暴露多个C1q结合位点，活化经典途径的能力最强；IgG次之，IgA、IgE和IgD无活化经典途径的能力。"},{"q":"与X连锁高IgM综合征有关的膜分子异常是","o":["CD40L表达异常","CD40表达异常","CD95表达异常","IL-2Rγ表达异常","MHCⅡ类分子表达异常"],"a":0,"e":"X连锁高IgM综合征由X染色体上CD40L基因突变所致，T细胞不能提供CD40L信号，抗体类别转换障碍，血清IgM升高而IgG、IgA降低。"},{"q":"T细胞阴性选择中，被清除的细胞是","o":["不能与抗原肽-MHCⅠ有效结合的DP细胞","与抗原肽-MHCⅠ亲和力过高的DP细胞","与抗原肽-MHCⅠ亲和力过高的SP细胞","不与抗原肽-MHCⅠ发生结合的SP","与抗原肽-MHCⅠ有低亲和力的SP细胞"],"a":2,"e":"髓质区SP细胞与DC、巨噬细胞提呈的自身抗原肽-MHC复合物高亲和力结合后凋亡，低亲和力者存活成熟；阴性选择即清除自身反应性T细胞。"},{"q":"补体激活经典途径中的C5转化酶是","o":["C3bBb3b","C4b2a3b","C3bBb","C4b2a","C56789"],"a":1,"e":"经典途径的C3转化酶C4b2a裂解C3后，C3b与C4b2a结合形成C4b2a3b，即C5转化酶；C3bBb3b为旁路途径的C5转化酶。"},{"q":"可用于检测外周T细胞总数的CD分子是","o":["CD1","CD2","CD3","CD4","CD8"],"a":2,"e":"CD3表达于所有成熟T细胞表面，与TCR组成复合物并转导信号，是检测外周T细胞总数的标志；CD4、CD8仅表达于相应亚群。"},{"q":"中和抗体发挥效应的主要作用机制是","o":["裂解病原体","阻止病原体感染宿主细胞","调理作用","ADCC作用","激活补体"],"a":1,"e":"中和抗体经V区与病原体表面结合位点结合，封闭其黏附素或受体结合部位，使病原体不能黏附侵入宿主细胞；裂解病原体、调理和ADCC由补体及Fc受体介导。"},{"q":"氨苯磺酸结合载体诱导机体产生的抗氨苯磺酸抗体，只能与氨苯磺酸结合，而无法与结构相近的氨苯甲醛结合，这体现了抗原的什么性质","o":["免疫原性","免疫反应性","抗原特异性","抗原的交叉免疫性","半抗原-载体效应"],"a":2,"e":"抗原特异性指抗原刺激机体产生应答及与效应产物结合均呈专一性，分子基础是抗原表位；抗氨苯磺酸抗体只识别间位氨苯磺酸表位，对结构相近基团呈弱反应或无反应。"},{"q":"反复输血、多次怀孕、长期透析的移植受体容易发生","o":["超急性排斥反应","急性排斥反应","亚急性排斥反应","慢性排斥","移植物抗宿主反应"],"a":0,"e":"受者体内预存抗供者ABO血型抗原、HLA及血管内皮细胞抗原的抗体，移植血管接通后数分钟至24小时内即发生超急性排斥反应。"},{"q":"属于TI-1抗原的是","o":["百日咳菌胞壁脂多糖","葡聚糖半Ag偶联的聚蔗糖","沙门菌多聚鞭毛素","肺炎球菌荚膜多糖","结核杆菌纯蛋白衍生物"],"a":0,"e":"TI-1抗原即B细胞丝裂原，如细菌脂多糖和细菌来源DNA，高浓度非特异性激活多克隆B细胞，低浓度经特异性BCR激活B细胞。"},{"q":"关于T细胞和B细胞介导的免疫应答，下列说法错误的是","o":["均产生效应产物","对TD-Ag的应答均需T细胞的参与","效应产物的作用都是特异性的","都能形成免疫耐受","对TD-Ag的应答都产生记忆细胞"],"a":2,"e":"抗体与靶抗原的结合是特异性的，但经Fc段介导的ADCC、调理吞噬等效应并无特异性；T、B细胞应答均可产生效应产物、记忆细胞和耐受。"},{"q":"关于腺苷脱氨酶缺陷发病机制的描述，下列哪一项正确","o":["属于T细胞缺陷","属于B细胞缺陷","属于吞噬细胞缺陷","属于补体缺陷","属于联合免疫缺陷"],"a":4,"e":"腺苷脱氨酶缺陷使嘌呤补救合成途径中间产物蓄积，对发育中的T、B细胞均有毒性，导致T、B细胞联合缺陷，属重症联合免疫缺陷。"},{"q":"发生机制主要与自身抗原改变有关的疾病是","o":["交感性眼炎","风湿性心脏病","睾丸外伤后的不育症","系统性红斑狼疮","青霉素引起的自身免疫性溶血性贫血"],"a":4,"e":"青霉素等小分子药物吸附于红细胞膜成为完全抗原，使膜抗原被修饰，诱导抗体产生并激活补体溶血；交感性眼炎属隐蔽抗原释放。"},{"q":"HLA的表型是指","o":["HLA基因在体细胞一条染色体的组合","HLA基因在体细胞两条染色体的组合","一条染色体上的基因组合","两条染色体上的基因组合","某一个体HLA分子的型别"],"a":4,"e":"HLA表型指某一个体所表达的HLA分子的型别组合，由两条单倍型共同决定并共显性表达；单倍型才是染色体上HLA基因的组合。"},{"q":"CD4 T细胞识别的抗原表位不包括","o":["线性表位","顺序表位","构象表位","蛋白降解后的多肽片断","MHCⅡ类分子提呈的表位"],"a":2,"e":"CD4+T细胞识别的表位为APC加工后由MHCⅡ类分子提呈的线性即顺序表位肽；构象表位由天然蛋白空间结构形成，属B细胞表位。"},{"q":"在B细胞对TD抗原的应答中，Th细胞不发挥作用的是","o":["抗体亲和力成熟","生发中心的形成","对抗原的特异性识别","B细胞的活化","Ig类别转换"],"a":2,"e":"BCR可直接识别天然构象的抗原表位，无MHC限制性，此过程不需Th细胞参与；Th细胞辅助B细胞活化、生发中心形成和类别转换。"},{"q":"以下分类正确的是","o":["白喉毒素属于TI-1抗原，LPS属于TI-2抗原","白喉毒素属于TI-1抗原，LPS属于TD抗原","白喉毒素属于TI-2抗原，LPS属于TI-1抗原","白喉毒素属于TD抗原，LPS属于TI-1抗原","白喉毒素属于TD抗原，LPS属于TI-2抗原"],"a":3,"e":"LPS是B细胞丝裂原，属TI-1抗原，可直接激活B细胞；白喉毒素为蛋白质，含T细胞和B细胞表位，需Th辅助，属TD抗原。"},{"q":"关于TI-1抗原，以下说法错误的是","o":["LPS是一种TI-1抗原","成熟B细胞可以被其激活","不成熟B细胞可以被其激活","诱导产生高亲和力IgM","又称B细胞丝裂原"],"a":3,"e":"TI-1抗原如LPS兼有丝裂原性质，可经BCR和丝裂原受体同时激活成熟与不成熟B细胞，只诱导产生低亲和力IgM，无类别转换和免疫记忆。"},{"q":"可特异性识别并摄取抗原的APC是","o":["单核细胞","内皮细胞","B细胞","树突状细胞","巨噬细胞"],"a":2,"e":"B细胞借BCR特异性识别、结合并内化抗原，再经MHCⅡ类途径提呈给Th细胞；DC和巨噬细胞以模式识别受体非特异性摄取抗原。"},{"q":"由Th细胞分泌并参与CTL细胞增殖与分化的细胞因子是","o":["IL-1","TNF","IFN-γ","MCP","IL-8"],"a":2,"e":"Th1细胞分泌的IFN-γ与IL-2协同刺激CTL前体细胞增殖分化为效应CTL；TNF主要介导炎症和靶细胞杀伤，无此协同作用。"},{"q":"根据独特型网络学说理论推测，对于类风湿关节炎宜采用的治疗方法是","o":["皮内注射抗原","应用β型抗独特型淋巴细胞","应用α型抗独特型抗体","静脉内注射抗原","应用β型抗独特型抗体"],"a":2,"e":"按独特型网络学说，α型抗独特型抗体可识别结合致病抗体V区的独特位，阻断其与抗原结合，故可用于治疗类风湿关节炎。"},{"q":"胶体金用于免疫电镜的优点是","o":["可用于疾病的快速诊断","可用于对组织抗原的定量检测","反应不受酸碱度影响","较其他标记物更敏感","可以用不同大小的颗粒对样本进行多重标记"],"a":4,"e":"胶体金电子密度高，不同直径的金颗粒在电镜下形态可辨，故可用不同大小的颗粒分别标记不同抗原，实现对同一样本的多重定位标记。"},{"q":"连接sIgA二聚体的结构是","o":["二硫键","共价键","分泌片","J链","铰链区"],"a":3,"e":"分泌型IgA为二聚体，由两个IgA单体经J链连接，再与上皮细胞产生的分泌片结合；J链由浆细胞合成。"},{"q":"以下哪种疾病是与T细胞无关的缺陷病","o":["DiGeorge综合征","腺苷脱氨酶（ADA）缺陷","嘌呤核苷酸磷酸化酶（PNP）缺陷","重症联合免疫缺陷病","慢性肉芽肿病（CGD）"],"a":4,"e":"慢性肉芽肿病为吞噬细胞NADPH氧化酶缺陷；DiGeorge综合征、腺苷脱氨酶及嘌呤核苷酸磷酸化酶缺陷、重症联合免疫缺陷病均涉及T细胞。"},{"q":"T细胞特异性活化的第一步是","o":["APC对抗原的摄取","APC对抗原的加工和处理","初始T细胞表面的TCR识别APC表面的抗原肽-MHC复合物","IL-2的分泌","CD3的表达"],"a":2,"e":"初始T细胞活化的第一信号由TCR特异性识别APC表面抗原肽-MHC复合物产生，TCR只识别pMHC而不能识别游离抗原；APC摄取加工是前提，IL-2分泌在活化之后。"},{"q":"适于分离纯化T淋巴细胞的方法是","o":["密度梯度离心","亲和层析","电泳分离","FACS","沉降法"],"a":3,"e":"FACS即流式细胞分选术，用荧光标记抗CD3等单抗标记后按表面标志分选，可高纯度分离T细胞；密度梯度离心只能获得混合的单个核细胞。"},{"q":"下列哪种疾病属于重症联合免疫缺陷病","o":["CVID","T-B-SCID","慢性肉芽肿病","白细胞黏附分子缺陷1型（LAD1）","遗传性血管神经性水肿"],"a":1,"e":"T-B-SCID指T细胞与B细胞联合缺失，由ADA、PNP缺陷或TCR/BCR基因重排障碍所致，是最严重的原发性免疫缺陷；CVID为B细胞缺陷，慢性肉芽肿病为吞噬细胞缺陷。"},{"q":"对血源性抗原产生免疫应答的主要场所是","o":["扁桃体","脾","胸腺","小肠派尔集合淋巴结","腹股沟淋巴结"],"a":1,"e":"脾含大量血窦，血源性抗原随血流进入脾，在白髓的动脉周围淋巴鞘和淋巴滤泡中被识别，是机体对血源性抗原产生免疫应答的主要场所。"},{"q":"下列情况属于人工主动免疫的是","o":["通过胎盘、初乳获得的免疫","通过隐性感染获得的免疫","通过注射类毒素获得的免疫","通过注射丙种球蛋白获得的免疫","通过患感染性疾病获得的免疫"],"a":2,"e":"注射类毒素属人工主动免疫，类毒素保留免疫原性而失去毒性，诱导机体产生抗毒素和记忆细胞；经胎盘初乳获得、注射丙种球蛋白属被动免疫。"},{"q":"可直接作用于G＋菌细胞壁、使之溶解破坏的物质是","o":["C反应蛋白","穿孔素","TNF-α","甘露聚糖结合凝集素","溶菌酶"],"a":4,"e":"溶菌酶可水解革兰阳性菌细胞壁肽聚糖，使细菌裂解；C反应蛋白和甘露糖结合凝集素则通过激活补体发挥作用。"},{"q":"用鼠源性抗CD3单克隆抗体防治移植排斥反应，最主要的并发症是","o":["GVHR","HVGR","Ⅰ型超敏反应","自身免疫病","肿瘤"],"a":2,"e":"鼠源性抗CD3单抗对人属异种抗原，可诱导产生抗鼠抗体，再次使用引发Ⅰ型超敏反应；该抗体本身用于抑制T细胞、防治排斥反应。"},{"q":"T细胞介导的超敏反应是","o":["Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅲ型超敏反应","Ⅳ型超敏反应","速发型超敏反应"],"a":3,"e":"Ⅳ型超敏反应由效应T细胞介导，属迟发型，接触变应原后24～72小时发病；Ⅰ、Ⅱ、Ⅲ型超敏反应均由抗体介导。"},{"q":"以下哪项关于γδT细胞的描述是错误的","o":["皮肤黏膜局部参与早期抗感染免疫的主要效应细胞","可通过释放穿孔素、颗粒酶杀伤靶细胞","可通过Fas/FasL方式杀伤靶细胞","有效识别MHC分子呈递的抗原多肽","识别热休克蛋白"],"a":3,"e":"γδT细胞不识别MHC分子提呈的抗原肽，而是直接识别热休克蛋白、脂类、多糖及CD1提呈的糖脂，无MHC限制性。"},{"q":"与免疫调节无关的因素","o":["免疫细胞","细胞因子","补体","神经递质","淋巴液"],"a":4,"e":"免疫调节由免疫细胞、细胞因子、补体及神经内分泌因素（神经递质、激素等）共同构成调节网络；淋巴液是淋巴细胞的运输介质，不参与调节。"},{"q":"单核细胞进入结缔组织和器官后发育为","o":["中性粒细胞","巨噬细胞","肥大细胞","朗格汉斯细胞","间质树突状细胞"],"a":1,"e":"单核细胞在血液停留12～24小时后，经MCP-1等趋化因子作用迁入组织器官，分化为巨噬细胞，也可分化为树突状细胞。"},{"q":"Th1型细胞因子包括","o":["IFN-γ、TNF和IL-12","IFN-γ、TGF-β和IL-12","TNF、IL-4和IL-12","IL-4、IL-5和IL-10","IL-12、IL-10、IL-13"],"a":0,"e":"Th1细胞主要分泌IFN-γ、TNF-α、IL-2等Th1型细胞因子，IL-12与IFN-γ相互促进Th1分化并增强细胞免疫；IL-4、IL-5、IL-10属Th2型。"},{"q":"参与T细胞与APC细胞非特异性结合的APC细胞表面分子有","o":["LFA-1","CD2","CD28","CTLA-4","ICAM-1"],"a":4,"e":"T细胞表面LFA-1和CD2分别与APC表面ICAM-1（CD54）和LFA-3结合，介导两者短暂可逆的非特异性黏附，便于TCR扫描pMHC。"},{"q":"关于CTL杀伤机制，正确的说法是","o":["首先需特异性识别靶细胞抗原肽-MHCⅡ类分子复合物","主要通过分泌IFN-γ和IL-12等细胞因子来杀伤靶细胞","一个CTL细胞只能杀伤一个靶细胞","CTL细胞在杀伤靶细胞的同时也可杀伤自身","CTL细胞可通过FASL/FAS途径诱导靶细胞凋亡"],"a":4,"e":"效应CTL表达FasL与靶细胞表面Fas结合，经死亡受体途径诱导靶细胞凋亡；其识别的是抗原肽-MHCⅠ类分子复合物而非MHCⅡ类。"},{"q":"下列关于IgM的叙述错误的是","o":["是相对分子量最大的一类Ig","激活补体能力比IgG强","血清中IgM含量升高提示有近期感染","是唯一能通过胎盘的抗体","是五聚体"],"a":3,"e":"IgG是唯一能通过胎盘的抗体，借滋养层FcRn主动转运；IgM为五聚体、分子量最大，激活补体能力强，血清IgM升高提示近期感染。"},{"q":"机体的抗肿瘤免疫效应机制中起主导作用的是","o":["T细胞","B细胞","巨噬细胞","NK细胞","红细胞"],"a":0,"e":"特异性T细胞尤其是CTL是抗肿瘤免疫最重要的效应细胞，经穿孔素/颗粒酶和Fas/FasL途径特异性杀伤肿瘤；抗体作用有限，甚至可促进肿瘤生长。"},{"q":"两种以上的细胞因子发挥同样或类似的生物学作用，这种作用的特点称为细胞因子的","o":["多效性","重叠性","协同性","拮抗性","网络性"],"a":1,"e":"两种以上细胞因子对同一靶细胞发挥相同或相似效应称为重叠性；一种细胞因子作用于多种靶细胞产生不同效应称为多效性。"},{"q":"参与淋巴细胞循环最主要的细胞是","o":["αβT细胞","γδT细胞","B1B细胞","B2B细胞","NK细胞"],"a":0,"e":"αβT细胞占外周血T细胞60%～70%、脾和淋巴结T细胞95%以上，是参与淋巴细胞再循环最主要的细胞。"},{"q":"CD4＋Th细胞能识别的抗原是","o":["游离的可溶性抗原","TI-Ag","经APC提呈的抗原","经APC提呈的抗原肽-MHCⅠ类分子复合体","经APC提呈的抗原肽-MHCⅡ类分子复合体"],"a":4,"e":"CD4+Th细胞的TCR识别APC提呈的抗原肽-MHCⅡ类分子复合物，CD4与MHCⅡ类分子结合作为共受体；游离抗原和TI抗原不能被TCR识别。"},{"q":"口服抗原可诱导局部黏膜免疫应答，却引起全身性免疫耐受的现象称为","o":["耐受分离","高带耐受","低带耐受","免疫忽视","免疫抑制"],"a":0,"e":"口服抗原在肠道黏膜局部诱导特异性免疫应答（如产生sIgA），同时抑制针对该抗原的全身性应答，此现象称耐受分离，属口服耐受。"},{"q":"NK细胞通过ADCC作用杀伤靶细胞需要","o":["补体","抗体","细胞因子","MHC分子","TCR"],"a":1,"e":"ADCC中IgG类抗体先与靶细胞表面抗原特异性结合，其Fc段再与NK细胞表面FcγRⅢ结合，激活NK细胞杀伤靶细胞。"},{"q":"AICD是一种高度特异性的生理反馈调节，仅针对被抗原活化并发生克隆扩增的免疫细胞，正确的解释是","o":["是Fas与FasL结合引发的细胞凋亡","免疫细胞组成性表达Fas，活化T细胞大量表达和分泌FasL","FasL通常由活化的T细胞和NK细胞产生","是Fas与FasL结合引发的细胞凋亡；免疫细胞组成性表达Fas，活化T细胞大量表达和分泌FasL","是Fas与FasL结合引发的细胞凋亡；免疫细胞组成性表达Fas，活化T细胞大量表达和分泌FasL；FasL通常由活化的T细胞和NK细胞产生"],"a":4,"e":"AICD由Fas与FasL结合启动凋亡；免疫细胞组成性表达Fas，活化T细胞大量表达并分泌FasL，FasL主要由活化T细胞和NK细胞产生。"},{"q":"Th1细胞产生的对巨噬细胞活化起重要作用的细胞因子是","o":["IFN-γ","TNF-α","IL-2","IL-3","GM-CSF"],"a":0,"e":"Th1细胞分泌IFN-γ，与巨噬细胞表面IFN-γ受体结合，经JAK-STAT1通路激活巨噬细胞，增强其吞噬杀伤胞内病原体的能力，并上调MHCⅡ类分子表达。"},{"q":"重组可溶性IL-4受体能够治疗Ⅰ型超敏反应的可能机制是","o":["降低Th1型细胞的活性","升高Th2型细胞的活性","减少IgG4的产生","减少组胺酶的产生","减少IgE的产生"],"a":4,"e":"可溶性IL-4Rα竞争结合IL-4，阻断IL-4和IL-13的信号转导，抑制Th2细胞分化及B细胞类别转换，从而减少IgE产生。"},{"q":"能刺激红细胞前体细胞增殖分化为成熟红细胞的细胞因子是","o":["IL-1","IL-2","IL-4","IFN","EPO"],"a":4,"e":"EPO即促红细胞生成素，主要作用于红系祖细胞，促进其增殖、分化并成熟为红细胞，临床用于治疗肾性贫血；GM-CSF作用于粒-单系祖细胞。"},{"q":"在Ig类别转化中，能促进IgM转化为IgE的细胞因子是","o":["IL-4","TNF","IL-2","TGF-β","IL-10"],"a":0,"e":"IL-4和IL-13可诱导B细胞发生向IgE的类别转换；TGF-β促进向IgA转换，IL-21驱动IgM向IgG转换。"},{"q":"移植病人使用免疫抑制剂治疗最常见的副作用是","o":["病毒感染和肿瘤发病率增高","超敏反应","原发性免疫缺陷病发病率增高","药物中毒","自身免疫病发病率增高"],"a":0,"e":"免疫抑制剂抑制T细胞等多种免疫细胞功能，使抗感染和免疫监视能力下降，故病毒感染与肿瘤发病率增高是最常见副作用。"},{"q":"与特异性抗原相遇前的成熟T细胞称为","o":["初始T细胞","效应T细胞","细胞毒性T细胞","记忆T细胞","前T细胞"],"a":0,"e":"从未接受过外来抗原刺激、处于G0期的成熟T细胞称初始T细胞，定居于外周免疫器官胸腺依赖区，参与淋巴细胞再循环。"},{"q":"以下关于NK细胞的叙述正确的是","o":["IL-4能增强其杀伤靶细胞活性","细胞表面表达mIg","可通过ADCC机制杀伤靶细胞","来源于骨髓的髓样细胞系","发挥的作用具有特异性"],"a":2,"e":"NK细胞表面表达IgG的Fc受体FcγRⅢA（CD16），与包被靶细胞的IgG结合后经ADCC杀伤靶细胞；其识别不具抗原特异性，不表达mIg，来源于共同淋巴样前体。"},{"q":"以下与Ⅰ型超敏反应的发生有关的是","o":["补体依赖的细胞毒作用","免疫复合物沉积激活补体","特异性免疫无应答性","肥大细胞脱颗粒","CD4＋T细胞介导的炎症反应"],"a":3,"e":"Ⅰ型超敏反应由IgE介导，变应原交联致敏肥大细胞表面FcεRⅠ，触发脱颗粒释放组胺、白三烯等，引起速发相反应。"},{"q":"关于T细胞识别同种抗原机制的正确描述是","o":["宿主的同种异型MHC分子可通过直接和间接途径被T细胞识别","受者T细胞识别移植物APC表面同种异型MHC分子为直接识别","受者T细胞识别移植物APC表面同种异型MHC分子为间接识别","直接识别排斥反应较弱","间接识别需要供者APC参与"],"a":1,"e":"直接识别指受者T细胞直接识别移植物中供者APC表面的抗原肽-同种异型MHC分子复合物，在急性排斥反应中起主要作用；间接识别由受者APC提呈供者MHC肽，见于中晚期及慢性排斥。"},{"q":"在器官移植排斥反应中，最可能存在直接作用的是","o":["Th2细胞与血管内皮细胞","CD8＋T细胞与移植物细胞","TDTH与单核细胞","过客白细胞与巨噬细胞","B淋巴细胞与血管内皮细胞"],"a":1,"e":"受者CD8+CTL可直接识别并杀伤表达同种异型MHCⅠ类分子的移植物细胞，是细胞性排斥的重要效应方式，无需抗体参与。"},{"q":"关于B细胞叙述正确的是","o":["主要参与天然免疫应答","介导细胞免疫应答","在胸腺内发育、分化、成熟","在体液免疫应答中，既是抗原提呈细胞，也是免疫应答细胞","可直接分泌产生免疫球蛋白"],"a":3,"e":"B细胞在TD抗原诱导的体液免疫中既作为APC经MHCⅡ类分子向Th提呈抗原，又作为免疫应答细胞活化后分化为浆细胞产生抗体。"},{"q":"TI-2抗原可以","o":["单独激活B细胞","诱导Ig类别转换","诱导抗体亲和力成熟","诱导记忆B细胞形成","激活Th细胞"],"a":0,"e":"TI-2抗原为细菌荚膜多糖等多重复表位抗原，可广泛交联B细胞mIg而直接激活成熟B细胞和B1细胞，无需Th辅助，一般不诱导类别转换和记忆。"},{"q":"用肺炎球菌荚膜多糖免疫裸鼠，将出现下列哪种情况","o":["无细胞免疫及体液免疫应答产生","有IgM抗体产生","没有特异性抗体产生","有肺炎球菌败血症产生","有IgG抗体产生"],"a":1,"e":"肺炎球菌荚膜多糖属TI-2抗原，无需T细胞辅助即可广泛交联BCR激活B细胞；裸鼠虽缺T细胞，仍可产生IgM而无IgG和免疫记忆。"},{"q":"非专职性APC最重要的属性是","o":["组成性表达MHCⅠ类分子","诱导性表达MHCⅠ类分子","组成性表达MHCⅡ类分子","诱导性表达MHCⅡ类分子","诱导性表达MHCⅢ类分子"],"a":3,"e":"非专职性APC不表达或低表达MHCⅡ类分子，在炎症或细胞因子作用下可被诱导表达，从而获得提呈抗原的能力，这是其最重要属性。"},{"q":"与无能T细胞不活化有关的分子不包括","o":["酪氨酸磷酸酶","BAFF","caspase-3","信号分子降解分子","促使基因沉默的分子"],"a":1,"e":"T细胞无能时上调酪氨酸磷酸酶使激酶失活、表达caspase-3促凋亡，并经信号分子降解和基因沉默阻断活化；BAFF是B细胞存活与分化因子，与T细胞无能无关。"},{"q":"下列疾病中属于免疫复合物型超敏反应的是","o":["过敏性休克","特应性皮炎","新生儿溶血症","链球菌感染后肾小球肾炎","肺出血肾炎综合征"],"a":3,"e":"链球菌可溶性抗原与相应抗体形成中等大小循环免疫复合物，沉积于肾小球基底膜并激活补体，引起免疫复合物型肾小球肾炎，属Ⅲ型超敏反应。"},{"q":"巨噬细胞的功能不包括","o":["吞噬杀伤作用","分泌细胞因子介导炎症反应","处理提呈抗原，启动特异性免疫应答","激活后特异性杀伤肿瘤细胞","免疫调节作用"],"a":3,"e":"巨噬细胞经LPS、IFN-γ活化后可非特异杀伤肿瘤和胞内寄生菌，并具吞噬、抗原提呈、分泌细胞因子和免疫调节功能，但无抗原特异性。"},{"q":"构成TCR特异性识别肽段的是该分子的","o":["胞内区","C区","跨膜区","恒定区","CDR1～3"],"a":4,"e":"TCR的V区含CDR1、CDR2和CDR3，其中CDR3变异最大，直接识别结合MHC分子抗原结合槽中的抗原肽。"},{"q":"B细胞表面的抗原识别受体是","o":["CD19","CD21","CD40","BCR","Igα/Igβ"],"a":3,"e":"B细胞表面BCR即膜型免疫球蛋白，直接识别并结合抗原表位，CD19、CD21为共受体，CD40为共刺激分子，Igα/Igβ负责转导BCR信号。"},{"q":"可募集和活化巨噬细胞的细胞因子不包括","o":["MCP-1","MIP-1α/β","IL-10","IFN-γ","GM-CSF"],"a":2,"e":"IL-10是抗炎细胞因子，抑制巨噬细胞和DC活化；MCP-1、MIP-1α/β为趋化因子，IFN-γ和GM-CSF均可活化或募集巨噬细胞。"},{"q":"致敏CTL细胞杀伤靶细胞时，导致靶细胞DNA裂解的物质是","o":["穿孔素","Fas蛋白","蛋白聚糖","颗粒酶","白细胞介素"],"a":3,"e":"CTL脱颗粒释放穿孔素在靶细胞膜上打孔，颗粒酶经孔道进入细胞，激活凋亡相关酶系统致DNA断裂；Fas/FasL途径亦诱导凋亡。"},{"q":"以下关于抗体与球蛋白关系的描述正确的是","o":["抗体就是免疫球蛋白","抗体就是丙种球蛋白","α球蛋白中没有抗体","β球蛋白中没有抗体","γ球蛋白中只有一种抗体"],"a":0,"e":"抗体的化学本质是球蛋白，具有抗体活性或化学结构与抗体相似的球蛋白被统一命名为免疫球蛋白，故抗体与免疫球蛋白在概念上可互称。"},{"q":"人体淋巴细胞归巢的目的地不包括","o":["骨髓","扁桃体","脾","淋巴结","黏膜相关淋巴组织"],"a":0,"e":"淋巴细胞归巢指其经高内皮微静脉回到淋巴结、脾、扁桃体和黏膜相关淋巴组织等外周免疫器官；骨髓属中枢免疫器官，不是归巢目的地。"},{"q":"MHCⅡ类分子的受体是","o":["CD2","CD4","CD8","CD25","CD28"],"a":1,"e":"CD4是MHCⅡ类分子的共受体，二者结合增强TCR对pMHC的亲和力并辅助Lck转导信号；CD8则结合MHCⅠ类分子的α3结构域。"},{"q":"初始T细胞活化所需的第二信号","o":["由CD3分子转导","由TCR分子胞浆区直接转导","代表适应性免疫应答严格的特异性","由TCR识别APC提呈的抗原肽-MHC分子复合物而产生","是APC与T细胞共刺激分子相互作用的结果"],"a":4,"e":"初始T细胞活化的第二信号即共刺激信号，由APC表面B7与T细胞CD28等共刺激分子对相互作用产生；缺少该信号T细胞不能活化而进入克隆失能。"},{"q":"无血缘关系的同种器官移植，发生移植排斥反应的主要原因是","o":["移植物供血不足","移植物被细菌污染","MHC不匹配","受者免疫功能紊乱","受者体内有自身反应性T细胞"],"a":2,"e":"同种异体移植排斥的本质是受者免疫系统识别供者同种异型MHC抗原，HLA型别差异越大排斥越强，故供受者MHC配型是减轻排斥的关键。"},{"q":"下列哪项与转导激活信号相关","o":["PTK","SHIP-2","ITIM","PTP","SHP-1"],"a":0,"e":"PTK即蛋白酪氨酸激酶，Lck与ZAP-70催化ITAM酪氨酸磷酸化，启动T细胞活化信号转导；ITIM及SHP-1、SHIP-2传递抑制信号。"},{"q":"CTL细胞杀伤靶细胞的特点是","o":["可通过释放穿孔素、颗粒酶杀伤靶细胞","受MHCⅡ类分子限制","无抗原特异性","可通过ADCC作用杀伤靶细胞","可通过分泌IL-10杀伤靶细胞"],"a":0,"e":"CTL脱颗粒释放穿孔素在靶细胞膜穿孔，颗粒酶入胞激活caspase诱导凋亡，也可经FasL/Fas途径杀伤，作用受MHCⅠ类分子限制。"},{"q":"下列物质属于佐剂的是","o":["金黄色葡萄球菌外毒素","青霉素","溶血性链球菌外毒素","卡介苗","人乳头状瘤病毒蛋白"],"a":3,"e":"卡介苗、短小棒状杆菌、脂多糖和GM-CSF属生物性佐剂，可非特异性增强免疫应答；青霉素和细菌外毒素不具佐剂作用。"},{"q":"关于TD抗原正确的是","o":["在胸腺中产生","只有在T细胞辅助下才能产生针对这种抗原的抗体","仅存在于T细胞上","相应抗体在胸腺中产生","对此抗原不产生体液免疫"],"a":1,"e":"TD抗原即胸腺依赖性抗原，须经Th细胞辅助才能诱导B细胞产生抗体，并非在胸腺内产生，也不只引起细胞免疫。"},{"q":"造成遗传性血管神经性水肿的补体缺陷是","o":["I因子基因缺陷","C1q、C1r、C2或C4基因缺陷","C3基因缺陷","B因子基因缺陷","C1抑制因子（C1INH）基因缺陷"],"a":4,"e":"C1抑制物缺陷使C1r、C1s及激肽释放酶持续活化，缓激肽生成增多致血管通透性增高，引起遗传性血管神经性水肿。"}];
